/* 令和4年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r04.committeeSessions.push(...[{"id":"r04-20220303-3","meetingId":"r04-c-budget","date":"2022年3月3日","dateIso":"2022-03-03","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時３３分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を170件整理しています。","topics":[{"id":"topic-01","title":"◯渡辺委員長 ただいまより、予算特別委員会を開会いたします。 それでは、第５号議案、令和４年度品川区一般会計予算","agenda":"◯渡辺委員長 ただいまより、予算特別委員会を開会いたします。 それでは、第５号議案、令和４年度品川区一般会計予算","exchanges":[{"speaker":"新妻委員","kind":"質問・要望","question":"９３ページ、ヤングケアラー支援事業ほか２事業、１２１ページ、医療保健政策包括補助金に関連して、地域猫対策について、この２点、お伺いします。今回、名称がこういう児童虐待というところにあるということで、子ども家庭支援センターが所管するという理解でよろしいか尋ねました。","respondent":"山下子ども家庭支援センター長","answer":"やはり子どもの支援に当たる部門が中心になっていくというところから、子ども家庭支援センターが所管課ということで、今回。なかなかこちらからの発見が難しいといったところから、そういったところの取組みを少しでも進めてまいりたいというふうに考えているところです。","id":"exchange-001"},{"speaker":"新妻委員","kind":"確認","question":"子ども部門の所管ということで、支援が進んでいくということを確認させていただきました。３点ということで、ここに明記されておりますが、３点それぞれについてご説明をお願いいたします。","respondent":"山下子ども家庭支援センター長","answer":"そういった研修を受講していただいた方々に実際に調査をお願いする形で実態の把握に取り組んでまいりたいというふうに考えております。","id":"exchange-002"},{"speaker":"新妻委員","kind":"質問","question":"ちょっと話はかわりまして、次に、東京都の予算に関連してお伺いしたいと思います。東京都の予算の活用というところは、検討されたのか、その点をお知らせください。","respondent":"山下子ども家庭支援センター長","answer":"先月の特別区主管課長会等で、ヤングケアラー支援事業ということで、当予算の反映はタイミング的に難しいところがございました。ヤングケアラー支援マニュアルの作成とかといったところで、そういったマニュアル等の活用につきましては積極的に考えてまいりたいと存じます。","id":"exchange-003"},{"speaker":"新妻委員","kind":"質問","question":"これまで様々なボランティアの方のお声を伺って、この地域猫の件、議会の中でも質問をさせていただきました。そのことを通して、次年度はどこに力を入れていくのか、そのことをまずお伺いいたします。","respondent":"鈴木生活衛生課長","answer":"区のほうでもいろいろな支援をしているのですが、かなり今、負担が増えてきているというところが課題だというふうに言われております。その３点の課題に対して、支援の改善、検討しています。","id":"exchange-004"},{"speaker":"新妻委員","kind":"質問","question":"品川区と東京都と、また他地域との地域猫に関する情報交換の場は、どのような形で行われていますでしょうか。お伺いいたします。","respondent":"鈴木生活衛生課長","answer":"事業内容の説明であったり、その際に各区から意見や要望、その内容についての調整などが行われているというのが現状です。情報が来ると思いますので、そこでまた情報共有をして、しっかりと連携していきたいというふうに考えております。","id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"都議会公明党は、動物保護のシェルターを併設した東京都動物愛護センターを新たに設置するということを昨年の都議選で公約に掲げました。その情報を早く伝えてほしいと思うのですが、こういうこともぜひ要望してほしいと求めましたが、いかがか尋ねました。","respondent":"鈴木生活衛生課長","answer":"都の設置する猫のシェルターですが、情報が来次第、内容を精査して、その上で、よい活用方法であったり、協力体制について声を出していきたいというふうに考えております。","id":"exchange-006"},{"speaker":"横山委員","kind":"質問・要望","question":"配布対象は、区立学校の６年生から９年生と保護者ということでよろしいでしょうか。思春期の子どもたちの目につきやすく、手に取りやすいデザインをお願いしたいというふうに思っておりますが、いかがか尋ねました。","respondent":"鷹箸保健予防課長","answer":"対象別に同じゲートキーパー研修を３回実施していたところですが、３９５名の方に、このゲートキーパー研修を受講していただいております。","id":"exchange-007"},{"speaker":"横山委員","kind":"質問・要望","question":"１０代の妊娠、子どもへの性的虐待によってどのような影響、健康被害があると区はお考えでしょうか。少しずつほかの自治体の動向を研究しながら、性的虐待の予防を進めていただきたいということを要望いたしますが、区のご見解を説明を求めました。","respondent":"山下子ども家庭支援センター長","answer":"その被害を受けてから後々になって出てくるというところに１つ特異な点がございまして、やはり大きな課題であろうというふうに捉えております。","id":"exchange-008"},{"speaker":"横山委員","kind":"質問・要望","question":"小学校、特に高学年や中学校の先生方にも実施していただき、悩み相談の窓口も整えていただきたいというふうに要望いたします。保健所と学校保健が連携して進めていただきたいのですが、教育委員会のお考えについては、教育費のところでお伺いしたいと思っています。","respondent":"高山健康課長","answer":"早い段階から見直していただく２０歳からの健康診査のご案内でありますとか、あるいは子宮がん検診などの啓発なども併せて実施しています。詳細の把握に努めまして、教育部門なども含めまして、この事業の実現性について検討してまいりたいと考えております。","id":"exchange-009"},{"speaker":"横山委員","kind":"質問・要望","question":"４点目に、特別区財政調整交付金についてお伺いいたします。都区の在り方について検討を進めるには、具体的にどのようにすればよいと区はお考えか尋ねました。","respondent":"佐藤企画調整課長","answer":"都区のあり方検討委員会の現状は先ほどお伝えしたとおりですが、都と区で連携して課題解決に向けた取組みを着実に進めているところが１点あります。","id":"exchange-010"},{"speaker":"横山委員","kind":"意見","question":"令和４年度にできることとしては、お互いの立場を捉えにくくしており、歩み寄り以前の課題ではないかなというふうにも思っております。私自身、今後も研究を深めていきたいと考えておりますので、ぜひ議論を進めていただきますよう、との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"品川区のホームページでも、これを掲載してほしいと求めましたが、いかがでしょうか。さらに延期を東京都に求めてほしいと求めましたが、いかがか尋ねました。","respondent":"鷹箸保健予防課長","answer":"次に、濃厚接触者に対する抗原定性検査キットの都からの配布です。現状、もちろん対象の時期が延長されたことは認識していますが、積極的に区民に周知を図っていきたいというふうに考えております。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ検査はどんどん積極的に進めてほしいと求めましたので、ぜひ保健所の立場から進めていただきたいと改めて要望しておきたいと思います。この延長を東京都に求めていただきたいということも申し上げましたので、これもまた改めてお願いしたいと思います。","respondent":"櫻木生活福祉課長","answer":"社会福祉協議会が実施している生活福祉資金のうち、緊急小口資金につきましては６,１４０件、１２億２,２７６万円。１２億６,７１３万円、再貸付けが３,１３５件、１５億９,１０６万円と伺っております。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひこれを出していただきたいのと、６月まで延長になったということも早急にホームページに掲載してほしいと求めましたが、いかがでしょうか。そして、「困ったときには１人で悩まずに、お気軽にご相談ください」と、これを掲げていただきたいと思うのですが、いかがか尋ねました。","respondent":"櫻木生活福祉課長","answer":"暮らし・しごと応援センターが見つけづらいというのは、庁舎の中でどのような形がいいかということで、経理課と相談しながら考えてまいります。就労を条件としないというところは、そのような方法でやっていると認識しております。","id":"exchange-014"},{"speaker":"田中委員","kind":"質問・要望","question":"生活者ネットワークは、２０２０年から感染症の影響による自死の増加について、早急な対応を求めていました。１つ要望したいのですが、リンクの添付などを求めたいのですが、見解を伺います。","respondent":"鷹箸保健予防課長","answer":"研究してまいりますというふうにお答えしたところですが、引き続き非常に重要なポイントなので、取り組んでいきたいというふうに考えております。その在り方も踏まえて、要は、必要な方にすぐ情報が届く形での情報提供に努めてまいりたいというふうに考えております。","id":"exchange-015"},{"speaker":"田中委員","kind":"質問・要望","question":"自殺対策についても、ネットカフェ等にいる方への情報提供は難しいと思いますが、ぜひ進めていただきたいと要望いたします。先ほど教育委員会の協力もあるとのことですが、ぜひそういった教育委員会も含めた体制となっているかを改めて確認させてください。","respondent":"山下子ども家庭支援センター長","answer":"教育委員会との連携ですけれども、先ほど、教育委員会との連携というのはやはり重要であろうというふうに思っております。家庭の次に、教育委員会との連携につきましては、先ほど申し上げました庁内連絡会を含めまして対応に当たってまいりたいと存じます。","id":"exchange-016"},{"speaker":"田中委員","kind":"確認","question":"その当該園のホームページを確認したところ、本ページでの報告は私が見た限りでは見当たりませんでした。影響があったのか、確認をさせてください。","respondent":"若生保育支援課長","answer":"様々ご質問いただきましたが、保護者への説明等に関しましては、これは当然、事業者側のほうで行っているということも聞いてあります。運営方針、取得したほうの、新しい運営母体の事業者のホームページで公開されてあります。","id":"exchange-017"},{"speaker":"田中委員","kind":"質問・要望","question":"不正受給について、項目に記載することぐらいはできたのではないかなと考えますが、区の見解を伺います。保護者への報告状況について伺うとともに、区のホームページ等でも情報提供すべきと考えますが、見解を伺います。","respondent":"若生保育支援課長","answer":"設置者自身が変更になった場合は、あるいは役員の変更、これまで実施しているところに基づいて進めていきたいと考えています。その間、そこからいろいろと区のほうでも対応していたというところで、そこからいち早く文教委員会でご説明をしなければならないというところで。","id":"exchange-018"},{"speaker":"田中委員","kind":"質問","question":"現在、子どもシェルターに関して、区で設置も含めた議論などはあるのでしょうか。都内には、民間が開設している子どもシェルターがありますが、連携などがあるのかも併せて伺いたいと思います。","respondent":"加島児童相談所移管担当課長","answer":"私どもといたしましては、子どもシェルターとの連携の重要性については認識しています。選択肢の１つとして、有用なものと考えておりますので、こちらは調査研究を行ってまいりたいというふうに考えております。","id":"exchange-019"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひそのまま進めてほしいと求めました。その拡充など、暴力に対する認識が広がる工夫を求めますが、見解を伺います。","respondent":"加島児童相談所移管担当課長","answer":"こちらにつきましては、法的背景といたしまして、令和元年６月の児童虐待防止法の改正で、体罰は許されないものであることが法定化されました。児童相談所でもその手法を引き継いでまいりたいと考えております。","id":"exchange-020"},{"speaker":"鈴木（博）委員","kind":"質問","question":"予算書、９１ページ、子どもの新型コロナウイルスワクチン接種事業および新型コロナウイルスワクチン３回目追加接種事業についてお伺いいたします。お尋ねいたします。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"昭和大学の小児担当とも実施をしておりまして、集団接種２会場、荏原保健センターと品川保健センターの会場の下見にもご同行いただきました。今後も定期的に打合せを実施いたしまして、接種を希望する区民の方が少しでも安心して接種できるようにしてまいります。","id":"exchange-021"},{"speaker":"鈴木（博）委員","kind":"質問","question":"誰が、どのように、どこで対処するのでしょうか。区民の安全のため、ぜひ必要と思われますが、区の体制はいかがか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"現在、２４時間対応でございまして、こちらは小児のワクチン接種の副反応に対しても対応できることは確認しております。相談、それから対応してもらえるよう、昭和大学病院の担当医の方と現在調整を進めているところです。","id":"exchange-022"},{"speaker":"鈴木（博）委員","kind":"質問","question":"この１２歳から１７歳の年齢層の区民がワクチン３回目の接種対象でないことの情報提供をしっかりすること、注意喚起などは行われているのでしょうか。この年齢層の３回目の接種は今後どうなるか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長、渡辺委員長","answer":"毎週実施しているウェブ会議等で、既に説明、依頼をしています。１２歳から１７歳の方の追加接種は、仮に希望があったとしても接種をすることはできませんが、体制は構築してまいりたいと考えております。 進めます。次に、湯澤委員。","id":"exchange-023"},{"speaker":"湯澤委員","kind":"質問","question":"私は、９３ページ、ヤングケアラー支援事業についてお伺いいたします。新規でありますので、まず事業概要からお伺いしたいと思います。","respondent":"山下子ども家庭支援センター長","answer":"今回、委員ご指摘のとおり、国の予算でヤングケアラーについての取組みを進めていく方針が示されております。実際に実態の調査把握に臨みまして、そこからどういった支援が望ましいのかを考えていきたいというところから、今回予算立てをしています。","id":"exchange-024"},{"speaker":"湯澤委員","kind":"意見","question":"それから、本人からの相談が多く寄せられていたのはどこなのか。ＳＮＳや電話等もあるかと思いますので、そちらを含めて、以上３点、お知らせほしいと求めました。","respondent":"山下子ども家庭支援センター長","answer":"令和４年２月の実施を予定しておったのですけれども、実際に実施はできておりませんけれども、ヤングケアラーというのはどういう方なのか。","id":"exchange-025"},{"speaker":"湯澤委員","kind":"意見","question":"少なくともそれくらいの方が家族の世話をしている可能性があることを視野に、今後の調査を行っていくべきと考えます。中高生の５割以上がヤングケアラーについて知ることを掲げておりますが、この５割以上という目標値について、お知らせ願いますとの意見を述べました。","respondent":"山下子ども家庭支援センター長","answer":"学校でしたり、児童センターでしたり、そういった子どもたちの目に触れるところにまず配布をいたしまして周知に臨んでまいりたいと考えています。その上で、紙ベース以外のほかの方策につきましても、種々検討を進めてまいりたいと考えています。","id":"exchange-026"},{"speaker":"湯澤委員","kind":"質問・要望","question":"例えば、ケアラー予備軍、そういった方が高齢化やグローバル化が進む今日においては増えていく可能性が高いというふうに考えております。家族が気づかないうちに自分が世話をさせてしまっているというケースもあると思いますので、これまでの取組みもあれば、併せてお知らせください。","respondent":"山下子ども家庭支援センター長","answer":"まずは、実際にヤングケアラーに関わる可能性の高い職種の方々を含めまして研修を実施し、ヤングケアラーについて浸透させていきたいと考えています。","id":"exchange-027"},{"speaker":"湯澤委員","kind":"質問・要望","question":"ぜひスクールカウンセラーとか、そういったケアラーとなるべき人をしっかりとサポートできるような体制をつくってほしいと求めました。これから３年間かけて庁内に連絡会を設置して、品川区においては、しっかりとした支援体制の構築にまずは注力していただきたいと考えております。","respondent":"山下子ども家庭支援センター長","answer":"今お話がございましたとおり、今回、実態調査、把握に臨みました後に、支援の体制を、また支援策を考えてまいりたいと考えております。","id":"exchange-028"},{"speaker":"湯澤委員","kind":"質問・要望","question":"これから実態調査を進めていただくわけですから、しっかりとその辺もお願いしたいと思います。ぜひ周知目標は高く掲げていただき、結果の伴う支援体制の構築を要望いたしまして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"くにば委員","kind":"質問","question":"本日は、１４３ページ、客引き行為等防止過料、１５３ページ、放置自転車等保管料についてお伺いいたします。その取りに来なかった自転車を、区ではどういうふうにしているのか、区内での放置自転車再生リサイクルの仕組みについてお伺いいたします。","respondent":"川口交通安全担当課長","answer":"そのうち処分をして売却をしたものに関しては１,１７５台、また、リサイクルをしたものに関しましては１２７台となっております。後ほどお答えします。","id":"exchange-030"},{"speaker":"くにば委員","kind":"質問","question":"併せて、放置自転車再生リサイクルの仕組みについてもお伺いしたので、答弁をお願いします。","respondent":"川口交通安全担当課長","answer":"失礼いたしました。リサイクル関係の内訳につきましては、社会福祉法人のふれあい作業所に８９台、また、自転車商の組合に３８台をリサイクルとして回しています。","id":"exchange-031"},{"speaker":"くにば委員","kind":"意見","question":"１２７台のみの実績ということですけれども、これは大分減少しているように感じるのですが、なぜこれだけ減少したのかという部分が１点。全てきちんと再生、販売に回すような報告を受ける仕組みになっているのか、説明を求めました。","respondent":"川口交通安全担当課長","answer":"自転車商の組合のほうですけれども、こちらにつきましては、再生している自転車につきまして、全て再生の後、販売という形になっています。","id":"exchange-032"},{"speaker":"くにば委員","kind":"質問","question":"ふれあい作業所のほう、部品取りをしたものを除いては、提供したもの全ての販売を完了したと。身内に譲り渡すことができてしまうと思うのですけれども、今おっしゃった覚書の中で、そこに関して報告をどのようにするのか伺います。","respondent":"川口交通安全担当課長","answer":"再生して販売するというような形のものを対応していますので、お渡しするときには、それぞれある程度の販売が見込めるようなものを対応しています。この減少の原因ですけれども、こちらに関しましては、コロナ禍におけるイベント等の減少等によりまして販売が減っているです。","id":"exchange-033"},{"speaker":"くにば委員","kind":"質問・要望","question":"私が今、答弁を伺った限りの認識では、きちんと販売をしたかどうかの報告書の提出は求めていないというふうに認識いたしました。イベントの際に展示をして販売しているというふうに記載されているのですけれども、現在どのような頻度、タイミングで販売されているのか尋ねました。","respondent":"川口交通安全担当課長","answer":"受入れの台数と販売の台数のみを月別でいただいているところですので、委員ご指摘の部分につきましては、今後の検討とさせていただければと思います。","id":"exchange-034"},{"speaker":"くにば委員","kind":"質問","question":"今お伺いした限りでは、リサイクルは最終的にふれあい作業所を含めて１２７台、年間でリサイクルができたと。そのようなシルバー人材センターへの無償提供と、品川区のシルバー人材センターの活用について、見解をお伺いします。","respondent":"川口交通安全担当課長","answer":"今後、既存でやっている部分に関しまして、例えば台数を増やすとか、そういう要望等があれば、それは適切に対応してまいりたいと思います。","id":"exchange-035"},{"speaker":"くにば委員","kind":"質問・要望","question":"業者の引き払いで海外等に提供したり、ぜひそのリサイクルに対しての意識をさらに強めて、うまく活用していただきたいなと思います。予算計上されているのが５万円、１件相当で、これらの件数や推移に関してもお伺いいたします。","respondent":"森田生活安全担当課長","answer":"件数の推移につきましては、指導は口頭指導なども含まれますので、これについて数量としての集計はとってはおりません。指導に応じず、警告にいき、また、警告から勧告、公表になる、こういった状況ですが、現在までの件数はございません。","id":"exchange-036"},{"speaker":"くにば委員","kind":"質問","question":"ということは、基本的に、これは条例を制定したけれども、条例を制定した段階で相当の抑止効果になって、その後、この特定地区を含めて全くもって客引き等はいなくなった、現在、被害等は全くない、苦情もない状況という認識でよろしいか尋ねました。","respondent":"森田生活安全担当課長","answer":"ですが、警察ではまだ取締りを継続しておりますし、目を光らせておりますので、その点については、全てがなくなっているというわけではございません。取締りも警察のほうで継続してやっておるところです。","id":"exchange-037"},{"speaker":"くにば委員","kind":"質問・要望","question":"今後もしていただきたいというふうに、時間がないので、これは要望します。ちょっと時間がなくなってしまったので、別のタイミングで、また客引き防止条例に関してお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"木村委員","kind":"確認","question":"しかし、せっかく組まれた予算、本区にはないところを目や耳で確認し、よいところは参考にする機会を約２年間ほど失ったことになりました。この事態に対してのご見解を説明を求めました。","respondent":"工藤区議会事務局長","answer":"令和２年度、令和３年度です。やはり新型コロナウイルスの感染拡大、そして蔓延の状況、こういった部分を鑑みて、議会として、やむなく中止の判断をしたです。","id":"exchange-039"},{"speaker":"木村委員","kind":"意見","question":"令和２年、令和３年の２年間、この先をどのように読んでいくのか。コロナの関係で、令和４年度の視察も、関係部署の皆さんのお考えをできればお聞かせほしいと求めました。","respondent":"工藤区議会事務局長","answer":"予算が執行できずに、この２年、残念でしたが、今回、また新たに予算を計上させていただいているところです。議会の中で視察の可能性を検討しまして、速やかに手続きができるように、事務局としてもしっかりと準備をしてまいりたいというふうに考えております。","id":"exchange-040"},{"speaker":"木村委員","kind":"意見","question":"本当にコロナ禍、大変な状況でありますけれども、令和４年度の視察も現在の状況では厳しい状況だと判断をしております。関係部署の皆さんのお考えをまたお聞かせほしいと求めましたし、行政の皆さんはどのように読んでいるのか、お考えを説明を求めました。","respondent":"工藤区議会事務局長","answer":"そして特徴的な施策や取組みを、現地に赴き、区の政策立案や意思決定に反映させるということで重要な議会活動だというふうに考えてあります。そういった意味では、先ほども申し上げましたように、コロナの状況等を見極めながら、また議会の中でその対応を検討していくです。","id":"exchange-041"},{"speaker":"木村委員","kind":"質問","question":"通常はスタンドに設置しているのでしょうか。それとも違うシステムになるのか尋ねました。","respondent":"工藤区議会事務局長","answer":"シルバー人材センターの対応がとれないということで、もう１つ加えまして、区内に３８か所あります。こちらの駅のスタンドのほうに配布をさせていただいている、このような形態をとって区民の皆様にご覧になっていただいているという状況です。","id":"exchange-042"},{"speaker":"木村委員","kind":"質問・要望","question":"約２２万６,８００世帯の発行部数、スタンドに置くということでありますけれども、どれぐらいの部数をスタンドに置くのでしょうか。そして、現在の品川区の状況を知っていただきたいとの思いで発行をしていることと思いますけれども、一定の部数をなぜスタンドに置く必要があるのか。","respondent":"工藤区議会事務局長","answer":"スタンド配布につきましては、新年号のみですが、やはり様々な方に見ていただきたいです。なるべく区議会だより、目に触れていただきたいという考えで、スタンド配布も新年号に関しては行っているです。","id":"exchange-043"},{"speaker":"木村委員","kind":"質問","question":"すみません、そうですか、そこのところを理解しておりませんでした。６回中５回は自宅に配布をする、そして、そのうちの６回目だけが、そのようなところでスタンドに置くということでよろしいか尋ねました。","respondent":"工藤区議会事務局長","answer":"新年号以外の５回分につきましては、ご自宅のほうに確実にお届けしているということで、スタンド配布は現在してございません。","id":"exchange-044"},{"speaker":"松本委員","kind":"質問","question":"私からは、５６ページの特別区財政調整交付金、あと、昨日に引き続きまして、１４１ページのふるさと納税寄附金をお伺いできればと思っています。令和４年度に、これはどういうふうに負担が生じるというか、区が完全に持ち出しというような形になるのかお伺いできればと思います。","respondent":"黒田財政課長","answer":"財調のいわゆる児童相談所の部分ですが、もともとは平成１９年度に、都と区の、当時の協議の中で、区は５５％という形で協議が決定した。","id":"exchange-045"},{"speaker":"松本委員","kind":"質問","question":"令和３年度に開設している港区とか、令和４年度、基準財政需要額に入ってもいないということなのでしょうか。お願いします。","respondent":"黒田財政課長","answer":"設置区の経費については、対応補正という補正の中で、今後の協議の中で引き続き協議をしていく必要があるかというふうに考えてあります。","id":"exchange-046"},{"speaker":"松本委員","kind":"確認","question":"一応確認ですけれども、令和４年度に設置される区の分も、別に割合は変わらない。先行３区以外のところも需要額に入れているのかどうかというところの確認をお願いします。","respondent":"黒田財政課長","answer":"児童相談所に係る経費でありますので、５５.１％の中で、特別区の需要を算定するという中で、需要に算定されておりますが、補正という形ですので、設置していく区が増えてくれば、そこの部分の需要が積み上がってきますから、当然足りないというのが特別区側の主張です。","id":"exchange-047"},{"speaker":"松本委員","kind":"質問","question":"芹澤委員が、追加でやるのもなかなかお恥ずかしいところですけれども、やっぱりどういうふうに増やしていくのかというのは大事だと思っています。こういうことが把握されていないようであれば、把握したほうがいいと思いますが、ご見解を伺います。","respondent":"伊東子育て応援課長","answer":"それと、いろいろと危惧をいただくという中では、ＰＲが重要だというふうに考えております。まだ行き渡らない部分もあろうかと思いますので、これから研究して、広く周知していくことに努めていきたいというふうに考えております。","id":"exchange-048"},{"speaker":"松本委員","kind":"確認","question":"どこで知ったのかというアンケートがなされているかの答弁がなかったので確認したいのと、ツイッターとか、いかがでしょうか。こういう声もありましたというふうにお伝えしていただくと、翌年以降のリピーターも増えると思うのですけれども、いかがか尋ねました。","respondent":"伊東子育て応援課長","answer":"次回の配送に生かすということですとか、寄附者に関しては、また次回も継続していただきたいという思いでの活用をしています。","id":"exchange-049"},{"speaker":"つる委員","kind":"質問・要望","question":"５０ページの特別区民税、関連して９３ページの子ども・子育て支援交付金、１０３ページの就学援助費等について伺っていきたいと思います。令和３年から令和４年の落差は、令和３年を低く見立て過ぎたということがあって大きな差があるというのは伺っているところであるわけですけれども。","respondent":"佐藤計画担当課長","answer":"こちらにつきましては、今年度策定しております総合実施計画の策定に当たりまして、改めて区民の居住意向についてお尋ねしたというものです。","id":"exchange-050"},{"speaker":"つる委員","kind":"質問","question":"前も本会議場で質問しましたけれども、別に区にお金を出してくださいということではなくて、その仕組みを活用してほしいということ。これは公費の部分も含めて、１食当たり幾らになるのか説明を求めました。","respondent":"勝亦学務課長","answer":"維持管理ですとか、調理機器の整備等々を合わせますと、概算で１７億円程度かかってあります。こちらを児童・生徒数、それから１食当たりの食数で割り返しますと、１食当たり大体３９０円から４００円程度になると考えています。","id":"exchange-051"},{"speaker":"つる委員","kind":"質問・要望","question":"そういう考え方でぜひ考えていただきたいなと思いますので、歳入なので、今日はあえて答弁は求めないで要望だけで終わろうかと思います。今、副区長と担当の課長に、ちょっとクッとやっていただいたけれども、歳出のほうで改めてご答弁を求めたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"松澤委員","kind":"質問","question":"５２ページの特別区たばこ税、１４３ページの歩行喫煙防止過料、そして７９ページの獣医衛生手数料についてお聞きいたします。この義務を怠ると罰金があるのか説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"松澤委員","kind":"質問・要望","question":"アンケートをとりまして、どちらも８５％以上が設置の要望、そして８０％近くがよい取組みだというお答えがあります。たばこ税、副流煙の出ない喫煙所の設置を要望しまして、これが実現したことは大変うれしく思っております。","respondent":"森田生活安全担当課長","answer":"多いか少ないかですが、実質のところ、令和２年度の過料は８６件でございまして、前年の令和元年度に比べましてマイナス１９件となっています。２人ないしは３人で、チョッキまたは旗竿などを掲げながらの実施、いろいろな場所のパトロールをしています。","id":"exchange-054"},{"speaker":"松澤委員","kind":"質問","question":"路上喫煙禁止地区というのは、主に、大崎、五反田、武蔵小山、大井町、青物横丁駅周辺であります。そのお考えをまずお聞きしたいのと、始まったばかりですが、現状はどう進んでいるのか説明を求めました。","respondent":"森田生活安全担当課長","answer":"閉鎖しているところの１つにつきましては、これは大崎駅東口の駅前のところですが、今年の４月２０日にコンテナ型喫煙所を開設する予定です。中には前向きに検討していただいているところもありますので、これは求めながら、現状を進めてまいりたいと考えています。","id":"exchange-055"},{"speaker":"松澤委員","kind":"質問","question":"そうすると、路上喫煙禁止地区の広がりというものが見えれば、そういう喫煙所の検討というのもだんだんされていくのではないでしょうか。こういった路上喫煙禁止地区の見直し、そしてまた拡充のお考えがありましたら説明を求めました。","respondent":"森田生活安全担当課長","answer":"現在、指定地区は多数の往来のある駅周辺ですとか、歩行者の喫煙またはポイ捨てなど環境美化の悪化、これらを含めまして地区を指定しています。品川区全体のことも考えながら、効果検証を見ながら調査研究を進めてまいりたいと考えています。","id":"exchange-056"},{"speaker":"松澤委員","kind":"確認","question":"千代田区では、建築確認が不要な喫煙トレーラーがあったり、ＪＴ、そういった企業との連携を考える自治体も出てきております。この喫煙の課題から見えるまちづくりについて、課長のお考えを説明を求めました。","respondent":"森田生活安全担当課長","answer":"今まで進めているところですが、指定地区の中での喫煙所の設置であるとか、こういったものも行っております。喫煙所が設置されることで、今後もそういった３つの取組みをしながら、より快適にできるようなまちづくりができたらと考えています。","id":"exchange-057"},{"speaker":"松澤委員","kind":"質問・要望","question":"区内の他者を思いやる、そういった心を育てる活動というのですか、思いやりを育む活動がまちづくりだと私も思います。さらに住みよいまちづくりを目指しまして、コンテナ型喫煙所の拡充を要望しまして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"安藤委員","kind":"質問・要望","question":"技術的に建て替えが不可能であるということではないと、やりようはあると思うのですけれども、そこら辺を確認させていただきたい。以上、３点伺います。","respondent":"有馬庶務課長","answer":"そういう意味で言えば、どこの学校も、そのほかの学校も必要性はあるだろうというのは考えているところです。それから３番目の建設についての課題ということですが、鮫浜小学校ですとか、技術的にクリアできないということはないかなと考えているところです。","id":"exchange-059"},{"speaker":"安藤委員","kind":"質問・要望","question":"もちろん当事者である子どもなどの声を聞きながら進めるべきで、特定の有力者の意見や政治的思惑で進めるべきものではないと私は言いたいと思います。区教委にも伺いたいのですが、再開発手法で検討しているということはあるのでしょうか、伺います。","respondent":"有馬庶務課長","answer":"冒頭にもお答えしましたけれども、現在、三木小学校の改築の計画の予定はございません。","id":"exchange-060"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺いますけれども、関係者の声を反映する仕組みをどのように担保してきたのでしょうか、伺います。迎える１００周年に向けて、私はつくってほしいと求めましたけれども、いかがか尋ねました。","respondent":"有馬庶務課長","answer":"そういう俎上に上がったときに初めて地元のほうにも説明し、建設準備懇談会というようなものをつくって、そこで協議をします。まずそこで説明会なり、考え方を聞き、そういう場を設けて進めていくということで進めているものです。","id":"exchange-061"},{"speaker":"安藤委員","kind":"質問・要望","question":"区が２３区でも突出して超高層開発に税金を投入して推進している事実について、区はどのように受け止めているでしょうか、聞かせてください。税金の使い方として正しいと思っているのでしょうか、伺いたいと思います。","respondent":"多並都市開発課長","answer":"事業を実施するに当たりましては、地域の方と一緒に考えながら、これまでの事業を一緒に考えながら進めてきたところです。今後の考え方ですけれども、にぎわいの創出など、地域の課題に取り組んで進めてまいりたいというところが区の考えです。","id":"exchange-062"},{"speaker":"安藤委員","kind":"質問・要望","question":"代表質問で、都市計画決定するというのは不当なのではないかと指摘し、改善を求めました。改めて伺いたいと思います。","respondent":"多並都市開発課長","answer":"壁面線といいまして、要するに、そこでハード的な中身についての規制緩和についての検討をしていくというものです。そこについて、その中でやっていくということですので、そういうスキームで段階的にやっていくというふうにご理解いただければと思います。","id":"exchange-063"},{"speaker":"安藤委員","kind":"質問","question":"仮に、税金投入そのものの是非を置いておいたとしても、こういう対応は、区民の理解を到底得られません。そして、明らかに最低限の説明責任すら果たしていないと思うのですけれども、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"この都市計画事業全般的に、まずはその公共性についてを都市計画ということで審議して、その中で決定していくということになります。それを行うべき実施段階になりまして事業という形で、その実施主体が、そういうご理解をいただく必要があるかと思います。","id":"exchange-064"},{"speaker":"渡部委員","kind":"質問","question":"減のものを少しお伺いしたいと思っていて、これはどういう部分で生活安全に資する事業を都が打ち切ったのか教えてほしいのと、途中で打ち切られて。例えば復活してほしい、こういうものをやってほしいみたいなことを区は言えるのか、その辺を聞かせてください。","respondent":"森田生活安全担当課長","answer":"それまでには設置が実質間に合いませんでしたので、補助については、ないという形になります。それと、今後、要望等々があるのかですが、これについては、折に触れて、そういった機会があればお願いしてまいりたいとは思っております。","id":"exchange-065"},{"speaker":"渡部委員","kind":"質問・要望","question":"事あるごとにといいましょうか、何か機会があるときにとおっしゃっていただいたので、何とか東京都のほうに復活の要望はしていただきたいと。この１２５ページの産業経済費補助金の中で、ここも冒頭の説明で２０何％減った、それがなくなったから減ったということだったのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"産業経済費補助金です。西大井創業支援センターの工事などがありまして、一定、工事等が終わりましたので減額になったです。","id":"exchange-066"},{"speaker":"渡部委員","kind":"確認","question":"りんかい線のことを、私、何回かいろいろ伺っている中で、また今日もお伺いしたいと思います。分かる範囲でお聞かせいただけますか尋ねました。","respondent":"鈴木都市計画課長","answer":"昨年の８月には、評価書案についての説明会も開催されているというところで、羽田空港アクセス新線のほうは聞いているところです。それから、臨海部に向かう臨海部ルートにつきましては、りんかい線も状況的には関係してくるのかなです。","id":"exchange-067"},{"speaker":"渡部委員","kind":"質問","question":"今は何だってできる時代になっているわけですから、人が住むとかではなくても、いろいろなことが仕掛けられるわけです。そういう夢のあることを、これから時間をかけて目がけて、そろそろやっていってほしいなと思うのですけれども、課長、考えがあれば説明を求めました。","respondent":"鈴木都市計画課長","answer":"昨年の１２月にも、意見交換を行いまして、新駅のお話を区のほうでもさせていただいたところです。やはり一番設置が可能なところは、ほかの２ルート、しっかり検討して動きをつくっていきたいです。","id":"exchange-068"},{"speaker":"渡部委員","kind":"質問・要望","question":"各種お打合せといいましょうか、話合いはできているのだなというのを確認させていただきました。やっと開通するというような話ですから、何か楽しいですよね、そういうことで話合いができるというのは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"こんの委員","kind":"確認","question":"１１５ページ、１３３ページ、教育支援体制整備事業費補助金からお伺いしたいと思います。基本的なところから確認しますが、そもそもこの事業は、どのような経緯で、どのようなねらいと意義を持って実施されているのか説明を求めました。","respondent":"竹田住宅課長","answer":"簡単に内訳をご説明しますと、バリアフリー関係が４１件、その他工事が１０件です。ご好評をいただいておりまして、この事業を通じて、区内の事業者の方にも使いやすいということで活用していただいているところです。","id":"exchange-070"},{"speaker":"こんの委員","kind":"質問・要望","question":"私が想像したとおりといえるのでしょうか、一定以上のニーズがある事業だなというところを確認させていただきました。１件でも多く対応する姿勢が欲しいなと思いますし、補正予算を組むなども１つの手ではなかったかと考えますが、区のご見解を説明を求めました。","respondent":"竹田住宅課長","answer":"令和２年度につきましては、期限いっぱいまでお受けして、予算を残して終了という形になってあります。できる限り需要を正確に把握して予算化していきたいと考えています。","id":"exchange-071"},{"speaker":"こんの委員","kind":"質問・要望","question":"令和２年は２月９日、令和３年は１２月２４日と、年度によって申請の件数は当然変わってくるだろうというところですか。ですので、区民サービスの公平性の観点からも、積極的な事業展開を要望するところですが、区のご見解を説明を求めました。","respondent":"竹田住宅課長","answer":"新年度につきましては、令和３年度に比べまして３００万円ほど増となっております。今後も適切な予算化に努めていきたいと考えております。","id":"exchange-072"},{"speaker":"こんの委員","kind":"質問・要望","question":"ぜひ積極的に補正予算などを組んでいくという考え方も持っていただきながら事業展開をお願いしたいと要望で終わります。高齢社会対策包括補助金は、この事業でどのように使われていくのか尋ねました。","respondent":"菅野高齢者地域支援課長","answer":"こちらについて、今年度は、１１コースを予算化しておりましたが、来年度は２２コースに倍増する予定です。定員上は１３２人というところでしたが、それらの倍増もしくは新設の教室によりまして、５０４人分の教室の定員の確保を予定しております。","id":"exchange-073"},{"speaker":"こんの委員","kind":"質問・要望","question":"そうすると、すみません、しながわシニアネットがしてくださっているコースが、１１コースから倍で２２コースということですか。そこを確認させてください。","respondent":"菅野高齢者地域支援課長","answer":"残りの２４０人分についてが民間事業者によるスマホ教室ということになります。こちらにつきましては、しながわシニアネットに委託しているスマホ教室がこちらの補助金の対象となっておりますので、この分が含まれております。","id":"exchange-074"},{"speaker":"こんの委員","kind":"質問・要望","question":"なので、そして社会参加促進、こうしたことのために一人も取り残すことのないように展開してほしいと考えるところです。その点いかがか尋ねました。","respondent":"菅野高齢者地域支援課長","answer":"相談回数は週１回、約３会場４８週で１４４回を予定しているところです。東京都のスマホ教室を実施させていただいたり、あとはゆうゆうプラザで指定管理者が自主事業としてスマホ教室などを実施しておりますので。","id":"exchange-075"},{"speaker":"こんの委員","kind":"質問・要望","question":"今ご答弁いただきましたように、他の事例も見て、また東京都のものも活用するという考え方、確認させていただきました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"小芝委員","kind":"質問","question":"私からは、７７ページの戸籍証明手数料、手数料全般について、また６１ページのなぎさ会館の活用についてお伺いいたします。手数料全般について伺います。","respondent":"木村戸籍住民課長","answer":"これはマイナンバーカードがコンビニで使えると認知されている方々がかなり増えてきているという印象を率直に思っております。もともとマイナンバーカードの普及を進めるという意味合いも込めまして、努めてコンビニ交付の普及を図ってまいりたいというふうに思っております。","id":"exchange-077"},{"speaker":"小芝委員","kind":"質問","question":"マイナンバーカードを持ってはいるけれども、窓口で申請するという方も多分いらっしゃると思います。次回申し込んだときには、こういったマイナンバーカードをぜひお使いくださいとか、そういったアナウンスとかというのはされておるのか尋ねました。","respondent":"木村戸籍住民課長","answer":"現在、窓口では、ポスター掲示でありますとか、ご案内をさせてはいただいておるところです。もうそこですぐというような形をとっていきたいというふうに考えて、今、準備をしておるところです。","id":"exchange-078"},{"speaker":"小芝委員","kind":"意見","question":"２倍以上に伸びて、４割５分ぐらいだと思いますけれども、そのぐらいまで普及されているかなです。ホームページ等でまた分かりやすく表示してほしいと求めましたが、その辺、お考えを説明を求めました。","respondent":"木村戸籍住民課長","answer":"先日、それぞれの証明書発行のページに、全面にコンビニを出していくというような形のリニューアルもしています。引き続き、いろいろな広報媒体、ＳＮＳも使いまして、お知らせをしてまいりたいというふうに思っております。","id":"exchange-079"},{"speaker":"小芝委員","kind":"質問","question":"このサービスを行っているのは２３区ではまだ少なくて、中野区のみでありまして、もっともっと評価されてしかるべきかなとは考えております。始まってまだ間もないサービスですが、今のところの状況だとか、何か反応とかがありましたら説明を求めました。","respondent":"木村戸籍住民課長","answer":"委員ご指摘のとおり、まだ認知がなかなかされていないというところもあると思いますが、日に１桁台というような形で、今、推移をしています。今後も、そちらも含めましてＰＲに努めてまいりたいと思います。","id":"exchange-080"},{"speaker":"小芝委員","kind":"質問・要望","question":"午前中に考えていた質問を切り替えなければいけないなと思いまして、またさらに高くなると思いますので、ぜひ要望させてほしいと求めました。そういったことも何か検討されておるのかどうかを含めて教えてほしいと求めました。","respondent":"木村戸籍住民課長","answer":"国税のほうの納税証明書については、委員ご指摘のとおり、画面にデータとして証明書が送られてくるという形になったことは認識しておるところです。","id":"exchange-081"},{"speaker":"小芝委員","kind":"質問","question":"続きまして、６１ページのなぎさ会館の活用についてお伺いいたします。その低下した稼働率を受けて、どのように評価されているのか、２点について説明を求めました。","respondent":"木村戸籍住民課長","answer":"それから、密を防ぐために、１日２組ご利用のところを１組にしたというところもあります。利用状況については以上です。","id":"exchange-082"},{"speaker":"小芝委員","kind":"質問","question":"３年前の夏から、なぎさ会館の一角に授乳室のスペースを設けているというふうに聞いておりますけれども、あれから３年がたちまして、こちらの授乳室の利用状況をまず教えてもらってもよろしいか尋ねました。","respondent":"木村戸籍住民課長","answer":"授乳室を開設いたしまして、のぼりも立てまして宣伝しておるところですけれども、実際のご利用はほとんどないような状況です。","id":"exchange-083"},{"speaker":"小芝委員","kind":"提案","question":"利用料金は主に３つのパターンから成り立っていまして、通夜がなく告別式、火葬のパターンが増えているとも聞いております。そういった場所をとらないスポーツも運用できるのではないかなと提案したいと思いますが、お考えがありましたら、お知らせくださいとの意見を述べました。","respondent":"木村戸籍住民課長","answer":"そういう集会施設、いろいろ検討してまいったところではありますが、なかなか難しいなというところ。そういう部分も考えて、私どもも認識しておるところですので、引き続き研究を続けてまいりたいというふうに思います。","id":"exchange-084"},{"speaker":"小芝委員","kind":"提案","question":"しながわ百景の１つであります、立会川の雨水放流管の工事を含めて、やはりこのなぎさ会館の周りの景色も大分広がってくると思います。私が先ほど提案した以外のものも残されていると考えますので、ぜひ今後とも、なぎさ会館の積極的な活用を促したいことを要望しましてとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-085"},{"speaker":"のだて委員","kind":"質問","question":"５０ページから始まる歳入の特徴について、１１１ページの障害者福祉手当等支給事務に関連して、心身障害者医療費助成について伺います。納税義務者が減っているのに、特別区民税が過去最高額なのはなぜか、理由を伺います。","respondent":"提坂税務課長","answer":"東京都の完全失業率は全国の２.８％を上回っているものの、そのようなもろもろの事情を見込んで、令和３年度の当初見込みの納税義務者よりも。","id":"exchange-086"},{"speaker":"のだて委員","kind":"質問","question":"高所得の５０代の方が増えているというところ、納税義務者が減ったということではないかというふうに思うのですが、いかがでしょうか。一方、所得が上がっている区民もいるというところで、この格差と貧困が拡大しているのではないかと考えますが、いかがか尋ねました。","respondent":"提坂税務課長","answer":"失業している方ももちろんいらっしゃいますけれども、様々な経済支援策の下支えの効果等で、失業者数も徐々に減っていくと思われます。納税義務者のうち総所得７００万円超の方の割合が４３％を占めまして、全所得層に対する税額の比率の約５割を占めているという実情もあります。","id":"exchange-087"},{"speaker":"のだて委員","kind":"質問・要望","question":"過去最高の歳入を福祉の増進に活用していただきたいと思うのですが、いかがでしょうか。そのためにも区民の実態を把握して予算編成に反映していくべきだと思いますが、いかがか尋ねました。","respondent":"提坂税務課長","answer":"普通徴収の場合は４期に分けてお支払いいただくのですが、生活が苦しくてなかなか納期どおりに払えないというご相談もたくさんいただいております。徴収猶予のご相談とか、その辺をじっくりと提案させていただいて、納付完結へ向けた対応をさせていただいているところです。","id":"exchange-088"},{"speaker":"のだて委員","kind":"質問・要望","question":"特別区財政調整交付金、これも前年度比３０億円増、７.７％増ということで、４１８億円と、これも過去最高水準ではないかと思います。コロナで打撃を受けている業種とは何か、Ｋ字回復ということは、事業者にも格差が広がっているのではないかと思いますが、いかがか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"Ｋ字回復についてです。同じ業種の中であっても、うまく乗り越えられているところと、なかなかうまくいっていないところがあるです。","id":"exchange-089"},{"speaker":"のだて委員","kind":"質問","question":"つまりは、格差が広がっているということではないかと思いますけれども、改めて伺いたいと思います。その打撃を受けている業種についても伺ったので、ご答弁ほしいと求めました。","respondent":"遠藤商業・ものづくり課長","answer":"特に融資という部分では、引き続き来年度におきましても、そのような形で支援していきたいと考えています。〔「業種」と呼ぶ者あり〕 業種につきましては、先ほど言いましたとおり、対面サービスという形になりますので、例えば飲食業とか、宿泊業というようなものが中心になるかと考えています。","id":"exchange-090"},{"speaker":"のだて委員","kind":"質問","question":"この際、打撃を受けている業種への支援を強めていくべきだというふうに思いますけれども、いかがでしょうか。区独自の金額の上乗せや、対象拡大を実施すべきだと考えますが、いかがか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"特に痛手を受けているというところで、借り換え資金、そういう部分で事業者の支援をしていきたいというふうに考えておるところです。事業復活支援金、金額等を決めているところですので、私どものほうでの上乗せ助成等は考えておりません。","id":"exchange-091"},{"speaker":"のだて委員","kind":"質問","question":"この間、コロナが２年間続いております。こうした中で、そうしたところに直接支援をしていくということが必要ではないかと思いますが、いかがか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"繰り返しになりますけれども、現在のところは、事業復活支援金等、国の補助金等への上乗せ助成、直接支援については考えていないところです。","id":"exchange-092"},{"speaker":"のだて委員","kind":"質問・要望","question":"次に、心身障害者医療費助成、いわゆるマル障の拡充について伺います。この助成対象の拡充を東京都に求めてほしいと求めましたが、いかがか尋ねました。","respondent":"松山障害者福祉課長","answer":"区といたしましては、この制度の趣旨に鑑みまして、対象者の拡大を、現在のところ、東京都に求めていく考えはございません。しかしながら、お困りの方については、様々な医療制度がありますので、その中で十分に相談に応じてまいりたいとも考えております。","id":"exchange-093"},{"speaker":"のだて委員","kind":"質問・要望","question":"区は求めないというお話でしたけれども、この対象にならない知的３度の方ですとか、やはり病気になりやすいという状況があります。やはり２級などになっている方は仕事ができないという状況ですので、やはり負担感が強いという状況になっておりますので、いかがか尋ねました。","respondent":"松山障害者福祉課長","answer":"そういったお困りの声につきましては、東京都には情報を提供しますが、制度全般につきましては、東京都全体の制度の実態を鑑みて、改正するかどうかを決めるものと考えております。","id":"exchange-094"},{"speaker":"のだて委員","kind":"質問・要望","question":"全体と言いますけれども、ぜひ区としてもそこは求めてほしいと求めました。東京都との協議に当たり、１８歳までの医療費助成について、所得制限なしで自己負担をなくすよう求めてほしいと求めましたが、いかがか尋ねました。","respondent":"伊東子育て応援課長","answer":"東京都は、細かいことをまだ示しておりませんので、その話を聞きながら進めていきたいというふうに考えております。","id":"exchange-095"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ所得制限なしで、負担もなく無料でできるようにしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-096"},{"speaker":"西本委員","kind":"質問","question":"そして、今後の公立保育園の方向性、それから将来像は、どういうものなのでしょうか。その考え方と、それから、子どもの自立の観点から見て、児童センターの役割について、お考えをお聞きします。","respondent":"初貝保育教育運営担当課長、廣田子ども育成課長","answer":"民営化は、目的としましては、そういったものを提供して保育の質の維持と向上を目指していくというような目的を持っているものです。ただ、規模によって様々ありますので… ０歳から１８歳を対象とするというところで、横のつながりのための重要な役割も、今はそういうところを認識しています。","id":"exchange-097"},{"speaker":"西本委員","kind":"質問・要望","question":"なぜ民間でなければできないのですか。その関わり方についてお聞きしたいと思います。","respondent":"立木保育課長、廣田子ども育成課長","answer":"品川区の保育は、委員がおっしゃるとおり、日本全国に誇れる保育だと考えています。公立保育園は、数の検討というのは必要になってくると思いますが、そういうような役割の中で民間委託ということも１つ進めているところです。子どもにとって食、親が一番よく知っているということで、食に対する大切さというのは、区として認識しているところは現在も変わりございません。","id":"exchange-098"},{"speaker":"西本委員","kind":"質問","question":"公立保育園の皆さん、頑張ってやってきているわけですから、何をしなければならないのか、公立のやるべき仕事、保育をしっかりと突き詰めてください。やっぱり福祉が必要なところもありますので、お願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-099"},{"speaker":"たけうち委員","kind":"質問・要望","question":"これはちょっと単純な確認ですけれども、その辺のところ、影響があったかどうかということを教えてほしいと求めました。その辺のことを教えていただきたいのと、別のところで実態把握調査経費というのが、これはそれぞれどう違うのかということを説明を求めました。","respondent":"提坂税務課長、中山会計管理者、山下子ども家庭支援センター長","answer":"今後の令和５年度、令和６年度の税金の推移ですが、これを一刻も早く収束させるということが最優先課題かと思います。… 会計管理室のほうに説明も受けておりますし、みずほ銀行のかなり上のほうの方をお呼びして説明を求めるとともに、厳重注意をしているところです。… 現時点でどこというふうに決めているところではございませんで、今後、そちらは委託先の契約ということで進めてまいりたいと考えております。","id":"exchange-100"},{"speaker":"たけうち委員","kind":"質問・要望","question":"すぐどうのこうのということではないのですけれども、安心の管理をやっていただければなと、これは要望です。それから、実態把握調査委託、これは入札か何かするのか尋ねました。","respondent":"佐藤企画調整課長、山下子ども家庭支援センター長","answer":"区といたしましては長期基本計画で１０年後の目標を明確に定めまして、総合実施計画の策定もしておりまして、また実績を伝えていくというところ。もう一方で、そういったものにもきめ細かく対応して… 先行の自治体の事例等を研究しながら、仕様書等を整えまして入札という形になるかと思いますけれども、契約ということで進めてまいりたいと考えています。","id":"exchange-101"},{"speaker":"たけうち委員","kind":"質問","question":"今の調査委託のほうは、もうとにかく予算が決まったら速やかに対応していただいて、なるべく早いスピーディーな対応をお願いしておきたいと思います。やはり働き盛りの比較的税収の高い方たちにどうやって品川区に定住してもらう、もう１回、お考えを説明を求めました。","respondent":"佐藤企画調整課長","answer":"ややその上というところと、あと就労世帯、生産年齢人口の増も区としてしっかりと見ていかなければならないと思っています。品川区は質素倹約で健全財政を築いておりますので、そういった強みを生かして、今後もしっかりと様々な事業を展開していきたいと考えています。","id":"exchange-102"},{"speaker":"西村委員","kind":"提案","question":"９５ページ、すまいるスクール運営費、９７ページ、ネウボラネットワーク経費、順不同で伺ってまいります。そこで、区民ニーズの高いドゥーラ利用の利便性をより高めるために、確認と提案をしますとの意見を述べました。","respondent":"山下子ども家庭支援センター長","answer":"産後の家事・育児支援、ドゥーラの利用についてのご照会です。児童センターの事業等々で、やはりドゥーラの予約が取りづらい、なかなか見つからないといったようなお声は耳に入っているところです。","id":"exchange-103"},{"speaker":"西村委員","kind":"質問・要望","question":"今後は、ベビーシッターによる一時預かり利用支援のご案内を必ずしてほしいと求めましたが、いかがでしょうか。実際に、ドゥーラからベビーシッターへの移行希望が多いと区内ドゥーラより伺っております。","respondent":"山下子ども家庭支援センター長","answer":"こちらのマッチングが何とかならないかというところで取り組んでいるところですけれども、今後も引き続き検討してまいりたいと考えています。今、周知が必要かと考えておりますので、部内保育支援課とも協力しまして進めてまいりたいと考えております。","id":"exchange-104"},{"speaker":"西村委員","kind":"質問","question":"それぞれの予約可能日が分からず、利用者が登録ドゥーラ１人ずつに、メールアドレスをコピーして希望要件や日時を送っていると伺いました。これは役所で打ち直しておられるのかどうか伺います。","respondent":"山下子ども家庭支援センター長","answer":"委員からご説明がありましたように、外部の力ですけれども、マッチングがうまくはまらないかという取組みをしたところです。３者が関係するところから、技術については進展しておりますので、そういったところについては引き続き模索してまいりたいと考えております。","id":"exchange-105"},{"speaker":"西村委員","kind":"確認","question":"人数確認のために、ある程度利用の予定をいただいていると伺い一定の理解を示しておりますが、イレギュラーな申込みがどの程度あるのか。昨年度との比較など、実数でなくても構いませんので状況を伺います。","respondent":"廣田子ども育成課長","answer":"保護者の皆さんもコロナの対応に大分なじんできたというか、人数については、ある程度の一定人数で落ち着いているところです。そちらについて少しずつ可能な範囲で入れていくというところを、今、準備しています。","id":"exchange-106"},{"speaker":"西村委員","kind":"質問・要望","question":"保護者にも自粛することや密への理解が浸透してきているのではないかというふうに伺いたかったのですが、例えば、そのような状況であれば。実際に保護者の方々に伺いますと、その周知も含めましてご検討ほしいと求めましたが、状況も含めてご見解を説明を求めました。","respondent":"廣田子ども育成課長","answer":"すまいるスクールは全学年を通して利用されますので、あと何人利用できますという数字を示したりするのはなかなか難しい状況にあります。様子を見ながら受け入れていくというふうなお答えしかなかなかできなくて申し訳ないですけれども、ぜひご相談をいただければと思います。","id":"exchange-107"},{"speaker":"西村委員","kind":"質問・要望","question":"区立学童では費用も大幅に民間と異なるため、死活問題になるという自治体があると伺っております。一概に今のお母さんたちが楽をしたいからお弁当を要望しているのではないというふうに思っています。","respondent":"廣田子ども育成課長","answer":"急なご利用に関しましても、特段突き詰めて事情をお聞きするわけでなく、お困りということであれば預かっているところです。食の支援のお話ですけれども、他の自治体の状況について、今後、調査をしていきたいと考えているところです。","id":"exchange-108"},{"speaker":"西村委員","kind":"質問・要望","question":"先ほど、つる委員もおっしゃっておられましたけれども、お母さんたちの声、全てのお母さんがおっしゃっているとは思いませんが、やはり多くの声が区民の方たちの声で届いておりますので、ここはしっかりと聞いていただきまして、行政のサービスに取り入れてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-109"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは、９１ページの国庫補助金の個人番号カード交付事務費補助金から、マイナンバーカード、そして、デジタル化について伺いたいと思います。区の認識を改めて伺いたいのと、マイナポイントの第二弾も使ってやっているのに、伸びない理由は何だとお考えか伺います。","respondent":"宮澤情報推進課長","answer":"令和３年１２月、マイナポイント事業の目的の１つにマイナンバーカードの普及がありますが、その目的に沿って普及が進んでいるという認識です。第二弾につきましては、１月から始まっている状況ですので、今後の動向は注視していくです。","id":"exchange-110"},{"speaker":"石田（ち）委員","kind":"質問","question":"伸びない理由も伺ったのですけれども、これから伸びてくるだろうというふうに見ているということでしょうか。ＤＸ推進計画は、地方自治の本旨も、住民福祉の増進を図るという立場も欠如していると思いますけれども、区の見解を伺います。","respondent":"宮澤情報推進課長","answer":"これらの動きを受けまして、行政としては、デジタル化を進めていく、その中には区民の利便性の向上であったり、業務の効率化を目的としております。","id":"exchange-111"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"地方自治の発展や住民福祉の増進のために、この技術を有効に活用することこそ求められていると。そして住民福祉の増進を図るという立場で、ぜひ進めてほしいと求めましたけれども、いかがか尋ねました。","respondent":"宮澤情報推進課長","answer":"マイナンバーの仕組みとしまして、各行政機関等で情報連携を進めております。ただ、各団体等で持っている情報を必要に応じて情報連携しているという形になってあります。","id":"exchange-112"},{"speaker":"大沢委員","kind":"質問・要望","question":"全体的なものを伺う前に、ぜひとも今日、黒田財政課長とお話させていただきたいなと考えています。去年の予算書にはありまして、今年は見当たらないのですけれども、これはどうなってしまったのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"ものづくり創造センターですけれども、こちらにつきましては、今年度で貸出しは全て終了という形になりまして、来年度につきましては、情報推進課のほうで使うという形になりますので、使用料としては発生しないという形になっているところです。","id":"exchange-113"},{"speaker":"大沢委員","kind":"質問","question":"ものですから、活用されたのでしょうか。活用せずして転用させたと、そこが大事なところで、お願いします。","respondent":"遠藤商業・ものづくり課長","answer":"これまではいわゆる事業者に使っていただいたところですが、ほかの施設などもできているところで、来年度につきましては、一応、別のほうに貸すという形で進めているところです。","id":"exchange-114"},{"speaker":"大沢委員","kind":"意見","question":"ちょっと答えがかみ合わなかったけれども、結構です。どのような指導、どのような助言をされているのか、ご披露くださいとの意見を述べました。","respondent":"黒田財政課長","answer":"受益者負担の適正化の検討、依命通達により、各所管のほうにお示ししています。","id":"exchange-115"},{"speaker":"大沢委員","kind":"質問","question":"本日は、使用料、手数料ですけれども、これ、歳入全般ということにもなりますので、今、３項目おっしゃっていましたけれども、最も的確な回答は、この依命通達、歳入に関する事項で、これを徹底させるべく助言、指導していると、このような考え方でいいのか尋ねました。","respondent":"黒田財政課長","answer":"予算編成に関する基本方針ということを依命通達でお示ししておりますので、ここでお示ししている項目が基本的な予算編成の歳入確保の考え方ということで、各部局のほうに通達しているものです。","id":"exchange-116"},{"speaker":"大沢委員","kind":"質問・要望","question":"そうなると、４月になると、今度は執行に関する依命通達が出てくるのですけど、これについては、どのように、まだちょっと早いですけれども、お話しできる範囲で執行に関する依命通達をお話しほしいと求めました。","respondent":"黒田財政課長","answer":"予算はあくまでも計画として見込みを立てているものですので、その見込みを下回らないように、執行の依命通達の中でも考え方としては持っていくものかというふうに思ってあります。","id":"exchange-117"},{"speaker":"大沢委員","kind":"質問","question":"そこで、歳入全体ということですけれども、先ほど来、お話がありましたように、令和４年度の予算編成、過去最大のものとなっております。約１,８９１億円ということになっておりますけれども、そこらの予想されるマイナス要因について、まず伺いたいと思います。","respondent":"黒田財政課長","answer":"予定どおりに活動できないということがあれば、当然予算を執行できないことがありますので、そういったところがマイナスの要素になろうかというふうに考えてあります。","id":"exchange-118"},{"speaker":"大沢委員","kind":"質問","question":"例えば、使用料ですか、これ。この約４５億円という金額、このようなものを勘案して、どのように積算をされたのか説明を求めました。","respondent":"黒田財政課長","answer":"各所管課のほうで管理している施設の来年度の工事の予定ですとか、使用の予定などを勘案して、このぐらいの利用があるだろうというところを見込んで要求があり。","id":"exchange-119"},{"speaker":"大沢委員","kind":"提案","question":"予算ですから、消費者心理でしょうか、提案をさせる。見込みというか、考えがあったら説明を求めました。","respondent":"黒田財政課長","answer":"まず区として率先して行いまして、いろいろな活動が活発化してくれば、機運も醸成されてくるのではないかというふうに考えてあります。","id":"exchange-120"},{"speaker":"大沢委員","kind":"質問・要望","question":"なぜ冷え込んでしまったかというと、そういう危惧感からこの質問を最後にさせていただきましたので、あるいは４５億円をしっかりと有効に活用できるように事業を行ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-121"},{"speaker":"若林委員","kind":"質問・要望","question":"１４３ページの歩行喫煙防止過料について伺いたいと思います。そこについて、今のご答弁も含めて、何かコメントがありましたら、お聞きしたいと思います。","respondent":"森田生活安全担当課長","answer":"指定喫煙所が閉鎖していることもありまして、取締り、また指導が多くなっているものというふうに認識しております。取締りは続けてまいりますが、以前よりは少なくなっているということで、私のほうも印象を聞いておるところです。","id":"exchange-122"},{"speaker":"若林委員","kind":"質問・要望","question":"根拠というのはどういうところにあるのか、要綱上か、どういう位置づけになっているのかを確認したいと思います。これを確認させてほしいと求めました。","respondent":"森田生活安全担当課長","answer":"これであると、違うところにまた喫煙者が行ってしまうというような、いろいろな状況もありまして、いろいろと検討しています。いずれにしましても、吸う方、吸われない方も住みやすいまちづくり、または喫煙所をつくっていきたいと考えています。","id":"exchange-123"},{"speaker":"若林委員","kind":"質問・要望","question":"９か所、コンテナ型というふうに要望しますけれども、こういう取組みをしっかりとお願いいたします。時間がありませんので、要望としますので、来年度もどうぞ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-124"},{"speaker":"芹澤委員","kind":"提案","question":"ぜひ、より障害者雇用をしていっていただきたいという思いで、幾つか提案します。これは以前もお伺いしたのですが、自宅で勤務できるわけですから、移動のハードルがぐっとなくなるとの意見を述べました。","respondent":"崎村人事課長","answer":"委員からありましたような基準の作成は必ず必要になってくるというふうに考えておりますので、現在、試行しながらルール化についても検討しています。会計年度任用職員を含めて、障害者雇用の促進については、引き続き検討していきたいというふうに考えております。","id":"exchange-125"},{"speaker":"芹澤委員","kind":"質問・要望","question":"やはりこれ、模索はしていくべきだなと思っていますので、そちらも併せてご見解をほしいと求めました。ご見解を説明を求めました。","respondent":"崎村人事課長","answer":"先ほど説明が不足していた部分があるのですけれども、区では、各課の印刷ですとか封入等の軽作業を引き受けるという業務支援室を設置する予定です。","id":"exchange-126"},{"speaker":"芹澤委員","kind":"提案","question":"最後に、オリンピック・パラリンピックのレガシーについて伺います。これは以前もご提案をしたのですが、ボッチャの大会をしていただきたいなと思っていて、レクリエーションでもあると思っていますとの意見を述べました。","respondent":"中元スポーツ推進課長","answer":"委員ご指摘のとおり、ボッチャは年齢や性別、障害のあるなしに関わらず、全ての方が一緒に競い合えるスポーツと認識しています。他自治体で開かれている大会の運営手法も調査研究し、今後、大会の開催を検討してまいりたいと思っているところです。","id":"exchange-127"},{"speaker":"芹澤委員","kind":"意見","question":"いろいろなスポーツがあって、他のスポーツが今開催されている中、それを押しのけてやってしまうと、なかなかそれも軋轢が出てしまうので、それはぜひ逆に他のスポーツの方々にもお手伝いいただいて、協力関係を得ながら、すばらしい大会を実現してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-128"},{"speaker":"高橋（し）委員","kind":"質問","question":"１４０ページの寄附金ですけれども、こちらは議案の説明のときに伺いました。ここまで結論が出されたことは、大変多大なご苦労があったと思います、ということでお尋ねしています。","respondent":"佐藤企画調整課長","answer":"予算書１４０ページの指定寄附金に関するご質問です。暫定施設のほうで活用しますが、その後の本格活用については、整備をする公共施設のほうに充てたいと今のところ考えております。","id":"exchange-129"},{"speaker":"高橋（し）委員","kind":"質問","question":"その都市計画決定は、お話しできれば、どのようなものになる見込みでしょうか。そして、時期がその２か月後とあるので、これは予算案の公共施設整備基金の積立て額に含まれているのか尋ねました。","respondent":"佐藤企画調整課長、鈴木都市計画課長、黒田財政課長","answer":"委員ご指摘のとおり、納付時期は都市計画決定後２か月以内ですが、都市計画決定時期は、今のところ未定というというふうに聞いております。 ＴＯＣの都市計画の現時点の計画ですが、３月の品川区の都市計画審議会にお諮りをして都市計画決定を進めるというような予定になってあります。 この寄附金につきましては、公共施設整備基金への積立ての財源として上げているものです。","id":"exchange-130"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"すみません、都市計画のほうも伺って。そして、なぜ寄附という形にしたのか尋ねました。","respondent":"佐藤企画調整課長","answer":"その「負担」という言葉を、これまでも議会のほうでご説明していたところですが、一部寄附という話もしています。第一日野小学校の整備費３０億円をベースにしながら検討してきた結果、今回、１７億円というところで寄附ということになりました。","id":"exchange-131"},{"speaker":"高橋（し）委員","kind":"質問","question":"そこと性質が違うのは、今課長がご説明のところがあるから、そういう状況なのでしょうか。今お話があったＴＯＣとの関係で言うと、違いは、これまでの経緯があったというところなのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-132"},{"speaker":"高橋（し）委員","kind":"質問","question":"すみません。新庁舎整備基金のほうに寄附が１件あるというふうに昨日ご答弁をいただいたので、そちらについて、今後結んだりするのか尋ねました。","respondent":"東野庁舎計画担当課長","answer":"まず、区民の方の意向を反映させるために、条例の中に条文を盛り込んだというようなところです。特に協定とか、そういうことではなくて、区民の方のご意向をそのまま庁舎計画のほうに反映させていきたい、そういう思いです。","id":"exchange-133"},{"speaker":"高橋（し）委員","kind":"質問","question":"質問の趣旨が分かりにくくて申し訳ありません。その補助も含まれて、費用がこれだけかかったということで補助が出てくるのか、その辺もご説明をお願いします。","respondent":"黒田財政課長","answer":"事業の種類にもよりますが、基本的に、寄附があった場合については、寄附の部分を除いたものが事業費の対象となりますので、いわゆる補助対象事業にもよりますけれども、基本的には、寄附は特定財源として除かれるというものです。","id":"exchange-134"},{"speaker":"高橋（し）委員","kind":"質問","question":"そこで、１７億円の基金のような形で設定しなかったのは、先ほどのご答弁との関係もあるのでしょうか。その点を伺います。","respondent":"佐藤企画調整課長","answer":"寄附の名目が西五反田地区公共施設整備指定寄附というところで、寄附していただいた民間事業者とも話をして、こういった公共施設整備基金に積立てて、今後の本格活用に使わせていただきますよというご説明をしているところで、両者が理解しているものだと考えております。","id":"exchange-135"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"これは減債基金を充当してもいいと思うのですが、それを入れないで一般財源となるのでしょうか。すみません、時間が厳しくて。","respondent":"黒田財政課長","answer":"ここは減税補填債については、もともと財調で原資を積立てていた部分は、その部分を国に充てていると。ここをぴったり充てるということではなくて、一般財源の調整の結果、こういった形で少し差額が出たです。","id":"exchange-136"},{"speaker":"大倉委員","kind":"質問","question":"私からは、１２９ページ、都市防災不燃化促進事業から、本年度対象地域になっている放射２号線に関連して伺いたいと思います。放射２号線のほうですが、今後どのようになっていくのか、見通しはどのぐらいの年数なのかというところを教えてほしいと求めました。","respondent":"鈴木都市計画課長","answer":"放射２号線の現在の用地取得率ですが、令和３年３月末のデータですが、現在、３９％というような用地取得率です。全体の計画的なところとしましては、事業期間見直しが行われまして、令和８年３月３１日までの事業期間になっているです。","id":"exchange-137"},{"speaker":"大倉委員","kind":"質問・要望","question":"まだまだ令和８年３月というところでは、地域の人からどう声があるのかとか、その要望等があったら教えてください。使っているところがあるというふうにも伺っているのですが、どういった活用がされているかを教えていただきたい、まずそれをお願いします。","respondent":"森木密整備推進課長","answer":"補助２９号線について、木密整備推進課のほうで地域の方々と話合いをしているところがありますので、私のほうから回答します。十分に地域の方々から意見を聞いて、区としても、東京都と連携していきたいというふうに考えております。","id":"exchange-138"},{"speaker":"大倉委員","kind":"質問・要望","question":"放射２号線のところだと、令和８年度の３月までは、何かいろいろなことができるのかなというような思いがあります。これは、では、一言お願いいたします。","respondent":"森木密整備推進課長","answer":"基本的には、特定整備路線の道路予定地ですので、できることはひとつ限られる部分があるのかなというふうには思いますけれども、せっかく地域の方々の身近にそういった部分がありますので、様々な意見を聞きながら、東京都と前向きに検討していきたいというふうに考えております。","id":"exchange-139"},{"speaker":"大倉委員","kind":"質問・要望","question":"以上で、この件に関しては終わります。５万８,０００円とか、実際どのぐらいが売上げとしてあるのかというところを教えていただきたいのですが、お願いします。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"こちらは、第一弾、第二弾の販売をしまして、それぞれ全体で合わせて１０万円弱です。これは売った分が全て入るわけではなく、ＬＩＮＥが販売した分の一部が配当金として入るです。","id":"exchange-140"},{"speaker":"大倉委員","kind":"質問","question":"今年度予算としては、どのくらい見込まれているのかというところを説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"こちらのＬＩＮＥスタンプですが、東京２０２０大会も終わったということで、販売自体も本年度の３月をもって終了する予定です。したがいまして、令和４年度の歳入のほうには入っておりません。","id":"exchange-141"},{"speaker":"大倉委員","kind":"質問","question":"今回で終わってしまうということで、ＬＩＮＥスタンプ、活用してみてどうだったか。この辺の評価とか、課題も含めて、あったら教えてほしいと求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"東京２０２０大会が決まったときに、まず応援競技をなかなかご存じない方が多かったので、普及啓発の１つとして作成したところです。職員が手作りで登録したりもしておりましたので、そういった意味では、チャレンジする気持ちもできたかなというふうに認識しております。","id":"exchange-142"},{"speaker":"藤原委員","kind":"質問","question":"１０３ページ、１３１ページ、いじめ防止対策事業補助金についてお伺いします。参議院議員選挙についてお伺いしますが、なぜ選挙をするのでしょうか、説明を求めました。","respondent":"齋藤選挙管理委員会事務局長","answer":"統治機構の担い手である一定の公職にある方、例えば、国会議員、地方議会の議員、首長につきましては、投票という行動をもって選任すると、こういった定めがあるためです。","id":"exchange-143"},{"speaker":"藤原委員","kind":"質問","question":"私は、一番は民意の反映、公正公平な選挙をやって民意を反映することと考えています。区だからとか、上とか下とかはないと思っているのですけれども、その辺についてはいかがか尋ねました。","respondent":"齋藤選挙管理委員会事務局長","answer":"それぞれ国会議員の役割、地方議会の役割、首長の役割というものが定められておりまして、その役割を全うする。そして有権者の意思を反映させて、行政のチェックをしたり、立法活動に関わる、こういったことにおいては同質なもの、同等のものと理解しております。","id":"exchange-144"},{"speaker":"藤原委員","kind":"意見","question":"どう考えてもおかしい。ちょっとおかしいなと思うのですけれども、局長、この辺についてはどう思いますかとの意見を述べました。","respondent":"齋藤選挙管理委員会事務局長","answer":"これは法律で地方議会、首長は除外をしていると、こういうたてつけになっているものです。立法論の課題となりますので、区として負担すべきかどうかということについては、少し答弁は控えさせていただきたいと思います。","id":"exchange-145"},{"speaker":"藤原委員","kind":"質問・要望","question":"答弁を控えさせていただきたいと言えば、せっかく選挙管理委員会もあるわけですから、ぜひこういう意見も出たということは上げてください。死亡数が減ったことについて、よかったなと思うのですけれども、その辺の分析はいかがか尋ねました。","respondent":"川口交通安全担当課長","answer":"１つが自転車利用中の事故で、もう１つが、残念ながら死亡事故という形でございました。ただ、高齢者の方々とか、比較的そのような日頃のキャンペーン等を通じた広報啓発活動の形が出たのかなというふうには考えております。","id":"exchange-146"},{"speaker":"藤原委員","kind":"質問","question":"これは事実ですから。これをずっと訴えてきたのですけれども、訴えて、何か対策を、改めてこういうことをしましたということがありましたら、その辺をお伝えください。","respondent":"川口交通安全担当課長","answer":"私のほうから警察のほうにも対応の要請をいたしまして、オーバーハング式の歩行者の横断歩道ありの標識の脇に、「歩行者あり！そちらの部分につきましては、優先順位をつけてやらせていただいたです。","id":"exchange-147"},{"speaker":"藤原委員","kind":"質問・要望","question":"だから、そういう意味で、その対策を、交通弱者ですから、そうですよね、どのようなことがあっても歩行者を守るのですよね。やっぱり交通弱者、歩行者を守っていくという施策をしていっていただきたいと思うのですけれども、その辺についてはいかがか尋ねました。","respondent":"川口交通安全担当課長","answer":"令和２年は６.６％だったものが、これが１２.１％に上がっているということなので、確実に上がっている部分はあるのかなです。区民の皆様が安心して暮らせるように、この経験を生かしまして、交通事故削減に向けて頑張っていく所存です。","id":"exchange-148"},{"speaker":"藤原委員","kind":"質問・要望","question":"これは１点ストレートに伺いますけれども、西大井の２校、まだなのです。これはどうなっているのか尋ねました。","respondent":"有馬庶務課長","answer":"区立学校の学校改築の件ですが、基本的には平成１７年辺りから、毎年１校ずつぐらいのペースで進めているものです。大井地区についても、今後、全体を見ながら改築するかどうかは検討していきたいと考えております。","id":"exchange-149"},{"speaker":"藤原委員","kind":"質問","question":"課長、地域ということを言うならば、あの西大井の近辺、２校ともやっていないですから、地域バランスを考えたら、やるべきではないですか。もうそろそろ常勤でということを考える時期に私はなっていると思うのですけれども、その辺についてはいかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"病院のカウンセラー、福祉のケースワーカーなど、そういうことで幅広く専門的な視点で適切な支援策を検討したりできるというメリットもあります。この週３日、４日というのが、また現職スタッフの話も聞きながら検討してまいりたいと思います。","id":"exchange-150"},{"speaker":"中塚委員","kind":"質問・要望","question":"７７ページ、区営住宅使用料に関連して、区営住宅について、異性だけではなく同性カップルも利用できるようにすることを求めて質問したいと思います。２３区で既に同性カップルの区営住宅の利用を認めている区は何区あるのか、どこなのか、伺いたいと思います。","respondent":"竹田住宅課長","answer":"区所管では、マイセルフ品川プランの行動計画推進会議の提言を踏まえ、パートナーシップ制度の導入について検討を進めているとしております。住宅課でも、区営住宅、区民住宅について、併せて検討してまいります。","id":"exchange-151"},{"speaker":"中塚委員","kind":"提案","question":"入居規定や、同性パートナー同士が同居できない状況が緩和されることが望まれますと、具体的に区営住宅についても提案がされております。この報告書に基づいて、具体化をする立場に立ってほしいと求めましたが、いかがか尋ねました。","respondent":"竹田住宅課長","answer":"今回、東京都が、パブリックコメントを実施いたします。パブリックコメント等は大変貴重な機会と考えておりますので、東京都の動向をしっかり注視していきたいと考えております。","id":"exchange-152"},{"speaker":"中塚委員","kind":"質問・要望","question":"品川区行動計画推進会議が出した報告書、この立場に立って具体化を進めていただくことを求めたいと思います。区営住宅に同性カップルを認めるということは、こうした差別を許さないという強いメッセージにつながると私は思いますが、いかがか尋ねました。","respondent":"竹田住宅課長","answer":"ただ、現状としましては、区営住宅、区民住宅の入居者資格は、同居親族がいることとなっています。東京都が現在検討している受理証明書が、東京都の動向を注視していきたいと考えています。","id":"exchange-153"},{"speaker":"中塚委員","kind":"質問","question":"東京都の動向は注視していただいてもよいのですけれども、私が今伺ったのは、この区営住宅に同性カップルを認めるということは、こうした差別は許されないという強いメッセージにつながると私は思うのですけれども、品川区は、そう思うのかどうか改めて伺いたいと思います。","respondent":"竹田住宅課長","answer":"区所管課では、マイセルフ品川プランの行動計画推進会議の提言を踏まえて、パートナーシップ制度の導入について検討を進めるとしております。品川区でも、区営、区民住宅について、併せて検討してまいる考えです。","id":"exchange-154"},{"speaker":"中塚委員","kind":"質問・要望","question":"異性カップルだけではなく同性カップルも認めることに、何か課題があると思っていらっしゃるのか、その点を伺いたいと思います。ぜひ区営住宅に同性カップルも認めると、その導入に向けた検討を今年進めてほしいと求めましたが、改めていかがか尋ねました。","respondent":"竹田住宅課長","answer":"パートナーシップ制度を利用した場合に東京都が発行を検討している住民証明が住民票に代わるものかどうかということをしっかり確認して。こういった方々が暮らしやすい環境づくりをするためにも、区民の方々のご理解を推進していきたいと考えております。","id":"exchange-155"},{"speaker":"高橋（伸）委員","kind":"質問","question":"５２ページ、特別区たばこ税、同じく５２ページ、森林環境譲与税についてお伺いいたします。マイナス４,９００万円ということですけれども、これ、改めてどういうふうに区としてお考えなのかということをまず１つお伺いしたいと思います。","respondent":"提坂税務課長","answer":"たばこの売渡し本数の動向につきましては、平成１８年以降、もう２０年近くずっと減り続けております。これまで度重なる税率の引上げですとか、健康志向の高まり、あと、今、コロナの影響とかもございまして、減少傾向は続くものと思われます。","id":"exchange-156"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"本当に課長がおっしゃるとおり、減少傾向だと私も認識しております。令和２年度の特別区たばこ税の収入額、２３区中、品川区は何位だったということがお分かりになれば教えてほしいと求めました。","respondent":"提坂税務課長","answer":"すみません、順位までは把握してございません。","id":"exchange-157"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"それと、関連しまして、今まで各委員から喫煙所に対しての質問がありました。４つの視点の中に、これは喫煙者にとって整備をしますよということでいいのかということ、確認だけさせてほしいと求めました。","respondent":"森田生活安全担当課長","answer":"喫煙所の設置につきましては、各指定地区を設けておりますが、その指定地区の中にまず設置をしていくという形で進めしています。今後も、人の多い駅前であるとか、そういったところの指定地区において実施をしてまいりたいと考えています。","id":"exchange-158"},{"speaker":"高橋（伸）委員","kind":"質問","question":"次の質問で、非喫煙者の回答が「とてもそう思う」、４４％です。そういう意味で、屋内型をパーテーション型にしっかりと改良するという手法もあると思うのですけれども、それについてお伺いしたいと思います。","respondent":"森田生活安全担当課長","answer":"屋外に限ってご説明させていただければ、煙の関係が出てきますので、パーテーションも設置をしております。ですが、なるべくその辺の煙が出ないような対策は、考えながら実施をさせていただいているところです。","id":"exchange-159"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続いて、同じく５２ページ、森林環境譲与税についてお伺いいたします。５月にエコルとごしが開設しますけれども、この中に入っていない理由というのですか、どういう考え方なのか教えてほしいと求めました。","respondent":"黒田財政課長","answer":"区の活用見込みとしましては、こういった国産木材を活用するといった事業を選定して、財源として充てているです。","id":"exchange-160"},{"speaker":"高橋（伸）委員","kind":"質問","question":"令和２年度だと、森林材を使った取組事例として、特別区だと、中央区、豊島区、江東区が記載されています。林野庁に事例集として、区として、それは上げていくのかということをお聞きしたいと思います。","respondent":"黒田財政課長","answer":"区の森林環境譲与税の活用事例として、そういった調査があれば報告していきたいというふうに考えてあります。","id":"exchange-161"},{"speaker":"高橋（伸）委員","kind":"質問","question":"やはりこれ、２９.４％増ということで、今後も増になるのかと思うのですけれども、財政として、どういうふうにそこはお考え、今後の見通しをお聞きしたいと思います。","respondent":"黒田財政課長","answer":"令和６年度には、品川区では５,０００万円ほどの譲与が見込まれておりますので、そういった財源を活用して進めてまいりたいというふうに考えてあります。","id":"exchange-162"},{"speaker":"塚本委員","kind":"質問","question":"２月１０日から戸籍票、今は、日によっては１桁ぐらいの申請がありますというふうに伺いました。先ほど２３区では３区が実施しているというような話がありましたけれども、また、そういった見通しについてお伺いします。","respondent":"木村戸籍住民課長","answer":"やはり１０％、２０％、コンビニ交付と同じぐらいのレベルに持っていきたいなというふうには考えておるところです。この年度末にかけて、各自治体どんどん増えてきているような状態でございまして、かなり今後も増えるのではないかというふうに思っております。","id":"exchange-163"},{"speaker":"塚本委員","kind":"質問・要望","question":"国がそれを認めていないからということで伺っておりますけれども、この１月に値上がりということで、大変やりにくくなるというのですか。区として認識しているところをお伺いしたいのと、どういった意見なり要望なりということをこれまでしてきたことがあるのかについてお伺いします。","respondent":"木村戸籍住民課長","answer":"それは開発可能ですというお答えをいただいていたりとか、これからもそういう動きをやっていきたいなというふうには、思っております。国が動き出すような雰囲気も今ありますので、機会を捉えまして、区のほうからも要望を出していきたいなというふうに思っています。","id":"exchange-164"},{"speaker":"塚本委員","kind":"質問","question":"すぐにできるというような形にもう進んでいるみたいですので、ぜひ今言ったような動きで進めていただけるとありがたいというふうに思います。どうしても不正請求の話が一方であるということで、このセキュリティについて、どういった対応が必要と考えられるかお伺いしたいと思います。","respondent":"木村戸籍住民課長","answer":"今ご指摘ございました、私は士業の人間ですというような証明はあると。やっている、ここら辺を国にどう示していただけるかという辺りが、これからのセキュリティ上の課題というふうに認識しておるところです。","id":"exchange-165"},{"speaker":"塚本委員","kind":"意見","question":"こういったことも１つの大きな効果があるのではないかというふうに思いますので、今後、検討いただければというふうに思います。令和１１年までに整備効果の高い４路線、令和４年度は、併せてお答えくださいとの意見を述べました。","respondent":"溝口道路課長","answer":"今回、令和２年度に作成しました無電柱化推進計画の中で進めていく事業としての設計ですとか工事、そういったものに使える補助制度になっております。工事等を予定しておりますので、この２路線については、それの工事費用に充てるということで補助金を充当しているものです。","id":"exchange-166"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私は、５６ページ、特別区財政調整交付金と、５３ページ、森林環境譲与税について伺います。１兆７,０００億円ぐらいだとしたら１７億円ぐらいで、どう手当てをされているのか、そこら辺のところを教えてほしいと求めました。","respondent":"黒田財政課長","answer":"全体の５５.１％の中で、東京都のほうの財調の対応補正の中で、現時点では５５.１％の中で算定されていると。これについては、令和４年度、改めて協議するというところになってあります。","id":"exchange-167"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"実績を見て令和４年に協議をするというのであれば、５５％が０.１％で終わりなわけではなくて、よく言うけれども。私はその金額が全然違うと思っているので、ぜひそこの議論も併せてやってほしいかなと思うので、そこら辺の感覚を教えていただきたい。","respondent":"黒田財政課長","answer":"過半の区が児童相談所を設置しなければ、適正な財源配分割合に変更するというところの姿勢を持って、これは強く協議に当たっていきたいというふうに考えてあります。","id":"exchange-168"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ここで伺いたいのは、６月ぐらいから、使用の底辺が広がっていくと思うのです。ぜひそこら辺のところを考えると、これからがそういう底辺を広げていく初年度になると思っているので、そこら辺のところの感覚を教えていただきたい。","respondent":"黒田財政課長","answer":"その使途を公表しなければならないということになっておりますので、意義に見合う使い方ができるように、今後も検討してまいりたいというふうに考えてあります。","id":"exchange-169"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"先ほども言ったように、必ずその底辺を広げるような使い方、こういうものをしていっていただきたい。こういう優しさ、これはもう要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-170"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/201716?Template=document&Id=1146#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":125024,"voices":376}},{"id":"r04-20220303-10","meetingId":"r04-cm03","date":"2022年3月3日","dateIso":"2022-03-03","committee":"議会運営委員会","time":"午後 ５時４５分～午後 ６時０３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を7件整理しています。","topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"お手元に配付させていただきましたロシア連邦のウクライナ侵略に抗議し、即時撤退を求める決議案について、説明させてほしいと求めました。説明は以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"須貝委員","kind":"質問","question":"こんな世界平和の中でこういうことをやる国に関して、無謀な暴挙に関しては、やはりきちっと我々で訴えるべきではないでしょうか。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"渡辺委員","kind":"提案","question":"提案者に質問です。スケジュール感だけ、提案者としてのご意見を伺っておこうと思うのですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"中塚委員","kind":"確認","question":"今予定されている会議日程から考えると、次回の議会運営委員会で議案を確認して、最終本会議で上程したいというスケジュール感を持っております。中途議決はいつでも可能だと思いますので、できるだけ早くという思いがありますけれども、現状としては……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"もう１回いいですか。何だよということになりますので、そこはちょっと付け加えて、意見を言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"大沢委員","kind":"意見","question":"ですので、１回持ち帰らせていただいてということのほうが私もいいと思います。以上ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"渡辺委員","kind":"質問・要望","question":"私どもの会派も、中身だろうと、そのスケジュール感だろうと、もちろん出す、出さないの含めて、私もちょっと持ち帰らせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/982514?Template=document&Id=5450#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":5414,"voices":33}},{"id":"r04-20220307-3","meetingId":"r04-c-budget","date":"2022年3月7日","dateIso":"2022-03-07","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時２８分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を150件整理しています。","topics":[{"id":"topic-01","title":"第５号議案、令和４年度品川区一般会計予算","agenda":"第５号議案、令和４年度品川区一般会計予算","exchanges":[{"speaker":"芹澤委員","kind":"質問","question":"１８９ページ、関連して１７３ページの国際交流推進事業、あと１７９ページの働き方改革推進事業についてお伺いしたいと思います。ぜひこの１週間の変化を捉えていただいて、ロシアの侵攻に対して抗議の意を表してほしいと求めましたが、ご見解を説明を求めました。","respondent":"古巻総務課長","answer":"見てまいりましたけれども、原子力発電所への攻撃といった形で、さらに憂慮の度合いが高まる状況になってまいりました。考えておりまして、これから少し検討した上で、何かできないかということは検討しています。","id":"exchange-001"},{"speaker":"芹澤委員","kind":"質問","question":"対外的な態度表明については、これで質問を終わりますが、区内の動きについて職責といいますか、これについて幾つかお伺いしたいと思います。警察署ないしはメディアもしくは大使館から、デモがありますというようなご連絡があったのか、事後も含めて分かる範囲で情報を説明を求めました。","respondent":"古巻総務課長","answer":"警察とも連携しながら、状況については逐次、情報収集をしてきたところです。特段大きな混乱はなかったとは認識しておりますけれども、今後も、その動きについては注視してまいりたいと考えております。","id":"exchange-002"},{"speaker":"芹澤委員","kind":"質問","question":"やはりいろいろなデモの対象になりやすいところですから、結構、いろいろあると思うのです。情報提供をした上で、職員の方が分かるような体制を取ってほしいと求めましたけれども、ご見解を説明を求めました。","respondent":"古巻総務課長","answer":"ご指摘いただいたとおりでございまして、何かあった後では遅いということがありますので、危機管理的な側面からも、警察との連携はしっかりして、今後もそういった形での大使館をめぐる動きについてはしっかりと情報収集をした上で対応していきたいと考えております。","id":"exchange-003"},{"speaker":"芹澤委員","kind":"質問","question":"いじめ防止というところでもお伺いするのですが、ロシア人が悪いというわけではなく、在日ベラルーシ人が悪いというわけではないと思うのです。人権啓発というところで、これからこの問題に対して品川区としてどういった啓発を考えていらっしゃるのか、説明を求めました。","respondent":"古巻総務課長、島袋人権啓発課長","answer":"それに応じた対応を考える必要が出てくるのかと考えておりますので、ベラルーシの動きにつきましては、しっかり注視してまいりたいと思います。総務課の国際部門では１つの課題という形で事業を展開しておりますので… 人権啓発課では、このたび、「外国人差別は許さない」という懸垂幕を掲出する予定ですので、それを区民の皆様に見ていただくように努めてまいりたいと考えております。","id":"exchange-004"},{"speaker":"芹澤委員","kind":"質問","question":"今回の質問をつくるに当たっていろいろ見ていく中で、やはり区内の出来事ですから、警察と強く連携してほしいと求めました。やはり職員のパフォーマンスというのですか、全部の項目は読み上げませんが、かなりの項目があります。","respondent":"崎村人事課長","answer":"移動しやすいものですとか、座面の高さや背もたれの調節ができるものといった基準で購入して、職員が使用させていただいているところです。そういった情報機器作業の中で取り組むべき事項、自分に合うよう椅子を調節しようといったことは、職員に向けて周知しています。","id":"exchange-005"},{"speaker":"芹澤委員","kind":"意見","question":"併せて、ＩＣＴ化が進んでいくに当たって、学校だけではなくいろいろなところで、できる人、できない人というのが出てくると思うのです。課長に関しても恐らくそうだと思うのですが、そういった取組みに今どういうものがあるのか、説明を求めました。","respondent":"崎村人事課長","answer":"現在、先ほど冒頭に予算の説明がございましたが、やはりそれを推進していく職員の育成というのが重要になってまいります。来年度以降、そういった職員研修の中で、特に管理職についてはそういった視点についても研修の中で育成を図ってまいりたいと考えております。","id":"exchange-006"},{"speaker":"新妻委員","kind":"質問","question":"１８５ページ、２０１ページ、順不同で伺ってまいります。東京２０２０大会のレガシーの取組みで、アートの講座を実施する、この講座との関連性をお伺いいたします。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"障害者アート等との連携ですが、アートの種類や特性等には特にこだわらないで、いろいろな形で活用できればと考えております。今、委員がご提案なさった障害者の事業との連携も含めまして、これから前向きにどのような形でできるかを相談しながら決めていきたいと思います。","id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"暫定活用ではありますけれども、こういう活動の場を一つでも多くつくっていただくことを要望します。続きまして、八潮地区のまちづくり事業について伺います。","respondent":"川島地域活動課長","answer":"委員にご説明いただきましたが、昭和５８年に団地の入居が始まったということで、約４０年経過しています。地域の魅力向上に向けたまちづくりへの支援を行うために、八潮まちづくり担当を新設して、八潮地域の魅力向上支援を行っていくです。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問","question":"この２年間、コロナ禍の影響を受けて、なかなかワークショップが延期、延期になっております。八潮自治会、１つの自治会で八潮地域センターがありますけれども、この地域センターとの関連をお伺いいたします。","respondent":"川島地域活動課長","answer":"そのまま引き続き継続していただく中で、八潮まちづくり担当は住民との調整を行いながら、組織連携を進めていくような役割になるかと考えています。しっかり、いろいろなご意見を酌み取ったり調整したりというような役割を果たせるのではないかと考えています。","id":"exchange-009"},{"speaker":"新妻委員","kind":"提案","question":"一つひとつ、着実に実現されることを要望いたします。併せて、東京都がこの制度を導入することで、品川区に住むＬＧＢＴＱの方々にはどのようなメリットがあるのか、お伺いいたしますとの意見を述べました。","respondent":"島袋人権啓発課長","answer":"子どもとの関係も検討したいというふうに聞いております。思い込みや偏見による差別がまだまだ多い状況だと考えておりますので、皆に見ていただけるような講演会を実施する予定で計画しているものです。","id":"exchange-010"},{"speaker":"新妻委員","kind":"質問","question":"そうしますと、東京都が発令することで、それに準じて品川区もしっかり対応されるという理解でよろしいのでしょうか。その辺のことについて、ご答弁をお願いいたします。","respondent":"島袋人権啓発課長","answer":"ただいま東京都より、東京都パートナーシップ宣誓制度導入に当たりまして、区市町村の調査というものが来ておりますので、委員がご指摘の内容についても検討していくように進めてまいりたいと考えているところです。","id":"exchange-011"},{"speaker":"横山委員","kind":"質問","question":"１点目に、選挙費、人権啓発費についてお伺いいたします。一般質問でもお伺いしたのですけれども、現在、区が実施している内容を説明を求めました。","respondent":"齋藤選挙管理委員会事務局長、島袋人権啓発課長","answer":"選挙管理委員会で実施している研修ですが、講座・研修会とも、地方自治に関心を持っていただくための講座、しいの木講座や、投票率向上に向けての出前模擬選挙といった講座・研修会を実施しています。 区では企業に対しましても、人権講演会に関するパンフレットなどの啓発活動に努めているところです。区民に対してですが、やはり思い込みや無自覚の偏見ということを変えていただくための啓発などを積極的に進めているところです。","id":"exchange-012"},{"speaker":"横山委員","kind":"質問・要望","question":"セクハラ、人権侵害の観点から、どのように区民の意識を向上させていくのがよいとお考えでしょうか。今日は総務費ですので要望といたしますが、ハラスメント撲滅のための取組みを進めていく必要があると私は考えております。","respondent":"島袋人権啓発課長","answer":"やはり啓発活動をしっかり進めてまいりたいと考えておりますし、１１月１２日から２５日に関しましては、女性に対する暴力をなくす運動の期間です。このときにも、様々な女性の人権に対する問題を提議していきたいと考えているところです。","id":"exchange-013"},{"speaker":"横山委員","kind":"質問・要望","question":"２点目に、プロスポーツ連携事業についてお伺いいたします。私は２月に、佐野智郎ヘッドコーチにお話を伺いました。","respondent":"中元スポーツ推進課長","answer":"令和３年に誕生した、小学生を対象としたスポーツ教室を今年度も実施していただきましたが、来年度も引き続き予算計上させていただいたものです。競技種目によりましては、先行事例等を勉強させていただきまして、今後取り組めるものを取り込んでいければと考えているところです。","id":"exchange-014"},{"speaker":"横山委員","kind":"質問・要望","question":"私たちの会派で北海道に視察に伺い、地域と融合したプロスポーツとして、北広島市に建設中のボールパーク構想についてご説明いただきました。庁舎移転後の跡地活用として、民間活力をどのように活かしていくかを含めてご検討いただきたいと要望いたしますが、区のご見解を説明を求めました。","respondent":"佐藤計画担当課長","answer":"大井町駅周辺地域まちづくり方針におきまして、行政機能・にぎわい集積ゾーンと位置づけられております。委員ご指摘の整備手法等を含めまして、様々な観点から検討してまいります。","id":"exchange-015"},{"speaker":"横山委員","kind":"質問","question":"では３点目に、広報広聴費についてお伺いいたします。そして４点目ですけれども、ＩＣＴ推進管理費についてお伺いいたします。","respondent":"大澤広報広聴課長、宮澤情報推進課長","answer":"例えば広報紙では、記事を大きくするとか囲み記事にする、また目につきやすいところに掲載するなどの工夫を行っております。ホームページにおきましては、それぞれの事業の目的と、また詳しい内容についてご案内して… 現在、約１,０００の手続きがある中で、１００以上の手続きのオンライン化を進めてきているところです。庁内で検討を進めていくというところで、令和７年度までに、可能な手続きは全てオンライン化していくという形です。","id":"exchange-016"},{"speaker":"横山委員","kind":"質問・要望","question":"ぜひどういったことを目的としているのかというところ、かつ正確に、引き続き工夫して伝えていただきたいと考えています。喜ばしいことですし、少しずつ進めていただきたいと考えていますので、どうぞ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"安藤委員","kind":"提案","question":"質問したいのは、現庁舎の跡地に、にぎわい施設を造るのだという点を区民の方に問うたことはあるのでしょうか。公有地というのは区民の財産なわけですから、にぎわい施設を造ってほしい、真っさらな状態で問うたことはあるか尋ねました。","respondent":"佐藤計画担当課長","answer":"この方針を策定する段階におきましては、案を含めまして、区民の方にご提示した上でご意見いただきながら方針を策定してきたという経緯があります。今後につきましても、様々な観点から検討してまいりたいと考えています。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"私が伺ったのは、現庁舎の跡地も含めた大井町の区有地ににぎわい施設を造るという方針を、直接区民に問うたことがあるのですかということです。その辺をちゃんとしっかりお答えほしいと求めました。","respondent":"佐藤計画担当課長","answer":"ご意見いただきながら方針を策定してきたということがありますので、十分に聴取した上で方針を策定してきたと考えておりますので、様々な検討をしていきたいと考えております。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"１７７ページ、男女共同参画推進事業について、パートナーシップ制度、区職員の休日や福利厚生について、それぞれ伺いたいと思います。先ほども質疑がありましたが、品川区としてパートナーシップ制度を設置する考えを持ってほしいと求めましたが、いかがか尋ねました。","respondent":"島袋人権啓発課長","answer":"品川区におけるパートナーシップ制度の早期導入ですが、第１７期品川区行動計画推進会議の報告書を受け、速やかに実施する方向で検討してまいりたいと考えているところです。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"速やかに検討していただけるということで、たくさんの会派からも要望がありましたので、ぜひ今年度、検討を進めてほしいと求めました。その上で、異性カップルだけではなく同性カップルにもこの休日を認めるべきだと思いますけれども、いかがか尋ねました。","respondent":"崎村人事課長","answer":"結婚休暇につきましては、週休日、休日を含めてになりますけれども、引き続き７日以内の取得が可能となっています。区として、パートナーシップ制度についての方向性を総合的に検討する中で、結婚休暇等につきましても検討していきたいと考えております。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問","question":"この間、様々議論がされてきましたけれども、区の職員は結婚に伴い、７日以内の休暇があります。品川区としても、そこをどのようにお考えなのか、伺いたいと思います。","respondent":"島袋人権啓発課長","answer":"品川区に関しましては、先ほど申し上げました第１７期品川区行動計画推進会議の報告書を受け、できるところからやっていけるように努力していきたいと考えているところです。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"その上で、なぜ結婚すると７日以内の休日が与えられるのか。それについて伺いたいと思います。","respondent":"崎村人事課長","answer":"勤務を要しないところということでの休暇でございまして、その内容につきましては、条例の施行規則の中で定められているところです。結婚休暇につきましては、結婚後の新婚旅行等々の面もございまして、７日以内の休暇を認めているといったところです。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"結婚や、配偶者の死亡の際に、幾ら給付されるのか、伺いたいと思います。この点についても給付の対象を異性カップルに限定するのではなく、同性カップルも対象にすべきだと思いますけれども、いかがか尋ねました。","respondent":"崎村人事課長","answer":"配偶者が死亡したときにつきましても、同じく互助会から弔慰金として２万円が支給されているような状況です。パートナーシップ制度導入についての検討の中で、この給付金のみならず、福利厚生全般についても併せて検討していくべきものと考えております。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"昨年１２月の報告書に沿って、当然、民間企業への波及効果も期待されると思います。ぜひ、そういう趣旨も踏まえて、今後、具体化してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"くにば委員","kind":"提案","question":"総論に関しては総括質疑でするとして、本日は４０以上の項目にわたって指摘・提案・要望をします。これがなぜか、９つのメニューの「手続き・届出」と「施設案内」の間に入ってしまっていて、ここに関しては改善を要望いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"くにば委員","kind":"意見","question":"先日、つる委員が、主に１回の答弁で、あとは思いを語っていらっしゃったと思いますので、これに関しましては私も、基本的に私がお伝えしようと思っている部分に関してお話ししますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"くにば委員","kind":"質問・要望","question":"ぜひともご確認をお願いします。ウェブに関して詳しい方がいらっしゃるかどうか、クオリティチェックをする総括担当を、そのクオリティチェックに関して権限を持たせていただきたい。","respondent":"大澤広報広聴課長","answer":"広報広聴課で一括に管理するということは、１万６,０００ページという量から考えても難しいと考えております。見やすいホームページにする調整というのが大切だと思いますので、今後、研修等を通して周知してまいりたいと思います。","id":"exchange-028"},{"speaker":"田中委員","kind":"質問・要望","question":"生活者ネットワークは２０２０年３月の予算特別委員会のときから、今後に活かすためにも記録することが必要だと求めていました。品川区でも、このように検証のために記録を残しておくことが必要だと思いますが、現状を確認させてください。","respondent":"古巻総務課長","answer":"新型コロナウイルス感染症対策本部会議を行ってまいりまして、それを取って、今後の感染症対策に資するような形で活用できるように考えております。公表している部分としましては、記録としてもしっかり、感染症対策をした記録として活用させていただければと考えております。","id":"exchange-029"},{"speaker":"田中委員","kind":"質問・要望","question":"そのことに関するパネル展示が用意されているのかを、まず伺います。世界では非核を実現できている地域があることを示し、区民が希望を持てる事業に発展させていただきたいと要望いたしますが、見解を伺います。","respondent":"古巻総務課長","answer":"適切なそういったパネル展示をしていきたいと考えておりますし、いろいろご提案いただいた部分も含めまして、随時見直しをしていきたいと考えております。","id":"exchange-030"},{"speaker":"田中委員","kind":"質問・要望","question":"条例、要綱を載せてほしいと求めますが、見解を伺います。なぜこのような事態となってしまったのか、傍聴ができる会議体でこのようなことが起きないように再発防止を求めたいのですが、見解を伺います。","respondent":"東野経理課長、大澤広報広聴課長","answer":"こちらは、総務委員会でも委員からご指摘いただいたところだと認識しております。現在、どの段階まで掲載が可能かどうかというところを整理している段階でございまして、今後も引き続き検討していきたいと考えています。 一律にホームページのルールとすることは難しいと考えますが、各所管で必要性を考慮しながら工夫していくように働きかけてまいりたいと思います。計画一覧と、役に立ったかどうかということに関しては、今後検討してまいります。","id":"exchange-031"},{"speaker":"田中委員","kind":"質問","question":"イベントカレンダーに、傍聴ができる会議体のことが記されていなかったことが問題だったので、その再発防止をどのように考えているかと伺いました。ご答弁ください。","respondent":"大澤広報広聴課長","answer":"各所管からの記載漏れがないように確認してまいります。","id":"exchange-032"},{"speaker":"田中委員","kind":"質問・要望","question":"昨年の第４回定例会で、選挙公報のスペースの拡充について質問しました。選挙管理委員会委員長から、事務方に督促して検討するようにしてまいりたいとありましたが、現在の検討状況をお知らせください。","respondent":"齋藤選挙管理委員会事務局長","answer":"区議会議員選挙での選挙公報です。２月末の選挙管理委員会で、１２人ということで、改善の方向で決定したところです。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問","question":"障害者が利用できる施設は継続してほしいという意味で、暫定の考え方を伺います。そして、行政財産から普通財産に変更するのかも伺います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"期間は５年程度を考えております。財産的な区分の扱いとしては、行政財産です。","id":"exchange-034"},{"speaker":"田中委員","kind":"質問・要望","question":"開催日の日程は、今後も学校のない日が設定されていくのか、伺います。高学年や中学生への参加呼びかけを行っているのか、周知方法を伺います。","respondent":"島袋人権啓発課長","answer":"予定では７月と１２月でしたが、コロナ禍ということもございまして、１２月と２月に開催したものです。まだまだ差別意識についてのお悩み等がありますので、こちらは参加人数が少なくとも、しっかりと継続して実施してまいりたいと考えているところです。","id":"exchange-035"},{"speaker":"田中委員","kind":"質問・要望","question":"助けを求めていいというのが、区と区教育委員会の認識が違うのか、伺います。新１年生に貸与されるまもるっちの資料一覧を確認したところ、案内が入っています。","respondent":"森田生活安全担当課長","answer":"私たちの、午前７時３０分から午後８時までということになっておりますので、マモリーノ機能のココセコムが対応しますというところのオプションです。こんなものを入れます」といったものにつきましても、やり取りをしまして、中身の確認をしました上で対応しています。","id":"exchange-036"},{"speaker":"田中委員","kind":"確認","question":"万が一のときは児童の保護や付近状況の確認をお願いするものとありますが、ココセコムのオプション導入は区の目的に合致しているとお考えでしょうか。伺います。","respondent":"森田生活安全担当課長","answer":"後継機の関係ですが、今現在、検討しています。会議体がありますかということですが、これは今のところ、係内での検討を進めておりますし、委託継承のところともお話をしています。","id":"exchange-037"},{"speaker":"木村委員","kind":"確認","question":"総務費の中の、最初に１６７ページの上から４行目、広報経費からの質問です。配達員というのか、そういう方々に配られるお金というものに違いがあるのかどうか、確認します。","respondent":"大澤広報広聴課長","answer":"様々な調査におきましても、広報紙から情報を得るという方が、現時点でも一番ですので、それなりの役割を果たしているものと認識しています。これは一括しての契約になってあります。","id":"exchange-038"},{"speaker":"木村委員","kind":"質問","question":"区内で個別配送希望者の方はどれぐらいいるのか。個別配送希望者、スタンドに置く部数と合わせてどのぐらいの部数になるのかが分かれば説明を求めました。","respondent":"大澤広報広聴課長","answer":"新聞折り込みのほかには、区内２００か所以上のスタンドや、残りの分がそのような形での配布ということになってあります。現在、紙媒体以外でも、ホームページ、アプリ等での配信というのも行ってあります。","id":"exchange-039"},{"speaker":"木村委員","kind":"質問・要望","question":"３９回ということでありますけれども、声ということですから、ラジオか何かを利用したシステムでよろしいのか。これもお願いいたします。","respondent":"大澤広報広聴課長","answer":"デイジー版というもの、容量の大きなＣＤとお考えいただければいいかと思うのですけれども、それの配布。デイジー版とカセットテープの郵送のほかに、ＹｏｕＴｕｂｅやホームページの読み上げ機能でも出るようになってあります。","id":"exchange-040"},{"speaker":"木村委員","kind":"質問・要望","question":"はや４０年になろうとしている事業と伺ってきましたけれども、令和４年で４０周年ということですが、お聞かせください。そして、今年は４０周年と大きな節目ですから、何か大きな催物というものが行われる予定か尋ねました。","respondent":"大澤広報広聴課長","answer":"来年度、４０周年を迎えますので、区民の皆様に区民憲章の内容を再認識していただきたいという思いから、広報紙の特集号を発行する予定です。主に子どもたちに向けて、品川区民憲章の内容を動画で伝えることで、次の世代にも受け継いでいきたいと考えております。","id":"exchange-041"},{"speaker":"木村委員","kind":"質問","question":"次に、しながわ百景からの質問を致しますけれども、しながわ百景の理念というのは何でしょうか。しながわ百景は、いつ頃どのように選定されたのか尋ねました。","respondent":"大澤広報広聴課長","answer":"選定の根拠ですが、区政４０周年記念、区民憲章制定５周年記念として、昭和６２年４月１日に選定いたしました。品川区のよさですが、区民と共に魅力発信をすることが大切だと考えておりますので、これからも一緒にやっていきたいと考えています。","id":"exchange-042"},{"speaker":"松本委員","kind":"質問","question":"１７７ページの人権啓発事業について伺います。区でもどの程度あるのかというところをお伺いできればと思いますし、それに対して区としてどのように対応されているのか、伺います。","respondent":"森田生活安全担当課長","answer":"その場合の対応ですが、回収箱の設置など、環境についても配慮してやっていただきたいところは要望しています。個々の事案につきましては、自動販売機のところを確認した上で、個々の対応をさせていただいているです。","id":"exchange-043"},{"speaker":"松本委員","kind":"質問","question":"その上で、第１４条１項で、この改善命令が実際に出されたことというのはあるのでしょうか。伺います。","respondent":"森田生活安全担当課長","answer":"委員の説明のとおり、改善命令の項目があります。現在まで、この改善命令を出したことはございません。","id":"exchange-044"},{"speaker":"松本委員","kind":"質問","question":"条例が定められてもうかなり経ちますけれども、１回も改善命令は出されたことがないということです。本当は勧告から入ったほうがいいと私も思っているので、これは勧告の規定を設けたほうがいいのではないかと思うのですが、いかがか尋ねました。","respondent":"森田生活安全担当課長","answer":"その上で様々な対応もしておりますところで、そこで改善もなされるのかと考えています。勧告も入れたほうがいいというお話ですが、これにつきましては、各区などの効果などもはかりながら、これから研究してまいりたいと考えています。","id":"exchange-045"},{"speaker":"松本委員","kind":"質問・要望","question":"どこにあるかというところまでは確認していない。ここは所管が違うとは思いますけれども、そこの部分は連携して届出制というのも検討してほしいと求めましたが、いかがか尋ねました。","respondent":"森田生活安全担当課長","answer":"他の区では届出制があるです。他の区の担当者にもお伺いしながら、品川区で環境美化が悪化しないような方向を常々考えながら、調査・研究してまいりたいと思います。","id":"exchange-046"},{"speaker":"松本委員","kind":"質問・要望","question":"これらの講演会について、私も令和２年の決算特別委員会で取り上げさせていただいて、趣旨・目的のところは確認させていただきました。これはやはり、講演の対象は区民に絞ったほうがいいと思うのですが、いかがか尋ねました。","respondent":"島袋人権啓発課長","answer":"そのときの答弁にそごがあったら申し訳ないですが、募集は区民と区内企業者に該当する方にかけております。たまたま、林家たい平さんの場合はファンが多いということから、今でも区民の方・区内事業者の方を中心に応募していただいております。","id":"exchange-047"},{"speaker":"湯澤委員","kind":"質問","question":"私からは、１６７ページ、広報経費と、それから１７３ページ、成人式経費についてお伺いします。観光の観点と併せて、区のホームページにアクセスされる方をお出迎えしていただくというのはいかがか尋ねました。","respondent":"大澤広報広聴課長","answer":"現在の形式を変えるのはシステム的に難しいために分かれてしまっているのですが、今後少しでも使いやすくできるように研究はします。例えばチャットボットの活用の促進になるという面もあるかと思いますので、今後の可能性については検討してまいりたいと考えております。","id":"exchange-048"},{"speaker":"湯澤委員","kind":"質問","question":"チャンネルを開くとトップ画面にハタチの龍馬がアップされていて、やはり人気があって、わずか３日ぐらいで２,７００回の視聴再生となっていました。これは知ってほしい、トップに張りつけておくのもよいかと思いますが、いかがか尋ねました。","respondent":"大澤広報広聴課長","answer":"ＹｏｕＴｕｂｅですが、現在は、新着の動画と、再生回数の多い動画が、トップに来るように設定しております。所管でも、何を基準にして優先順位をどのようにつけるかということは大きな課題となると思いますが、出し方については検討してまいりたいと思います。","id":"exchange-049"},{"speaker":"湯澤委員","kind":"質問","question":"その特徴を活かして、例えば子どものレポーターが大人に鋭い質問を投げかけるとか、ご高齢のレポーターが若者に対して世代を超えて質問を投げかける。少し遊び心を持った企画も、これからの時代は必要になってくるのではないかと思いますが、ご意見を説明を求めました。","respondent":"大澤広報広聴課長","answer":"以前は高校生のレポーターがいたり、夏休みには中学生のレポーターに活動していただいたりというような取組みもしてまいりました。なかなか今、区民レポーターの方の活用というのが難しい状況ではありますが、再開の際には、委員のご提案も含めて検討してまいりたいと考えます。","id":"exchange-050"},{"speaker":"湯澤委員","kind":"質問・要望","question":"品川区の公式ＬＩＮＥについてもお伺いします。区民の１割を目指すとか、できる限りの区民に登録してほしいと考えておりますが、今後の目標などもあれば教えてほしいと求めました。","respondent":"大澤広報広聴課長","answer":"次の目標としては、よく言われている、人口の１割ということで、今の倍の４万人を目標に取り組んでまいりたいと考えております。委員のご提案も受けまして、現在ワクチンの集団接種会場等でご案内をお配りしておりますが、今後も機会を捉えて周知に努めてまいりたいと思います。","id":"exchange-051"},{"speaker":"湯澤委員","kind":"確認","question":"そこで伺いたいのですけれども、来年度、成人となる方に対して、いつどのように成人式があるということをお伝えするのか。気になって区のホームページなどを見て確認した人もいるかもしれないですけれども、広報紙などを活用して、いかがか尋ねました。","respondent":"古巻総務課長","answer":"委員は今、１８歳とおっしゃっていたのですが、２０歳で成人式をということで、区のほうではお知らせをしています。年齢については検討させていただきまして、成人式という名称にするかどうかはこれからの検討になりますけれども、二十歳の方のイベントの際には。","id":"exchange-052"},{"speaker":"湯澤委員","kind":"質問","question":"早いにこしたことはないと思いますので、お祝い事でもありますし、早めの周知をお願いしたいと思います。一生に１度の成人式でありますので、本人ではなくても交換ができるといった取組みも検討すべきではないかと思いますが、いかがか尋ねました。","respondent":"古巻総務課長","answer":"今後も例えばオンラインを併用するなどという形が続く可能性もありますし、様々に検討させていただいて、適切な形で執り行っていきたいと考えております。","id":"exchange-053"},{"speaker":"湯澤委員","kind":"質問","question":"品川区で育った成人の皆さんの門出でありますので、区が心を込めて祝ってあげる。そういった成人式になりますことを希望いたしまして、質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"つる委員","kind":"提案","question":"それから１７３ページ、１８９ページ、伺っていきたいと思います。今後タイミングを見て、モニュメント的なものを新たにつくる方向で検討ほしいと求めましたが、まずお考えを説明を求めました。","respondent":"古巻総務課長","answer":"委員ご指摘のとおり、確かに荏原地区・八潮地区には、その印が入っていないというような状況です。ご指摘を受けまして、何か工夫していけることはないだろうかということは検討してまいりたいと考えております。","id":"exchange-055"},{"speaker":"つる委員","kind":"提案","question":"それから義務教育学校の計１５校に、新たなそうした意識を確認できるような、そういう場を新たに検討ほしいと求めました。様々な観点を含めて、そういう名を冠した大会を実施してはいかがでしょうか、このような提案をさせていただきましたとの意見を述べました。","respondent":"古巻総務課長、中元スポーツ推進課長","answer":"区の様々な行事や施策に非常にたくさんご協力を頂いておりまして、先日も防災訓練を防災体験館でやったというようなお話も聞いております。庁内連携を致しまして、そういった形での催しといいましょうか… やはり区民の方が公募を通して広く参加できる大会を今後検討してまいりたいと考えておりますので、総務課とも連携させていただいて、そのような形も視野に入れて検討させていただきたいと存じます。","id":"exchange-056"},{"speaker":"つる委員","kind":"質問・要望","question":"本来であれば、これは事前に伺った中では１年延びたということで、いろいろなご意見を反映させていくというところを伺いました。この視点を基軸にしていただきながら、１年延びますので令和６年の配布に向けて、しっかりと推進してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"おくの委員","kind":"質問・要望","question":"そういう表示をしていただきたいのですが、その点、いかがでしょうか。この２点をお伺いしたいと思います。","respondent":"川島地域活動課長","answer":"その結果ですが、水を入れて重りにするようなタイプの設置型の看板みたいなものを、９か所ほど設置していただけるという話がついております。ただ、３月中ぐらいに設置ということなので、区民の方の利便性向上を図っていきたいと思ってあります。","id":"exchange-058"},{"speaker":"おくの委員","kind":"質問・要望","question":"水を入れて設置するような看板を設置してほしいと求めました。大きめのきちんと目立つものにしていただければいいと思うのですけれども、そこを考えていただきたいのですが、いかがか尋ねました。","respondent":"川島地域活動課長","answer":"古い表示もあるということですので、再度点検いたしまして、どんな工夫ができるか、何ができるかというところを再度点検していきたいと考えています。","id":"exchange-059"},{"speaker":"おくの委員","kind":"質問・要望","question":"そこで、壁に大きく、それこそ非常に大きく、ここが地域センター用の駐輪スペースだと表示するなどしていただきたいのです。この２点、いかがか尋ねました。","respondent":"川島地域活動課長","answer":"地域センターでも駐輪場が無料というのが分かりにくいということは認識しておりましたので、手作りの案内札を置いたり、それでも分かりづらいです。そのほか、さらに無料の駐輪場があるということが分かるように、周知も工夫をしていきたいと考えています。","id":"exchange-060"},{"speaker":"おくの委員","kind":"質問","question":"なぜ新しい荏原第一地域センターでは放送設備などが有料になり、また利用料も値上げになったのでしょうか。この点を伺います。","respondent":"川島地域活動課長","answer":"こちらは例えば第１集会室ですと料金は変更ないですし、第３集会室も、備品の料金が１回有料になったというようなご指摘だと思います。備品を有料にさせていただいているということで、新しくきれいな設備を使っていただくということなので、ご理解いただきたいと考えています。","id":"exchange-061"},{"speaker":"おくの委員","kind":"質問・要望","question":"今までは無料で、要するに部屋の利用料を払えばそれに附帯する設備として使えていたものが、お金を払わないと使えなくなるわけです。なるべく利用しやすいようにしていただきたいのですけれども、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"大沢委員","kind":"質問・要望","question":"それと１８３ページ、１６９ページ、品川区民憲章について伺いたいと思います。四点お伺いしたいと思うのですけれども、具体例を挙げますと、コロナ禍におきまして事業を遂行するためにどのような対策を打って行われたのか。","respondent":"川島地域活動課長","answer":"第２１回中学生の主張大会の実施の工夫ですが、参加者の人数も最低限度に絞らせていただきました。今後、発表の様子と表彰式につきましてはＹｏｕＴｕｂｅにもアップする予定です。","id":"exchange-063"},{"speaker":"大沢委員","kind":"質問・要望","question":"あるいは人との活気が失われつつある現状において、現下において、非常に工夫をして事業を行うということはいいことだと思います。中学生の主張大会ということで伺いましたけれども、１３の地域センターがあるわけで、そこの現状をお知らせほしいと求めました。","respondent":"川島地域活動課長","answer":"これは人を１か所に集めることなく実施することができましたということで、夏休み中、ＩＣＴを活用した地区委員会事業の一つだと考えています。","id":"exchange-064"},{"speaker":"大沢委員","kind":"質問・要望","question":"行政もそれに対するフォローをしていただきたいと思うのですけれども、地域活動課でやっていただいているということで、大変感謝しています。１８３ページですけれども、テーマ別意見交換会と課題解決支援業務についてお伺いするのですけれども、もう少し詳しくお答えいただきたい。","respondent":"川島地域活動課長","answer":"それで、結果につきましても報告書にまとめまして、配布して活用する予定です。こちらは、テーマ別懇談会の開催と併せまして、コンサルタント会社に業務委託をするような予定で、今、準備を進めております。","id":"exchange-065"},{"speaker":"大沢委員","kind":"質問・要望","question":"そこのところはなるべく、斟酌されて、仕掛けをしていただきたいと考えています。次の質問ですけれども、去年の７月からということでありますが、それについて状況や変化があったら説明を求めました。","respondent":"川島地域活動課長","answer":"駅の近くの非常に便利なところに移転したということで、多くのお客様に訪れていただいているというところが、何かあったというところだと思います。","id":"exchange-066"},{"speaker":"大沢委員","kind":"質問・要望","question":"特別区政３５周年記念ということで、前文および５項目、これはまさに区の施策に関わることであると私は今考えているところであります。この５つの基本線をしっかりと押さえながら、これは企画部になるのでしょうか、その辺の関係を教えてほしいと求めました。","respondent":"大澤広報広聴課長","answer":"今、委員がおっしゃったように、いつの時代も変わることなく次の世代に受け継いでいくものだと思っています。区への愛着と誇りを深めて住み続けていただきたいという思いと一致するということで、現在はシティプロモーションで普及啓発を図っております。","id":"exchange-067"},{"speaker":"大沢委員","kind":"質問・要望","question":"普及啓発という観点で質問をしたわけではなくて、しっかりと押さえて、区行政を行っていく必要があるのではないかと思っている。やはり広報広聴課のみならず、私も頑固なもので譲らないかもしれないですけれども、その辺りのお考えをもう一度お聞かせいただきたいと考えています。","respondent":"佐藤企画調整課長","answer":"今年度、ご案内のとおり、総合実施計画に関しましても、より具体的な施策の展開を入れてまいります。委員ご指摘の観点も踏まえて、総合実施計画でもそのようなバランスを捉えた事業展開を、全庁一体となって進めていきたいと考えています。","id":"exchange-068"},{"speaker":"大沢委員","kind":"質問・要望","question":"そこのところはしっかりと押さえながらやっていただきたいし、そこが皆の気持ちや頭の中にしっかりと残るような広報の在り方、あるいはその政策の進め方をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"小芝委員","kind":"提案","question":"私からは、１８５ページ、町会・自治会ＩＣＴ活用促進補助と、同じページの児童参加地域事業補助について、お伺いいたします。これまで、昨年の予算特別委員会で、町会や自治会の会館へのインターネット環境の整備に向けた提案などをさせていただきましたとの意見を述べました。","respondent":"川島地域活動課長","answer":"令和２年度に新設しました新型コロナウイルス感染症対策物品補助金の執行実績が、それを参考にしまして５０町会分を、まず予算計上しました。多くの町会に活用していただきたいという思いでやっているところです。","id":"exchange-070"},{"speaker":"小芝委員","kind":"質問・要望","question":"利便性を追求するには、例えばＩＣＴに長けた職員による相談対応などを行っていただきたいと考えますが、いかがでしょうか。その紹介も含めて、品川区からアプローチしていただきたいと考えますが、いかがか尋ねました。","respondent":"川島地域活動課長","answer":"区の職員が対応できるようなご相談にも、こちらはスマホやパソコンの講習会の開催経費につきましても、区で補助対象にしております。情報化格差の解消に役立てていただき、町会・自治会自身もどんどん積極的にＩＣＴを活用していっていただけるようになればと思ってあります。","id":"exchange-071"},{"speaker":"小芝委員","kind":"質問","question":"続きまして、児童参加地域事業補助について伺います。その効果というのは親にも波及し、その親を町会に引き寄せる効果があると認識しておりますが、その辺りの考えを教えていただけますか尋ねました。","respondent":"川島地域活動課長","answer":"何か将来の役員になるような、候補の方に声をかけたり、一緒に活動していくきっかけになることが多いと聞いてあります。","id":"exchange-072"},{"speaker":"小芝委員","kind":"質問","question":"従来型の行事を踏襲したままでは、なかなか人が集まらなくなるようなケースも出ておりますし、また負担になることもあります。より一層、また今度は町会・自治会の活性化につながると考えますが、いかがか尋ねました。","respondent":"川島地域活動課長","answer":"町会・自治会の先進事例というか、紹介ということになりますと、３月中に町会・自治会活動の事例集を発行する予定です。令和４年度にも、こちらはそういった考えに基づきまして、私どもも仕事を進めていきたいと考えております。","id":"exchange-073"},{"speaker":"小芝委員","kind":"提案","question":"どうしても、また提案がないと、やはり現状としてあります。２０１の町会があります、ぜひ後押ししていただきたいと思いまして、質問を終わらせていただきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-074"},{"speaker":"こんの委員","kind":"質問・要望","question":"１８５ページ、２０７ページ、マイナンバーカード普及促進の３点についてお伺いします。そこで、品川区の現状はどのような状況か尋ねました。","respondent":"島袋人権啓発課長","answer":"ＤＶ相談件数の総括表ですが、今年度の１月まででは、相談件数各課等々を含めまして１７９件上がっているところです。守秘義務もございまして、相談を委託している関係上、こちらから申し上げることは控えします。","id":"exchange-075"},{"speaker":"こんの委員","kind":"質問","question":"なぜこのような体制であるかというところの経緯をお聞きしたいのと、相談をためらうというか、この相談体制についてお考えをお聞きしたいと思います。全国女性シェルターネットでは、専門相談の資格はどのような形か尋ねました。","respondent":"島袋人権啓発課長","answer":"カウンセリング相談・ＤＶ相談を増やしていきたいと考えているところですが、東京都ウィメンズプラザを紹介したり、させていただいたりしています。よろしくお願いします。","id":"exchange-076"},{"speaker":"こんの委員","kind":"質問・要望","question":"実態はどのようになっているのか、品川区としては委託ですから、その点どのような状況なのかもお聞かせほしいと求めました。こうしたことも要望するわけですが、いかがか尋ねました。","respondent":"島袋人権啓発課長","answer":"相談内容から、しかるべき支援にすぐに回したほうがよい場合は、すぐにそちらの支援先をご案内しているというところになってあります。入り口の相談に対応していますので、すぐにしかるべき支援先を紹介して、迅速に対応しています。","id":"exchange-077"},{"speaker":"こんの委員","kind":"質問・要望","question":"その辺のところをどうかご理解いただいて、寄り添った対応をお願いしたいという要望で、この質問をさせていただいたところです。日曜開庁のときにもそれをしてくださるのかどうかというところで、ある端末でやっていただくのですが、その辺をお聞きしたいと思います。","respondent":"木村戸籍住民課長","answer":"当初はまず、区役所の特設会場で受付を行うような体制を考えておりまして、もちろん日曜日も行います。それから、端末を持ってこられている方についても支援ということで、ご案内をさせていただこうと考えています。","id":"exchange-078"},{"speaker":"こんの委員","kind":"質問・要望","question":"どちらかで必ず本人確認をするという作業で交付がされていると思いますけれども、そこで本人確認を取っていただいて、交付時には郵送してさしあげる。今はそうなっていないと思うのですけれども、いかがか尋ねました。","respondent":"木村戸籍住民課長","answer":"後で郵送という形は十分取れるとは考えておりますけれども、日時を指定したり、必ずその場にいていただかないといけないという縛りがあります。ですので、郵送の部分で少し課題がありますけれども、引き続きこれは検討させていただきたいと思います。","id":"exchange-079"},{"speaker":"西本委員","kind":"質問・要望","question":"非常にクレームが多くて、移設をしていただけないかということでありますが、そのお考えはありますでしょうかということです。１年間、設備が古くなっていると思って確認したいのですが、プロジェクターは常備されますか。","respondent":"森田生活安全担当課長、篠田文化観光課長、黒田財政課長","answer":"いずれにしましても、受動喫煙に配慮した形でということで、いろいろと検討しているところではあります。先ほどと同じ話になってしまいますけれども… コロナ対応の各種物品等の設置ですけれども、ご指摘の点も踏まえながら、様々考えてまいりたいと思っているところです。… 今回の令和４年度の当初予算につきましては、さらに財源があれば積み増しするというような状況で、予算を編成しています。","id":"exchange-080"},{"speaker":"西本委員","kind":"質問","question":"要は、長期にわたっての計画があって、基金というのがあるのではないのですかという。その顔に対して、やはり人事課の中で、きっちりと指導し、調査し、研修などをしていくというのも必要ではないかと思うのですが、いかがか尋ねました。","respondent":"黒田財政課長、篠田文化観光課長","answer":"総合実施計画を策定する中で、このぐらい経費がかかるというところを見込みながら、運営を進めているです。 指定管理あるいは委託という形になっていますので、なかなか人事課が絡む余裕は、難しいのかと思っています。今後、引き続き慎重に、きちんとできるように対応してまいりたいと考えているところです。","id":"exchange-081"},{"speaker":"西本委員","kind":"質問","question":"私は、そこは人事課でしっかり見ていく必要があるのではないかと思うのですが、人事課としての考え方をお聞きしたい。","respondent":"崎村人事課長","answer":"特に委託の部分につきましては、そこの所管と委託会社の中で、接遇についてしっかりと教育・研修等々を行っていくというスタンスです。","id":"exchange-082"},{"speaker":"西本委員","kind":"意見","question":"いずれにしても品川区の顔になりますので、委託であろうと何であろうと区民には変わりません。同じ対応を致しますので、それぞれの所管がしっかり指導していただきますようお願いして終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-083"},{"speaker":"のだて委員","kind":"質問・要望","question":"１６７ページから、１７３ページ、ロシアのウクライナ侵略について伺います。他国を牽制する行為は非核平和都市品川宣言に反するという、この立場に立った意思表示が必要だと思いますけれども、いかがか尋ねました。","respondent":"古巻総務課長","answer":"非核平和都市品川宣言ですけれども、核兵器の製造・配備・持込みを認めないといったことで、核兵器廃絶と恒久平和確立の悲願を込めて宣言しています。","id":"exchange-084"},{"speaker":"のだて委員","kind":"質問・要望","question":"こうした反戦・平和を求める人々と連帯して、各自治体以下も含めて、そしてロシアを包囲していくということが重要だと思います。そのためにも、国際連合憲章に違反しており、非核平和都市品川宣言にも反するという立場に立つことが重要だと思うのですけれども、いかがか尋ねました。","respondent":"古巻総務課長","answer":"何か、食い違っているとは思わないのですけれども、非核平和都市品川宣言の趣旨に則りまして、今回のロシアへの対応については、しっかりと対応していきたいと考えております。","id":"exchange-085"},{"speaker":"のだて委員","kind":"質問・要望","question":"区として、どういった仕事内容・職種に会計年度任用職員を適用しているのか。区内の会計年度任用職員の人数と、そのうち女性の人数を伺います。","respondent":"崎村人事課長","answer":"相談業務、軽作業などの、常勤職員を補助・補完する業務といったところに従事しています。大体１,３５０人ほどに、会計年度任用職員として従事いただいているところでございまして、中でも女性の方は１,１５０名ほどいらっしゃいます。","id":"exchange-086"},{"speaker":"のだて委員","kind":"質問","question":"単年度契約なので、４月からの計算になっていて、手当が満額出ていないという声を頂いたのですが、これが本当かどうか、そこを伺いたいと思います。１年ごとに履歴書を逐一出さないといけないということで、簡略化していくことができないか、伺います。","respondent":"崎村人事課長","answer":"委員もご存じのように、その会計年度ごとに職を設置することの必要性を検証しまして、新たに職を設置して公募によって選考を実施しています。そういった方については、一応、申込書についてはご提出頂いているのですけれども、少し省力化は図っているところです。","id":"exchange-087"},{"speaker":"のだて委員","kind":"質問・要望","question":"さらなる簡略化を求められているのかと思いますので、毎年、全員公募する方式というのは改めるべきだと思います。そういった方でも給料が上がらないということで、ぜひ昇給制度をつくっていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"崎村人事課長","answer":"ですので、区としても、その考え方に基づいて、先ほどもお話ししましたように、職の必要性を吟味した上で、毎年度、採用選考を実施しています。","id":"exchange-088"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひここは昇級制度を考えてほしいと求めましたし、また休暇の面で、正規職員と会計年度任用職員に違いがあります。その違い、会計年度任用職員が無給休暇となっているところを改善していただきたいと思うのですが、何があるのか、伺います。","respondent":"崎村人事課長","answer":"休暇については、確かに無給となっている部分がありますけれども、今回、出産・育児の部分では有給化するところなどもありますので、今後も引き続き対応してまいります。","id":"exchange-089"},{"speaker":"西村委員","kind":"質問","question":"しながわ学びの杜の新規取組について伺ってまいります。この講座がどのような内容になるのか、伺います。","respondent":"篠田文化観光課長","answer":"これまでも障害者の方に対しては、ある程度以上の重い方というのはなかなか受入れが難しいということで、これまでなかなか設定できませんでした。半年間、月２回で計１２回ぐらいの講座を想定して、実施してまいりたいと考えているところです。","id":"exchange-090"},{"speaker":"西村委員","kind":"質問・要望","question":"我々の会派で２年前に視察に伺った、御殿場の障害者支援施設があります。今後、様々な障害をお持ちの方への講座の広がりをご検討ほしいと求めましたが、区のお考えを説明を求めました。","respondent":"篠田文化観光課長","answer":"どのような課題があるかというのは、まだ実際に受入れをしていないところなので、なかなか見えてこないところです。ただ、今後、やはりその辺について、様々展開をしていく方向性というのを見据えながら、今回、実施してまいりたいと考えているところです。","id":"exchange-091"},{"speaker":"西村委員","kind":"提案","question":"様々な障害をお持ちの方の講座の広がりというのをご提案させていただきたいと思っておりまして、己書というデザイン書道を楽しんでおられました。もう一度ご答弁をお願いいたしますとの意見を述べました。","respondent":"篠田文化観光課長","answer":"私どもも、そういった形でのニーズというのは広く見ているところでもあります。困難性が伴うものもあると考えられますので、その辺の課題もしっかり研究しながら、今後対応してまいりたいと考えているところです。","id":"exchange-092"},{"speaker":"西村委員","kind":"質問・要望","question":"こちらは、ぜひともご検討ほしいと求めましたので、要望します。障害者スポーツに関しましても伺ってまいりたいと思いますが、今、戸越体育館でフリー教室を様々に行っていただいていると思います。","respondent":"中元スポーツ推進課長","answer":"今までですと、ソフトバレーボールやキックベースボール、ボッチャなどに取り組んでいるところです。","id":"exchange-093"},{"speaker":"西村委員","kind":"質問・要望","question":"続きまして、広報広聴費から１点、お伺いします。こういったところのユーザビリティも求められるようになってきていると感じておりまして、区のお考えと、念のため確認させてください。","respondent":"大澤広報広聴課長","answer":"封筒のＱＲコードの不具合というのは、私のほうでは今、確認できていないのですが、そのような事実があれば、ＱＲコードをせっかく印刷しても意味がありませんので、今後、調査等をかけて修正していきたいと思います。","id":"exchange-094"},{"speaker":"西村委員","kind":"提案","question":"いっぱいのＱＲコードをスマートフォンがキャッチしてしまうということだと思いますので、ぜひともご確認ほしいと求めました。そのように、アプリをＬＩＮＥと同期させていくということが可能なのかどうか、お伺いさせてくださいとの意見を述べました。","respondent":"大澤広報広聴課長","answer":"各所管でつくっているアプリと区の公式ＬＩＮＥ、いろいろあるのですが、それの統合というのはなかなか難しいと聞いてあります。","id":"exchange-095"},{"speaker":"西村委員","kind":"提案","question":"私もすごく難しいと思っておりまして、実際にＬＩＮＥの方にもお話を伺ったりしております。周知の努力が必要になってきますので、何かいいアイデアと工夫を私も考えまして、またご提案させてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-096"},{"speaker":"渡部委員","kind":"質問・要望","question":"大体どういう調査を、この４万円か何かで調査がかかってくるのか。そもそもこれはどういうもので、何のためにやっているのか、その辺をご説明ほしいと求めました。","respondent":"川島地域活動課長","answer":"国の就業・不就業の状態を明らかにし、こちらも総務省が５年ごとに実施するということで、令和４年調査で１８回目になるものです。学校に関する基本的事項を調査するということで、区内の公立・私立合わせて９３校に調査し、学校から回答していただくような形の調査になります。","id":"exchange-097"},{"speaker":"渡部委員","kind":"質問","question":"今日お伺いして、多分５年に１度の調査などというと、例えばもうネットでできるようになっていますなどというのは大体どんな感じか。やはり、国の調査というのはどうしても、ある程度手書きで返していくような仕組みになっているのかどうなのかだけ、分かれば教えてほしい。","respondent":"川島地域活動課長","answer":"国の行う調査ですけれども、国勢調査も非接触型の調査という形で、インターネット回答と郵送主体になるというように、大きく変わってあります。調査によってまた方針が変わってくるとは思うのですけれども、インターネットや郵送での回答が中心になっておりますので、時代や。","id":"exchange-098"},{"speaker":"渡部委員","kind":"質問","question":"伺ったらシティプロモーション関係のものが流れているという話なのだけれど、途中で広告が入ると、その広告にいらっとする人が大半だと思うのです。ですから、その辺はどういう仕組みでどうなっていたのか、教えてほしい。","respondent":"大澤広報広聴課長","answer":"ＹｏｕＴｕｂｅですが、令和３年６月１日より、ＹｏｕＴｕｂｅが利用規約を変更しまして、収益のない動画にも広告が出るようになってあります。配信実績ですけれども、一定のシティプロモーションの効果があると思いたいところではあります。","id":"exchange-099"},{"speaker":"渡部委員","kind":"質問","question":"あれは仕組みとして、５秒は見ないと駄目じゃないですか。ワクチン接種は何月何日までとか、そういう大事な情報がぱっと入るような仕組みがいいと思うのですけれど、どうか尋ねました。","respondent":"大澤広報広聴課長","answer":"ＹｏｕＴｕｂｅの広告の配信は始めたばかりですので、今後どのような活用の仕方があるのか研究してまいりたいと考えております。","id":"exchange-100"},{"speaker":"渡部委員","kind":"確認","question":"もうやめますけれど、勝負は５秒ですから。この内訳の確認をさせてください。","respondent":"大澤広報広聴課長","answer":"デジタルサイネージの利用料ですけれども、現在、区内に２９台ありますので、そのリース料となっています。","id":"exchange-101"},{"speaker":"渡部委員","kind":"質問","question":"今の時代ですから、この辺のものをどんどん増やして、区の情報を発信していく。まちの活性化に使えればいいのになどと、ずっと思っているのですけれども、その辺は少しずつ進歩しているのか尋ねました。","respondent":"大澤広報広聴課長","answer":"最初に設置したものが、今後検討ということになるかと思いますけれども、屋外設置等も視野に入れて検討していく予定です。","id":"exchange-102"},{"speaker":"渡部委員","kind":"質問・要望","question":"もう、その時点で私自身は、個人情報の確認が１００％取れている。先ほど言った本人確認の部分など、その辺はどういうふうに捉えていらっしゃるのか、説明を求めました。","respondent":"堀越企画部長","answer":"個人情報保護に関する法改正も実施されて、個人情報を保護しながら、いかにデータを流通させて利便性を上げていくか。産業の活性化といいますか、外国と伍していくというような観点で、国でも検討を進めてあります。","id":"exchange-103"},{"speaker":"渡部委員","kind":"質問","question":"誰かが持っていって、番号は何番だったっけと教えてしまったら使えてしまうので、それだけではセキュリティは効かない。部長がおっしゃったように、それで全てが解決できる問題だと私は信じていますので、様々活用ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-104"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"令和４年度の組織改正について、それから１７６ページの人事管理費から、保健所職員の労働実態や職員体制について伺いたいと思います。「福祉」の文言を課名からなくすわけですけれども、「福祉」とは何か、区の認識を伺いたいと思います。","respondent":"佐藤企画調整課長","answer":"区はこれまで、障害者福祉課の１つの課と、１担当課長制といった体制で施策を推進してまいりました。多くの方々の幸せという意味だと認識しておりまして、個別の相談や給付事業をやる課として障害者支援課と、より分かりやすい名称にしたです。","id":"exchange-105"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"国が進める社会保障は自助・共助で行い、社会保障の逆行の流れに変えるものではないかと思いますけれども、そのことについてはいかがでしょうか。この一連の流れではないのか、改めて伺いたいと思います。","respondent":"佐藤企画調整課長","answer":"区として定めております障害福祉計画に沿いまして、施設整備を計画的に進めていく必要があると考えております。そういったところで今回、先ほどご説明したとおり、２課体制として、より積極的に、効率的に、施策を推進していくという趣旨です。","id":"exchange-106"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう流れで今回の障害者福祉も「福祉」という名前を変えたのではないかとお聞きしていますので、その点についてもお伺いしたいと思います。「障害者福祉」の文言を変えないよう、改めて求めたいと思いますが、そのことについても伺いたいと思います。","respondent":"佐藤企画調整課長","answer":"組織を設置する場合に、また事業の継続性も含めまして、適切な名称を考えているところです。来年４月からは、障害者施策推進課と障害者支援課で進めていきたいと考えております。","id":"exchange-107"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは、ここだけで終わるものではないので、本当に人権保障という立場に、ぜひとも立っていただきたいということで求めておきたいと思います。平均残業時間と最大の残業時間はそれぞれ何時間なのか、伺いたいと思います。","respondent":"崎村人事課長","answer":"コロナ対応に当たりました保健予防課の職員の中で、保健師につきましては８人中６人、事務につきましては８人中５人という状況でございました。月平均ですけれども約２８時間だったものが、令和２年度には約５６時間、今年度も約５５時間というような状況です。","id":"exchange-108"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ずっと要望し続けてきましたけれども、下から２番目という少なさで、平均までに１２人足りないと。その方針はあるのかについて伺いたいと思います。","respondent":"崎村人事課長","answer":"来年度の採用として当初７名を採用予定としていたところですけれども、今現在５名、採用予定です。辞退がございまして、現在のところ、５名の採用予定といったところです。","id":"exchange-109"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"厚生労働省が２０２０年３月に、自治体保健師の人材確保ガイドを出しているのです。退職者数は１０年前の１.５倍に増えているという中で、改めて保健師の人材確保策をつくることが必要ではないかと思うのですが、いかがでしょうとの意見を述べました。","respondent":"崎村人事課長","answer":"区として人材確保策といいますと、保健師については特別区の採用選考になりますので、なかなか確保策を策定するというのは難しいかと思います。","id":"exchange-110"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"１７９ページ、人事管理費の中の、代替職員の雇用制度についてお伺いします。検討の結果はどのような結論になったのか、教えてほしいと求めました。","respondent":"崎村人事課長","answer":"区では、課の出先施設ごとに１名ずつ選出していただきまして、人事課において令和２年１２月に意見聴取会を実施して意見を頂いたところです。その意見の中で、派遣期間を３年間延長して、令和３年９月から令和６年９月末までの派遣延長となったところです。","id":"exchange-111"},{"speaker":"高橋（し）委員","kind":"質問","question":"各職場の代表と区分代表、ここのところは、もう一度お願いします。あるいは中の話合いですか、その方が代表で出て、今お話のあったような協議をするという仕組みになっているということでよろしいのか尋ねました。","respondent":"崎村人事課長","answer":"失礼いたしました。まず１名、また保育園であれば保育園の代表といったところで区分代表を選出して、意見聴取を実施したという内容です。","id":"exchange-112"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、現状はそういった形になっているわけですけれども、また３年経てば同じようなことが、期限がやってきます。そのときに向けて、どのような対応、現在、協議したばかりですけれども、３年後についてはどのような見通しがあるのか尋ねました。","respondent":"崎村人事課長","answer":"こちらは、今度３年間、延長になったときに、今度は令和５年度中にこういった手続きが必要になってくると認識しております。まずは区の職員労働組合に、もし職員団体が過半数団体でないということが分かりましたら、今回と同様の手続きで進めていきたいと考えております。","id":"exchange-113"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"派遣労働者の方々は、区全体で１３４名の方々がおられると伺っています。これは、年度末に策定すると伺っていますが、現状、令和４年度の計画はもう策定されたのか尋ねました。","respondent":"今井監査委員事務局長","answer":"監査基準に基づく監査計画ですが、毎年度、翌年度の計画につきましては、大体３月までに策定するという形になっております。現時点ではまだ策定はしていない状況です。","id":"exchange-114"},{"speaker":"高橋（し）委員","kind":"提案","question":"３月にというお話がありましたが、問題意識を持って能動的に、こういう監査という提案をすることが行われていると思います。私は監査の中身が分かりませんので、その機会というのは、どのような場であるのか尋ねました。","respondent":"今井監査委員事務局長","answer":"監査委員の皆様におきましては、監査計画に基づきまして、細かい内容につきましても、それぞれの監査について監査委員協議会の中でご決定いただきまして、監査を実施していただいているところです。","id":"exchange-115"},{"speaker":"高橋（し）委員","kind":"提案","question":"ぜひ、その提案等を活かす形で計画を立てていってほしいと求めました。しかし品川区では、それが昨年度も出ていないのですが、何か公表してはいけないという法律上のルール等があるのか尋ねました。","respondent":"今井監査委員事務局長","answer":"監査計画につきましては、地方自治法や監査基準などでも、公開について特に定めはございません。監査委員の皆様が、監査委員協議会の中で決めていかれる内容だと承知しております。","id":"exchange-116"},{"speaker":"高橋（し）委員","kind":"提案","question":"以前から、公表についてはいろいろご提案申し上げて、そういったホームページにアクセスすることができていると思います。区民の方々にとって分かりやすい監査をさらに進めるという点で、お願いしたいのですが、その点についていかがか尋ねました。","respondent":"今井監査委員事務局長","answer":"区民に分かりやすいホームページの充実につきましては、これは既に検討を進めております。ただし、監査計画につきましては、今承りました内容につきまして、監査委員にお伝えしてまいるという形になると思います。","id":"exchange-117"},{"speaker":"若林委員","kind":"質問・要望","question":"１８３ページ、地域振興事業の中で、特にマンション管理組合等実態調査について伺いたいと思います。この辺を、すみません、４点ぐらいになりましたけれども、お聞かせほしいと求めました。","respondent":"川島地域活動課長","answer":"町会につきましては冊子をお配りするだけではなくて、町会長会議の場で説明もさせていただいて、活用できるようにしていきたいと考えています。こちらは当然、先行事例でしている町会もありますが、そういった接点づくりになるように活かしていきたいと考えています。","id":"exchange-118"},{"speaker":"若林委員","kind":"質問・要望","question":"１００戸以上ということで取りあえず始められるということで、しっかり確認、町会支援・自治会支援をよろしくお願いしたいと思います。一般質問でも紹介しましたが、まちづくりの部門に確認したところ、いわゆる区分所有マンションが７万数千棟あるのです。","respondent":"川島地域活動課長","answer":"１割ぐらいが区内在住の方かと。どんな活動をしているかというところまでは、なかなか話を聞き取りしているわけではないので、把握していない状況です。","id":"exchange-119"},{"speaker":"若林委員","kind":"質問・要望","question":"協賛団体、それからＬＥＤの数の関連性があるのかどうかというのを教えていただきたいのが１つと、歩道を造った工事が終わっていると思います。この辺のご認識はあるかどうか、お聞かせほしいと求めました。","respondent":"篠田文化観光課長","answer":"今年度の実施に関しまして、それぞれのお考えがあって参加されることと思いますので、もしかしたら反映されているのかと。検討されていると伺っていますので、一定程度、考えがあったのではないかと。","id":"exchange-120"},{"speaker":"松澤委員","kind":"質問","question":"新規事業の２点をお聞きしたいのと、あと１８９ページの生活安全推進事業の中から、あと生活安全パトロールについてお聞きいたします。特殊詐欺の増加における注意喚起がありまして、どうして増加傾向になったのか、最近の全国の動向とともに説明を求めました。","respondent":"森田生活安全担当課長","answer":"それを持っていって被害に遭われるというところだったのですけれども、これはご自宅に犯人が来るという意味では、非常に犯人側にリスクがあるです。令和３年度になりますと、それが一因になっているのかということで、私どもでは認識しております。","id":"exchange-121"},{"speaker":"松澤委員","kind":"質問","question":"そういった報道が１月にあったと思います。たしか５０件を目標にしていたかと思いますけれども、また、普通の自動通話録音機の貸出し状況の現状を説明を求めました。","respondent":"森田生活安全担当課長","answer":"現在までに約５,０００台の貸出しをしています。ＡＩ型自動通話録音機の貸出しの状況につきましては、現在まで１９台ございまして、今年度はあと３台、設置の予定です。","id":"exchange-122"},{"speaker":"松澤委員","kind":"質問・要望","question":"そしてまた時間、あとルートが決まっているのか、教えていただきたい。そういうところも説明を求めました。","respondent":"森田生活安全担当課長","answer":"現在、生活安全サポート隊につきましては、委員のおっしゃるとおり、１９名で対応しています。時間につきましては、午前７時３０分から午後１０時まで、様々に早番・遅番・日勤に対応しています。","id":"exchange-123"},{"speaker":"松澤委員","kind":"提案","question":"ＡＩ型自動通話録音機の話をしましたが、私から提案したいのが、このパトロールにもＡＩを導入するというのは画期的ではないかと考えています。やはりこの６年間で、ルートの固定化というのですか、ご見解を説明を求めました。","respondent":"森田生活安全担当課長","answer":"ＡＩのパトロールという、１つの方法であるとは思います。いろいろな不審者情報がありますけれども、ひとつ今後の参考とさせていただきながら、今後も品川区における安心に寄与してまいりたいと考えています。","id":"exchange-124"},{"speaker":"松澤委員","kind":"質問・要望","question":"ネットを利用した、いわゆる電子回覧板というのですか、そしてウェブ会議の導入の動きが進んでいました。地域センターで開催されます町会・自治会長会議ですか、今までも月１回やっていると思うのですけれども、連携を一番望んでいるのがＰＴＡです。","respondent":"川島地域活動課長","answer":"その辺に町会の役員の方を呼ぶとか、若い方を呼ぶことが可能かどうかというのは、必要性も含めまして検討していきたいと思います。引き続きの良好な関係というのは、またさらに深まっていくのではないかと考えていますので、その辺は推移を見守っているところです。","id":"exchange-125"},{"speaker":"大倉委員","kind":"質問・要望","question":"私からは、１８９ページの歩行喫煙防止推進経費で、品川区歩行喫煙および吸い殻・空き缶等の投げ捨ての防止に関する条例について伺えればと思います。１６７ページの広報経費で、メールやＳＮＳを通じた区民への情報発信というところを伺えればと思います。","respondent":"古巻総務課長","answer":"日本赤十字社で寄附の動きがあるということで、日本赤十字社を所管しております福祉計画課で、窓口という形で対応しているとは伺っております。そういった形でのご案内をしていると認識しておりますので、そちらは日本赤十字社と連携しまして、周知していきたいと考えております。","id":"exchange-126"},{"speaker":"大倉委員","kind":"質問","question":"区民の方から寄附先について質問されることが多かったので、ホームページのトップページに、その辺についてはどのようにお考えでしょうか。では、その点だけお願いします。","respondent":"古巻総務課長","answer":"ホームページは福祉計画課で出しているので、その辺りは連携といいましょうか、福祉計画課とも調整しまして、分かりやすくということも含めて、どういった形でホームページに掲出するかは検討させていただきたいと思います。","id":"exchange-127"},{"speaker":"大倉委員","kind":"質問・要望","question":"情報を確認して、改めてそうした情報の出し方の確認をしっかりと行っていくということについて、お聞かせほしいと求めました。第５条３項で、これはしっかりと回収容器を自動販売機の横に設置してもらうべきだと思うのですが、いかがか尋ねました。","respondent":"大澤広報広聴課長、森田生活安全担当課長","answer":"広報広聴課でも原因が分からない場合もあるのですけれども、その辺に関しましては、今後も気をつけて配信していきたいと考えています。１週間前には各所管から申請を上げていただけるようにご協力いただいて… 回収容器の設置です。引き続き、関連団体に対しまして、回収容器の設置などにつきましても周知してまいりたいと考えています。","id":"exchange-128"},{"speaker":"大倉委員","kind":"質問・要望","question":"ぜひ連携して、品川区の自動販売機の横に、しっかりと回収ボックスを置いてもらえるように取り組んでほしいと求めました。ぜひ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-129"},{"speaker":"藤原委員","kind":"質問・要望","question":"自動販売機の横に回収容器が置いてあるかどうか調べてほしいと要望しましたけれども、それはどうなっているでしょうかということと。それと、経験者採用というシステムといいますか、採用していると思うのですけれども、なぜ経験者採用を実施しているのか、説明を求めました。","respondent":"森田生活安全担当課長、崎村人事課長","answer":"いずれにしましても、自動販売機の横の回収容器の設置などにつきましては、引き続き協会に要請はしてまいりたいと考えています。防犯の面からも目を持っていただくというのが目的ですので… 国に準じて実施するというところで妥結したところですので、可決を頂きましたならば、以降２年ごとに１歳ずつ引上げになるといったものです。","id":"exchange-130"},{"speaker":"藤原委員","kind":"質問・要望","question":"「吸い殻・空き缶等の投げ捨ての防止に関する条例」と入っているわけですから、ここと、これでは名ばかりの条例になってしまうじゃないですか。今後もっとどういうふうにしていくかというのを考えて、その辺を考えていってもいい時期だと私は思うのですけれども、いかがか尋ねました。","respondent":"崎村人事課長、森田生活安全担当課長","answer":"６０歳以後の翌年度から、給与については７割水準となるといったところで、支給時期が１歳ずつ遅くなってくるものです。６０歳以降の任用ですとか給与退職手当に関する制度について… いずれにしましても、委員が懸念しているようなことにならないように、私どもとしましても対応してまいりたいとは思っております。今後とも事業を継続してまいりたいと思います。","id":"exchange-131"},{"speaker":"藤原委員","kind":"質問・要望","question":"ここはやはりもう、今日３人の委員が質問しているわけですから、どうしてもやっていただきたいのです。定年延長という言葉が出てくるのですけれども、結局は再任用とあまり変わりないと思っていてよろしいのか尋ねました。","respondent":"森田生活安全担当課長、崎村人事課長","answer":"そういった、空き缶がころころ転がっているとか、そういった状況がありましたら、つぶさに対応してまいりたいと考えています。引き続き要請はしていきたいと考えていますし、私どものほうでも勘案しまして… その年齢まで、６１歳、６２歳まで職員として働くといった部分になります。常勤職員、今の６０歳未満の職員と同様に支給されますので、そういった部分の待遇面は改善されているかと考えています。","id":"exchange-132"},{"speaker":"高橋（伸）委員","kind":"質問","question":"１８９ページ、１９３ページ、お伺いします。初めに、１７３ページ、全国自治体との連携事業についてお伺いいたします。","respondent":"古巻総務課長","answer":"計画はしていたのですけれども、なかなかコロナ禍という中で実施できなかったということで、予算上はちょっと減額しております。ですので、来年度の令和４年度につきましては、坂井市との交流ツアーはまたしっかりと復活させていきたいという流れで、今考えているところです。","id":"exchange-133"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これは全国を見ると、北海道とか九州とか、特に北陸や中越とか中部地域の自治体が加盟していないと思うのです。幾つかお分かりになれば、この先考えている協定というか、交流を結ぶような自治体とかがあるのであれば教えてほしいと求めました。","respondent":"古巻総務課長","answer":"具体的な予定はございませんけれども、様々に連携ですとか、協定を結んでいる自治体もあります。連携が必要な部分については進めていきたいと考えておりますし、来年度につきましてはしっかりと復活させていきたいと考えているところです。","id":"exchange-134"},{"speaker":"高橋（伸）委員","kind":"確認","question":"松澤委員に対してのご答弁のことで確認ですけれども、先日ありました区民委員会で、現在まで１７件設置しておりますという報告がありました。先ほどのご答弁だと１９件ということですけども、これは１９件でいいのかどうか、確認だけ。","respondent":"森田生活安全担当課長","answer":"区民委員会のご報告のときには１７件でございまして、その後、２月に設置が２件ございました。それで１９件です。","id":"exchange-135"},{"speaker":"高橋（伸）委員","kind":"意見","question":"来年度予算ですと、４３０万円余。この中でＡＩ型特殊詐欺対策アダプタの予算というのはどれぐらいなのかというのをお示しほしいと求めました。","respondent":"森田生活安全担当課長","answer":"１台８,８００円となっておりますので、５０台分で４４万円ということで予算を計上しています。","id":"exchange-136"},{"speaker":"高橋（伸）委員","kind":"質問","question":"続きまして、新規事業の１９３ページ、荏原地区イベント事業開催経費について、新規事業のまちぐるみ文化イベントについてお伺いいたします。それで、これは何月ぐらいを想定しているのかというのをお聞きしたいと思います。","respondent":"篠田文化観光課長","answer":"先ほど委員から、武蔵小山の各施設、事業概要のところで説明しているところのお話もございました。もし可能であれば、それとも同じタイミングでやれれば、荏原地区全体が盛り上がるのではないかというようなところも考えているところではあります。","id":"exchange-137"},{"speaker":"高橋（伸）委員","kind":"質問","question":"武蔵小山というと、本当に荏原地区の文化イベントなのだけれど、ちょっと遠いよねという声も恐らく上がると思うのです。これから周知をきちんとやっていただければと思っているのですけれども、そこをちょっと詳しく教えてほしいと求めました。","respondent":"篠田文化観光課長","answer":"旗の台から少し遠いところではあるのですけれども、荏原文化センターなども含めて開催してまいりたいと考えています。ですので、幅広い荏原地区全体に情報が行き渡るように、私どもも対応してまいりたいと考えているところです。","id":"exchange-138"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"周知の部分で、町会・自治会、そして商店街にも本当に十二分に行き渡るように周知してほしいと求めました。お願いしたいと思うのですけれども、改めてもう一回、ご答弁を。","respondent":"篠田文化観光課長","answer":"今回のイベントの実施に当たりましては、開催の主体を、今、検討中ではありますけれども、実行委員会形式でやれたらいいと思ってあります。","id":"exchange-139"},{"speaker":"塚本委員","kind":"質問","question":"１９３ページの区民作品展、それから１８５ページ、町会・自治会ＩＣＴ活用促進補助についてお伺いしたいと思います。初めに１８９ページの歩行喫煙防止推進経費ですけれども、どこまでしっかりと対応できるのかというような観点でお伺いしたいと思います。","respondent":"森田生活安全担当課長","answer":"路上喫煙禁止・地域美化推進地区につきましては、おおむね、マナーアップ啓発も実施、また生活安全パトロールも実施しています。目黒駅であるとか、１９駅を全９地区に分割して、シルバー人材センターの方々に回っていただいて、やっていただくというようなこともしています。","id":"exchange-140"},{"speaker":"塚本委員","kind":"質問・要望","question":"現在の条例でどこまで、例えば警察等で、そういったことに関して対応していただけるのかというところをお伺いしたいと思います。こういうこともやっていただきたいという思いがあるのですけれども、現状いかがな認識でおられるのか、お伺いします。","respondent":"森田生活安全担当課長","answer":"警察に１１０番等があれば、これは独自に警察で対応しているということで認識はしておりますが、そういった事案というものは今のところございません。","id":"exchange-141"},{"speaker":"塚本委員","kind":"質問","question":"１１０番された方からの情報として得られれば、この時間帯にちょっと行ってみて、現場を押さえてと。あらかじめ、現場を押さえられれば注意しようといったこともやっていただければいいのではないかと思いますが、この辺についてはいかがか尋ねました。","respondent":"森田生活安全担当課長","answer":"指定地区以外というところは、いろいろなご相談に乗りまして、私どもでも対応しています。警察については警察のほうで、独自にいろいろな１１０番が入っておりますし、相談事も入っておりますので、対応はしていると聞いております。","id":"exchange-142"},{"speaker":"塚本委員","kind":"質問・要望","question":"新しい観覧、いわゆるバーチャル空間を活用した展示というのですか、こういったことを少し考えてみたらいかがかと思います。最近、仮想空間がすごく話題になりましたけれども、いわゆる現実にある渋谷のまちみたいなものを仮想空間に再現するというのか尋ねました。","respondent":"篠田文化観光課長","answer":"１つはシステム的にどんなものをつくっていくかということが当然問題になりますけれども、問題が出てくる、課題が出てくるかと思います。","id":"exchange-143"},{"speaker":"塚本委員","kind":"質問・要望","question":"今はもうデジタルで作曲して、それを自分で配信して、どんどんスマホの中で広がっていくみたいな。今後、視野に入れてほしいと求めましたけれども、いかがか尋ねました。","respondent":"篠田文化観光課長","answer":"現状ではなかなかそこまで手が伸ばせていないところではあるのですけれども、そういった発表の場の提供というのも、当然区として今後考えていく必要があるのではないかと捉えているところではあります。","id":"exchange-144"},{"speaker":"塚本委員","kind":"質問","question":"よろしくお願いしたいと思います。そういったいろいろな運営面をサポートしてくれる人に対する経費というのも、この補助の対象として考え得るのかどうかというのを説明を求めました。","respondent":"川島地域活動課長","answer":"補助対象にしようと考えていますし、Ｚｏｏｍ会議の運営の支援をしていただいたり教えていただく、３月中に活用できるようにつくっていきたいと考えています。","id":"exchange-145"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"４年間ぐらいと考えると、約４億円近くかかっていくのかと考えていますが、まず教えていただきたいです。そこから入ります。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"委員がご指摘のとおり、来年度は１０月オープンを目途にしておりまして、来年度は運営面に関しては３,０００万円強の費用を見ております。委員がおっしゃるように、五、六千万円ぐらいの運営費になるかと認識しております。","id":"exchange-146"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"３６５日で考えるならば、２５０日ぐらいは、そういうことを無料でやっていってもいいのだろう。そういうことをやっていくことが、こういう活用の仕方をしていただきたいと思うのだけれども、その辺の考え方を説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"実際に、イベント等で借りられるのかというようなお問合せも頂いているところです。その辺りはこれからの検討課題ではありますが、今、積極的にいろいろ検討を進めているところです。","id":"exchange-147"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"あっという間に１０年ぐらいは経ってくるのだろうと考えていますが、どういうふうにしていくのだという、ぜひやっていただきたい。地域の方々に伺うと、よりよい八潮のまちづくりを進めていっていただきたいと考えていますが、その辺の考え方を教えていただきたい。","respondent":"川島地域活動課長","answer":"地元の方にとっては非常に関心が高い部分だと思いますので、その辺を考慮しまして、メンバーの構成をやっていきたいと考えています。それから、冒頭お話しいただきましたような過去の経緯なども大事にしながら、計画を進めていきたいと考えています。","id":"exchange-148"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"過去の経緯もぜひ大切にしていただきたいし、それがどういう形を取るかということであります。どうやって評価していこうと今は考えていらっしゃるのか、どういうふうに取り組もうと考えていらっしゃるのか、教えてほしいと求めました。","respondent":"崎村人材育成担当課長","answer":"自分をどうスキルアップしていけばいいかというところを考えさせる研修なども、研修として実施していきたいと考えているところです。次代の課長級管理職を目指す職員をどう育てていくかという部分の重要性を認識させるための研修というのも実施していきまして、人材育成。","id":"exchange-149"},{"speaker":"石田（秀）委員","kind":"意見","question":"短期で管理職試験を受けているような人、こういう人はもちろん、行政間の交流もあるけれども、民間、外部に、１年ぐらい行ってもらう。こういう方々にそういう体験をしてもらうことも必要だと思いますので、ぜひそれはお願いだけしておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-150"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/201716?Template=document&Id=1148#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":117121,"voices":344}},{"id":"r04-20220307-10","meetingId":"r04-cm03","date":"2022年3月7日","dateIso":"2022-03-07","committee":"議会運営委員会","time":"午前 ９時００分～午前 ９時０５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/982514?Template=document&Id=5452#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":2029,"voices":13}},{"id":"r04-20220308-3","meetingId":"r04-c-budget","date":"2022年3月8日","dateIso":"2022-03-08","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時４０分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を160件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"松澤委員","kind":"提案","question":"１点だけ、またちょっとしつこいようですけれど、その動画の取組というのをご提案させていただきたいと考えています。これから３年間の予算というものがありますけども、品川区が本気になるべきと私は考えていますので、ご見解を説明を求めました。","respondent":"山下子ども家庭支援センター長","answer":"アニメーションでしたり、今後庁内で検討してまいります支援策の検討の中で、動画の活用というところも含めて考えてまいりたいと考えています。区としましても、そちらの国の動画等も含めて、有効に活用してまいりたいと考えております。","id":"exchange-001"},{"speaker":"松澤委員","kind":"質問","question":"２０２５年、本人ミーティングの要は進化版というのですか、（仮称）認知症ミーティングセンターの開設とありました。７月には事業開始とありますけども、これ、どういった経緯で開設まで進んだのか、また、準備のご苦労等もありますか、そこら辺を説明を求めました。","respondent":"宮尾高齢者福祉課長","answer":"認知症ミーティングセンターに関するお尋ねです。できれば２家族一緒に参加をしていただいて、今回、事業化を考えているものです。","id":"exchange-002"},{"speaker":"松澤委員","kind":"質問・要望","question":"準備も大分進んでいると思っていますが、どのようなイメージでセンターというものを計画しているのか、教えていただきたいです。どこか場所を１か所決めてそこでやっていくのか、分散していろいろな形で開催するのか、そこら辺を説明を求めました。","respondent":"宮尾高齢者福祉課長","answer":"３か所分の開設支援経費を計上させていただいておりまして、実際に、こちらのミーティングセンターをやっていただきたいということで考えております。","id":"exchange-003"},{"speaker":"松澤委員","kind":"質問","question":"そういった機会をつくるとか、その後の活かしというのですか、そういうのがとても大切だと私は思っております。関わり合いが長いその先輩たちにとっては、失礼で、分かっているというお話になると思いますけれども、そこら辺の考え方を説明を求めました。","respondent":"宮尾高齢者福祉課長","answer":"それから、つなぎですが、委員ご指摘のように１回だけで終わりというものでは決してないというふうに今、考えております。いろいろな場へのつなぎ、こういったものをしっかりと意識して、この事業を推進していきたいというふうに考えております。","id":"exchange-004"},{"speaker":"松澤委員","kind":"意見","question":"ぜひ、この取組が区民に周知されまして、また、先ほど言いました、各地域で盛り上がる、要は、品川区以外の区で盛り上がりを見せて、また、各地域、品川区全体で定期的に開催できることを願いまして終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"２２３ページ、日常生活用具給付事業、自家発電装置について、２２９ページ、障害児支援事業に関連をいたしまして、馬とのふれあいについて伺います。２７３ページ、２６９ページ、伺ってまいります。","respondent":"櫻木生活福祉課長","answer":"こちらの事業は、想定としましては、ＮＰＯや事業者が生活困窮者に向けたフードパントリーを実施する際に、区が費用について助成する事業となります。それと、ピックアップ型の実績ですが、令和４年１月までで大体延べ２０２回という形です。","id":"exchange-006"},{"speaker":"新妻委員","kind":"意見","question":"この２０２回の利用者も昨年よりもかなり増えていると認識をいたします。それと、この福祉関連の事業者において、利用者の方がどのような仕組みで利用ができるのか、そこら辺のご説明をお願いいたしますとの意見を述べました。","respondent":"櫻木生活福祉課長","answer":"いつからですが、事業者のほうでご検討されている状況ではあるのですが、６月頃を目標としたいというお話を伺っているところです。大体月に２回程度、区民の方が直接事業者のほうに申し込んでお受け取りいただくような、そのような仕組みと考えております。","id":"exchange-007"},{"speaker":"新妻委員","kind":"質問","question":"最初のこのきっかけというのは、暮らし・しごと応援センターになるのでしょうか。その周知の仕方についても、もし今検討されているようであればお考えをお知らせください。","respondent":"櫻木生活福祉課長","answer":"周知につきましては、チラシ等を作成して、お困りの方にどのような形で目につくような、届くような形で周知できるかということは、これから考えてまいりたいと考えています。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"八潮地域で人工呼吸器を使われている方の状況はどうなのかということを確認させていただきましたが、大きな災害が起こらなくても、本当に。その方々がどのようにその自家発電装置を既にお持ちなのか、その状況は把握をされているのか尋ねました。","respondent":"松山障害者福祉課長","answer":"少し前になりますけど、昨年１０月１日時点で、区内で人工呼吸器を使用されている方は１７人いらっしゃいます。全く準備をされていない方もいらっしゃいますので、今後、周知に努めてまいりたいと考えております。","id":"exchange-009"},{"speaker":"新妻委員","kind":"意見","question":"区がしっかり、１７名いらっしゃるということを把握されているということで安心をいたしました。１７人それぞれ、団体を通じてもぜひ周知もお願いしたいところなのですが、どのような流れでこれが進んでいくのかお知らせくださいとの意見を述べました。","respondent":"松山障害者福祉課長","answer":"この事業につきましては、災害時個別計画を現在作成しているところですが、この事業とセットで進めていきたいと考えております。保健師や相談員、直接ご相談をして作成する形でのご案内ということで、漏れなく周知してまいりたいと考えております。","id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"１７名漏れなく全員ということ、全ての方がご自宅に設置されるよう、取組を要望します。今後、教育部門でも確認をさせていただこうと考えていますが、福祉部門におけるこの馬との触れ合い事業についての見解をお伺いいたします。","respondent":"松山障害者福祉課長","answer":"障害のある方と馬とのふれあい事業についての見解です。馬とのふれあい事業については、知的障害者のみならず重症心身障害児もかなり触れ合いがあり、コロナ禍の中で効果的なものだと認識をしております。","id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"そういう事業展開を要望させてほしいと求めましたので、また引き続きつる委員とともに、取り上げてまいりたいと思います。キャッシュレス化が進んでおりまして、キャッシュレス化の現状と、また新規で行われるところがどこなのか、またスケジュールをお伺いします。","respondent":"初貝保育教育運営担当課長","answer":"現状ですと、令和３年の１月より、第三庁舎のオアシスルームでキャッシュレス化を開始しております。今後の予定ですけれども、ほか８か所を追加して行う予定でございまして、計９か所を実施する予定です。","id":"exchange-012"},{"speaker":"新妻委員","kind":"質問","question":"計９か所となるということです。オアシスルームはたしか１２か所でしたでしょうか、全部が展開できないというのは何か課題があるのでしょうか、お伺いします。","respondent":"初貝保育教育運営担当課長","answer":"来年度は９か所で実施を予定するというようなところですけれども、その利用状況等々、実績を踏まえた上で、順次キャッシュレス化の施設を拡大する予定ということで、まずは来年追加でというようなところで考えております。","id":"exchange-013"},{"speaker":"新妻委員","kind":"質問","question":"早急に全てのところでキャッシュレス化ができますよう、よろしくお願いいたします。八潮、勝島地域におけるこのオアシスルームの設置について、状況をお伺いいたします。","respondent":"初貝保育教育運営担当課長","answer":"この間、区有の施設を中心に検討を進めているところです。様々施設の問題であったり調整がなかなか難しかった部分もありますけれども、引き続き適地を検討しまして、実現に向けて検討していきたいと思います。","id":"exchange-014"},{"speaker":"横山委員","kind":"質問・要望","question":"将来的に、就業支援の部門とが連携しながら、メンズ・クライシスの予防を進めていただきたいというふうに要望いたします。商業・ものづくり課の部分については産業経済費のところでお伺いいたしますが、若者等社会参加の観点からの考え方を説明を求めました。","respondent":"廣田子ども育成課長","answer":"キャリア支援に向けたプログラムに取り組んでいるところですけれども、今後起業等の支援についても課題として研究してまいりたいと思います。今後につきましては、起業と就業の支援の部門についても連携していくように検討していこうと思います。","id":"exchange-015"},{"speaker":"横山委員","kind":"質問・要望","question":"２点目に、児童相談所移管推進事業についてお伺いいたします。同じく、今後区でも開設に当たりまして準備を進めていただきたいと考えていますが、区のお考えを説明を求めました。","respondent":"佐藤企画調整課長、加島児童相談所移管担当課長","answer":"２点目、ＥＢＰＭ実施のポイントといたしまして、既に様々な計画策定の中で取り組んでおります。いずれにしましても、施策の効果検証は区として重要なことだと考えておりますので、引き続き情報収集に取り組んでまいります。現段階では市区町村での実施は想定されていないものと認識しておりますが、今後考えてまいりたいと受け止めております。","id":"exchange-016"},{"speaker":"横山委員","kind":"質問・要望","question":"３点目に、ひとり親家庭支援事業についてお伺いをいたします。入居後のサポートなど、様々なアクターが得意分野を活かして連携体制を整備してほしいと求めましたが、区のお考えを説明を求めました。","respondent":"伊東子育て応援課長","answer":"そういう中で、それに関する部分に関してはしっかり聞いて、それなりの支援に結びつけるというような形でお話を聞いているところです。母子生活支援施設ということであれば、それ以外の部分に関しては、それぞれの課と連携して対応していきたいというふうに考えております。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"２２９ページ、２３１ページの避難行動要支援者個別計画作成について、障害者および高齢者の個別計画を伺いたいと思います。進捗状況と対象者を伺いたいと思いますが、障害者そして高齢者はどういう方でそれぞれ何人か、伺いたいと思います。","respondent":"松山障害者福祉課長、宮尾高齢者福祉課長","answer":"障害者の方の対象としては、今年度は通所施設のご利用者の方を対象に実施いたしました。１１月に相談支援向けの防災学校を実施して、約１か月、１２月までの数字ですが、１２人の方に作成したところです。 今年度は、同じく原案の段階で５,０００件の作成を予定しています。障害者のほうと同様に、高齢者につきましても、ケアマネジャーを対象に、防災に関する研修の実施を今年度はしたところです。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"進めていただきたいと思うのですけれども、全ての障害を対象にすることを目指しているのかどうか、その点を伺いたいと思います。でも早くという思いで質問していますが、この作成を加速させるにはどんなことが課題と考えていらっしゃるのか、伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"手帳の所持者でサービスを使われていない方も将来的には対象というふうに考えておりますけれども、まずは支援が日常的に必要な方から作成しています。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"この難しさや個別性について丁寧に聞き取って作成してほしいと求めましたし、また、地域の理解を広げていくことが併せて必要だと思います。当事者への説明と併せて、地域住民への理解を広げていく取組が必要だと思いますが、いかがか尋ねました。","respondent":"松山障害者福祉課長","answer":"地域住民の方とともに避難したり、避難生活を送るということは想定されますので、必ず私どもで地域の理解というのを促進していく必要があります。日頃からの障害者理解の促進とともに、防災課と連携しながら普及啓発をしてまいります。","id":"exchange-020"},{"speaker":"中塚委員","kind":"提案","question":"様々の支援について理解を広げていくために、先ほどパンフレットのことも提案させていただきましたが、この支援者の確保につながってくると。それがいずれ、個別計画の作成を加速させていくと思いますが、いかがか尋ねました。","respondent":"松山障害者福祉課長","answer":"その中でやはり、当事者やご家族が改めて災害時の避難について、世帯で考える、家族全体で考えるきっかけとなっております。それが一番の普及啓発だと考えております。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"避難先となる福祉避難所についても伺いたいと思いますが、特養ホームなど介護施設になるわけですけども、運営は区の職員が行うという説明でしたが。ぜひ連携して訓練も進めてほしいと求めましたが、連携についていかがか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"福祉避難所におけます連携ですけれども、基本、一義的には福祉避難所というのは区が開設をするものというふうに認識をしております。しっかりと施設側とも連携協力をしながら、訓練の実施も含めて、区の職員と施設側とで連携を図ってまいりたいというふうに考えております。","id":"exchange-022"},{"speaker":"くにば委員","kind":"質問・要望","question":"私は、昨年１１月の一般質問で、この高齢者の熱中症予防のためのエアコン設置助成を求めました。もう１点お伺いいたします。","respondent":"宮尾高齢者福祉課長","answer":"それから、こういうことをまずはしっかりと伝えていくことが重要であるということで、昨年の１１月の答弁と相なったです。まずは、あるいは扇風機等をお貸しする、こういったものを併せて推進をしていきたいというふうに考えているところです。","id":"exchange-023"},{"speaker":"くにば委員","kind":"意見","question":"要するに３３％の方は設置していないとのデータなのです。それとも、もう６７％が相当数ということだからまあいいでしょうという感じなのか、ちょっとそこの数字に関しての認識についてご答弁くださいとの意見を述べました。","respondent":"宮尾高齢者福祉課長","answer":"ちょっと説明が足りずに、というところで、ちょっとどうかなというところはあるかなと思います。お一人暮らしのご高齢者の方を訪問する際には、そういった説明も含めて、対処していくという必要があるというふうに認識をしています。","id":"exchange-024"},{"speaker":"くにば委員","kind":"質問","question":"私は一般質問の際も申し上げましたけれども、経済的な事情で設置ができない方も相当数いらっしゃいますというふうに申し上げました。今までやり取りしていますけれども、私が申し上げていることがむしろ逆にかみ合っていないのであればそれもご指摘ほしいと求めました。","respondent":"宮尾高齢者福祉課長","answer":"決して、経済的に購入できない方がゼロであるという認識は毛頭ございません。そういったことも含めてしっかりとアセスメントをしていく必要があるということは、それはしっかりと認識としては持ち合わせております。","id":"exchange-025"},{"speaker":"くにば委員","kind":"質問・要望","question":"ちょっとこれに関しましては、次の質問がありますので要望としてお伝えさせていただき、この質問を終わらせてほしいと求めました。区有施設以外で、これまでどのような施設を検討していたのか、その２点をお伺いします。","respondent":"若生保育支援課長","answer":"区有施設に関しても様々検討を進めているところで、一方で民間で事業を行っているところのスペースの検討ですけれども、例えば事業主ですとか。様々検討を進めていく中で、民間の施設等も含めまして広く、今後も検討してまいりたいと考えています。","id":"exchange-026"},{"speaker":"くにば委員","kind":"質問・要望","question":"今質疑で私が求めたのが、今私が申し上げた２か所等については、区有施設以外でどのような施設を具体的に検討してきた経緯があるのかお伺いします。何か区有施設でなければいけないみたいな縛りがあるのか、要望があるのか、その点お伺いします。","respondent":"若生保育支援課長","answer":"大井競馬場の駅前に関する事業用地、こういったところの検討をしたかどうかというところに関しましては、区として具体的な検討は行ってございません。","id":"exchange-027"},{"speaker":"くにば委員","kind":"質問・要望","question":"２歳児を育てておりまして、行くのに子どもの支度を含めて１時間ぐらいかかってしまう、尻込んでしまうというご意見を多々いただいております。ですので、そこに関して重ね重ね、ぜひご検討のほうお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"吉田委員","kind":"質問","question":"４件というのがちょっと意味が分からなくて、４つの施設で１人ずつということなのでしょうか。１つの施設で複数人数の有資格者配置に使えるのか尋ねました。","respondent":"松山障害者福祉課長","answer":"有資格者についてですが、１つのグループホームにつきまして、有資格者は２名を上限としております。選定基準につきましては、区の要綱で助成要件を定めております。","id":"exchange-029"},{"speaker":"吉田委員","kind":"質問・要望","question":"これが十分なのかちょっと判断がつきませんので、その辺について見解を伺います。併せてぜひ治療費補助も検討してほしいのですが、いかがか尋ねました。","respondent":"松山障害者福祉課長","answer":"は、講演会などの場合については二、三人の通訳者が１５分から２０分ごとに交代しながら行っているところです。区としましては、手話通訳者の頸肩腕等のご健康についても、今後も配慮してまいります。","id":"exchange-030"},{"speaker":"吉田委員","kind":"質問・要望","question":"これは要望とします。障害者差別解消という視点から、手話通訳者配置のための補助制度を検討していただきたいと思うのですが、いかがか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"法律で、合理的配慮の提供が義務化されているものですので、サービスの提供の実施者側で提供するということが基本になってくるものと考えております。","id":"exchange-031"},{"speaker":"吉田委員","kind":"質問・要望","question":"伺いたいのは、ここに区の障害者福祉課職員が、重症心身障害者通所事業担当として１人配置されています。障害児者総合支援施設担当として１人配置していますが、秋に、それでピッコロのほうに配置されている職員の方の位置づけについて伺いたいと思います。","respondent":"松山障害者福祉課長、築山障害者施策推進担当課長","answer":"こちらのピッコロは区の直営の事業です。施設ではないため、指定管理者ではなく、区の組織にその職員も、重症心身障害者通所事業担当として、組織の中に位置づけているというものです。 区と指定管理者とが連携をしながら建物の運営を実施しているという側面もありますので、１０月以降も区職員、１年は配置をする予定です。","id":"exchange-032"},{"speaker":"吉田委員","kind":"質問・要望","question":"例えばそこに区の職員がいるということで、一般的に偽装委託とか偽装請負とか、そういう解釈がされる危険性はないのでしょうかということが１点。この７年ぐらい、全然異動されていないのですけれど、その職員としてのそういう考え方の違いも説明を求めました。","respondent":"松山障害者福祉課長","answer":"ピッコロに関しての委託については、こちらのほうも東京都の指定をきちんと受けておりますので、何か請負とかそういったことでは一切ございません。それから、職員の異動の案件につきましては、人事案件ですので個別案件につきましてはちょっとお答えは控えします。","id":"exchange-033"},{"speaker":"吉田委員","kind":"質問・要望","question":"施設を利用されている方たちにとっても、ちょっと戸惑いの元というか、そういうようなことを伺っております。ぜひ活用を進めていただきたいという視点から、区がその活用状況をどのように考えているのか伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"令和３年に開設して、７月から来館者の受入れを開始しているという状況の中、利用者数が延べ１８２人となっております。ただ一方で、送迎を含めた預かりの通所サービスを実施してほしいというようなお声もありまして、現在ベルの方向性についても事業者と協議しています。","id":"exchange-034"},{"speaker":"吉田委員","kind":"質問・要望","question":"第２回定例会の一般質問で、子どもの意見表明とそれに関連してアドボケイトの仕組みを求めたところ、確か。区としてそれをぜひ活用して、子どもの意見表明とアドボケイトの仕組みを求めますが、現段階での検討状況などがあったら説明を求めました。","respondent":"加島児童相談所移管担当課長","answer":"今ご質問の点につきましては……。","id":"exchange-035"},{"speaker":"木村委員","kind":"確認","question":"私からは、２１５ページの上から４行目、高齢者安否確認事業の中の、その３行下にあります、長寿お祝い事業からの質問をいたします。区内在住の高齢者の皆様をご覧になり、昔と今の高齢者とでは変化を感じること、違いを感じることというものは何かあるか尋ねました。","respondent":"寺嶋福祉計画課長、菅野高齢者地域支援課長","answer":"こういった事業内容でございまして、恐らく式典等につきましては、シルバー成年式等のことをおっしゃっているのではないかと思います。令和３年につきましては、９月に実施予定だったのですが、オンラインによる記念式典と記念講演のみを実施させていただきました。","id":"exchange-036"},{"speaker":"木村委員","kind":"意見","question":"この事業を実行すれば、元気な人生を送ることができるだろうなど、お考えになったことはありますか。ほかに何か、高齢で元気に過ごすための極意というもの、何かそういうお考えがあれば説明を求めました。","respondent":"菅野高齢者地域支援課長","answer":"社会参加、この３つは相互に影響し合っておりまして、特に社会参加の機会が低下すると衰えの最初の入り口になりやすいと言われております。介護予防や閉じ籠もり防止にもなることから、区において、こうした活動を積極的に支援していきたいと考えているところです。","id":"exchange-037"},{"speaker":"木村委員","kind":"質問","question":"ずばり、行政としてのサポートはどのようなことができるとお考えでしょうか。そして、これからのこの計画の中で、これは実行に移したいということはあるのか尋ねました。","respondent":"菅野高齢者地域支援課長","answer":"私どもの課では、実施していますが、活躍の場のきっかけづくりみたいなものを区としてはつくっていくことがサポートになるのかなと考えています。","id":"exchange-038"},{"speaker":"木村委員","kind":"質問","question":"次に、２３１ページの中ほどの下にありますけれども、高齢者災害対策支援事業費、５,９１９万円余からの質問であります。災害に対し、品川区がほかの自治体と違った独自の対策等をお考えになっていることがあれば、許せる範囲で説明を求めました。","respondent":"宮尾高齢者福祉課長","answer":"こういう方に対して、きめ細かくどうやって支援をお届けするか、こういう視点を持ってこれからも進めてまいりたいと考えています。災害の避難についても同様の考え方で進めさせていただいているところです。","id":"exchange-039"},{"speaker":"松本委員","kind":"質問","question":"私からは２４９ページ、子どもすこやか医療費助成事業および２５３ページ、２６１ページの保育所等の巡回支援事業について伺います。手続について伺います。","respondent":"伊東子育て応援課長","answer":"高校生の医療費助成ということで、入院費に限定したところですけども、区は他区に先駆けて実施しています。今、その領収書を持って区のほうの窓口に来ていただいて、還付というか支給の申請をしていただくという形でのことをやっているところです。","id":"exchange-040"},{"speaker":"松本委員","kind":"質問・要望","question":"平日の１７時までということなので、これは実際に、働かれている保護者の方たちからすると、相当負担だと伺っています。この高校生等入院医療費助成、郵送申請や電子申請を導入すべきと考えますが、区の見解を伺います。","respondent":"伊東子育て応援課長","answer":"今現在は、領収書の原本を提出していただくという形になってありますので、そこが一つのネックであるというふうに考えてあります。","id":"exchange-041"},{"speaker":"松本委員","kind":"質問・要望","question":"こちらも電子申請、検討してほしいと求めましたがいかがでしょうか。こちらも、電子申請が難しくてもせめて郵送申請を検討してほしいと求めましたがいかがか尋ねました。","respondent":"伊東子育て応援課長","answer":"領収書もそうですけども、その他保険証ですとか様々あるという部分で、こういう形で対応を取らせていただいているところです。今後、電子申請ですとか、郵送申請の可能性については探って行きたいと考えています。","id":"exchange-042"},{"speaker":"松本委員","kind":"質問・要望","question":"次に、保育所等の巡回支援事業について伺います。これプレスリリースで拝見すると、あまり時間もないですから一応確認で、法律上の指導検査とこの巡回支援の違いについてお伺いできればと思います。","respondent":"立木保育課長","answer":"巡回支援事業ですけれども、区が実施します指導検査のような子ども・子育て支援法や児童福祉法に規定された権限に基づいて行うものではございません。主に助言等を行うことを想定しております。","id":"exchange-043"},{"speaker":"松本委員","kind":"確認","question":"種類がたくさんありまして、なかなか複雑なところもあって、さらに認可と認可外というところの違いもあると思っています。平成２４年の辺りから、ここも確認なのですが、そこのところの部分を解説していただけますか尋ねました。","respondent":"立木保育課長","answer":"子ども・子育て支援法が施行になりまして、児童福祉法と子ども・子育て支援法と二本立ての形になっております。まだ、そこの部分はちょっと違いあるのですが、基本的には区のほうにも指導検査権限のほうが下りてくるという形になってあります。","id":"exchange-044"},{"speaker":"松本委員","kind":"質問・要望","question":"さらに、この児童相談所が設置されると、この中に認可外のところの指導監督というのも出てくると思っています。早めに準備が必要かと思いますが、今、人員体制等の準備状況をお伺いできればと思います。","respondent":"立木保育課長","answer":"令和６年度の児童相談所開設に向けまして、指導検査の体制のほうも、順次整えている段階でございまして、体制の強化等も年ごとに増やしていく形で、計画をしています。","id":"exchange-045"},{"speaker":"松本委員","kind":"質問・要望","question":"これは初日か２日目でも扱いましたけれども、事故を防げるように、体制整備をお願いできればと思います。以上、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"小芝委員","kind":"質問","question":"私からは２６３ページ、また２６１ページ、保育所等の巡回支援事業についてお伺いをいたします。この事業が新たに拡充をされました経緯を説明を求めました。","respondent":"若生保育支援課長","answer":"私立保育園での保育園に対する巡回支援というところで、臨床心理士の巡回相談事業で、認可保育所のみを対象として実施していたところです。","id":"exchange-047"},{"speaker":"小芝委員","kind":"質問","question":"場合によっては、母親が子どもの特性に気づかないこともあるかもしれません。保育所は、この特別支援保育巡回相談で臨床心理士などとどのように連携を取っていくのか、入り口のところをぜひちょっと教えてもらいたいと思います。","respondent":"若生保育支援課長","answer":"特別支援を要するお子さん、保育士の対応の仕方については、かなり苦慮しているということは聞いてあります。保護者への対応についても、連携しながら事業を進められているところです。","id":"exchange-048"},{"speaker":"小芝委員","kind":"質問・要望","question":"こういったことはもちろん防ぐように、日々の点検を怠ることのないよう、強く求めて次に行きたいと思います。これまでも、当然に事故の防止に取り組んでこられてきたと思いますが、この巡回支援事業を行うことで得られる効果について説明を求めました。","respondent":"立木保育課長","answer":"巡回支援事業ですけれども、法に規定された指導検査とは別に、巡回支援指導をプラスして実施することによりまして、各保育施設における重大事故の防止や、保育の質の確保・向上を図るという、そういったねらいの下に行うものです。","id":"exchange-049"},{"speaker":"小芝委員","kind":"質問・要望","question":"この巡回支援事業というのは、年１回の検査、指導検査を待たず助言を行うと書かれていますけども、なるべくこういったことも頻度を多くして進めてほしいと求めましたが、その辺りの考えを教えてほしいと求めました。","respondent":"立木保育課長","answer":"当面、年２回行う予定ですけれども、様子を見ながら拡大の方向も探っていきたいと考えています。","id":"exchange-050"},{"speaker":"つる委員","kind":"質問・要望","question":"２６５ページ、２６７ページ、ベビーシッター利用支援事業について伺っていきたいと思います。他の委員とのやり取りを確認すると、親の関わりを持っていただきたい、これが区の思いなのです。","respondent":"廣田子ども育成課長","answer":"３番目がスキームの問題ということを考えております。他区の調査については、父母会、父母会等とどんな役割分担をしているのかであるとかというところを調査して分析していこうと考えているところです。","id":"exchange-051"},{"speaker":"つる委員","kind":"質問・要望","question":"給食費の１食当たりのものですとか、また栄養価等についてもいろいろと確認はさせていただいて、ここをしっかりとどう担保していくのか。ですから、これはいわゆる給食を設定した時間の１５分前ぐらいに到着をするというところでは、これをしっかりと模索をしていただきたいなと。","respondent":"山下子ども家庭支援センター長","answer":"今、委員からご案内ございましたとおり、来年に向けてこども家庭庁ということで国のほうで新庁が設置される予定です。虐待また今後進めていくヤングケアラー支援も含めまして、また庁内以外に関係機関との連携というところを強めてまいりたいと考えています。","id":"exchange-052"},{"speaker":"つる委員","kind":"質問・要望","question":"公明党からその確認をさせていただいて、区の見解を求めたところでは、来年度２０２２年度でシステム改修費等が示されている。これを２０２３年度から実施する場合には、どのようなスケジュール感になるかを説明を求めました。","respondent":"伊東子育て応援課長","answer":"高校生の医療費無償化ということで、都のほうでは令和４年度、７億円ということで準備経費として計上しています。今年度中に準備というのは、やれないことはないと思いますが、ぎりぎりなのかなというふうに思っているところです。","id":"exchange-053"},{"speaker":"つる委員","kind":"質問・要望","question":"これは昨年の一般質問ですとか決算特別委員会の段階で求めさせていただいて、これは他の自治体の事例も含めて確認をさせていただいて。これについてご答弁ほしいと求めました。","respondent":"若生保育支援課長","answer":"私ども保育支援課として、他区の事例等も含めまして、どういった支援ができるか様々検討を進めてきたところです。今後、品川区の保育全体の在り方、こういったことも含めて、きちんと検討した上で、また再度検討を進めていきたいと考えています。","id":"exchange-054"},{"speaker":"つる委員","kind":"質問・要望","question":"アプリも含めて、紙媒体も含めて、充実をさせてほしいと求めました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"渡部委員","kind":"質問・要望","question":"２６１ページとか２５３ページの辺なのでしょうか、保育のことでちょっとお伺いをしたいなと思います。満点ではなくて３０点代半ばぐらいで入られている方もいるわけでして、ですから、概略を教えてほしいと求めました。","respondent":"立木保育課長","answer":"２次選考では、内定者がさらに追加で２７６名で、トータルで不承諾が９７１名ということになりました。委員おっしゃるとおり、入園に関しましては、指数の低い方も去年と比べると少し入りやすくなったというのが見られる状況です。","id":"exchange-056"},{"speaker":"渡部委員","kind":"質問・要望","question":"ですから、この日だけ預かってほしいとかという、あった場合の手当というようなことも少し考えていただけないのかな。例えばそういう需要がどれぐらいあるのか、研究からでもスタートしていただきたいなとちょっと思っているのですけれど、どうか尋ねました。","respondent":"立木保育課長","answer":"ニーズがいろいろ変化している中で、保育の預かり方という部分に関しましては様々な事例を研究させていただきまして、今後そういったことができるかどうかというのもしっかり検討させていただきたいと考えております。","id":"exchange-057"},{"speaker":"渡部委員","kind":"質問・要望","question":"ですから、そういうところまで見据えて、どういうことで活かせるかどうか、考えていっていただきたいなと思います。そのやり取りも伺っていたし、時代は確かに変わっていますし、やはりどうやったらできるのだろうなというふうなのは自分でも考えてみたのです。","respondent":"廣田子ども育成課長","answer":"委員にいろいろお話ししていただいたとおり、課題についてはもろもろそのようにたくさんあるというところは、今まで申し上げてきたとおりです。大人数の子どもを一堂に集めますので、研究をしてみようと考えていますので、調査をさせていただこうと思っているところです。","id":"exchange-058"},{"speaker":"渡部委員","kind":"質問・要望","question":"前回の一般質問でもお伺いしましたプレイパークであるとか、去年の第４回定例会の一般質問でしたか、進捗状況をお伺いしたいなと思うのと。何とか進めてほしいなと、進めていただいているのだろうなと思いながら、お聞かせほしいと求めました。","respondent":"廣田子ども育成課長","answer":"荏原、旗の台公園で令和２年度から外遊び推進事業を実施しておりますけれども、ニーズとしてはおおむね好調な事業となっております。令和３年度１月から乳幼児親子や小中高生を対象に、令和４年度の検討に向けて、今後の在り方について検討を進め始めているところです。","id":"exchange-059"},{"speaker":"渡部委員","kind":"質問・要望","question":"ここに行けばどういう講座があると、いろいろな児童センターに行くわけですから、いろいろ考えられることってあるのです。それをどう支援していくかというのは、そういうのを念頭にこれからも進めていただきたいと思うのですが、何か一言あればお願いします。","respondent":"廣田子ども育成課長","answer":"それを参考に、実際使おうとしている子どもたちの意見を参考にしながら、よりよい施設に向けて検討したいと考えています。","id":"exchange-060"},{"speaker":"安藤委員","kind":"質問","question":"２５２ページ、児童保育費、待機児解消、２３９ページ、高齢者住宅について伺います。昨年、一昨年の応募人数と入居できた人数についても伺います。","respondent":"菅野高齢者地域支援課長","answer":"令和３年度の入居状況ですが、現在、まだ進行形で入居案内の方もいらっしゃるのですけれども、１７名の方にご案内をしています。令和２年度につきましては、１９名の方が入居されております。","id":"exchange-061"},{"speaker":"安藤委員","kind":"質問","question":"品川区は、高齢者住宅の潜在ニーズを考えますと、申請者数が少ないとは思いませんでしょうか。入居者数は十分だと思っているのか、それぞれ伺いたいと思います。","respondent":"菅野高齢者地域支援課長","answer":"例えば、賃貸住宅への住み替えを支援するものとして、住まいの確保と見守りと生活支援を一体的に提供する、あんしん居住サポートを実施してきました。区の居住支援協議会において、不動産関係団体等と連携し、住宅情報の提供等の支援を実施しております。","id":"exchange-062"},{"speaker":"安藤委員","kind":"質問","question":"そのうち賃貸住宅に居住している方の割合ですとか、住宅に困窮される方など、居住の実態というのはどれぐらいつかんでいるでしょうか。伺いたいと思います。","respondent":"菅野高齢者地域支援課長","answer":"このときの７５歳以上の人口が３万９,６６７名ですので、約１８％の方が、７５歳以上の一人暮らしの高齢者ということです。それからしばらく７５歳人口が増加しているということもありますので、単純にもう少し伸びているということで推測できます。","id":"exchange-063"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはりそのもの、高齢者住宅の増設を求めたいと思いますが、いかがでしょうか。先ほど質疑がありましたけど、本日は２次選考の発表日ということで、当然選考は既に終わっていますので、２次選考の結果を伺います。","respondent":"菅野高齢者地域支援課長、立木保育課長","answer":"こちら、令和４年度の予算規模で約１億９,７００万円の維持管理経費が必要となっております。高齢者の住宅施策を進めていく中で、国や東京都の施策とのバランスも考えていく必要があり… これは１次選考からの継続も含みます。４歳児２９名、５歳児１５名、合計で９７１名となっています。","id":"exchange-064"},{"speaker":"安藤委員","kind":"質問","question":"２歳のお子さんを育てておりまして、今の自分の勤務時間ではまず保育園に入れないだろうと、初めから諦めて４月応募していませんでした。待機児童は基本的に解消という認識は、現実と乖離していると思いませんでしょうか、伺いたいと思います。","respondent":"若生保育支援課長","answer":"先ほどご紹介いただきました、不承諾数から待機児童が除かれるというところに関しましては、国の基準にのっとってやっているところです。ただ、総合的な待機児童対策として、認可外保育施設も認証保育所等も含めて対応しています。","id":"exchange-065"},{"speaker":"湯澤委員","kind":"質問","question":"以前一般質問でもお尋ねしましたが、平成２８年、現在では神戸市や渋谷区など７つの自治体が取り組んでおります。１年半前にも質問させていただいた際には、改めて障害者の短期間雇用に対する本区の考えと取組、また検討状況を教えてほしいと求めました。","respondent":"松山障害者福祉課長","answer":"２月１８日に、地域自立支援協議会で就労支援部会を行いました。東京大学先端科学技術研究センターの近藤先生にご講演いただきまして、就労支援事業所と情報共有を図り、今後について検討しています。","id":"exchange-066"},{"speaker":"湯澤委員","kind":"意見","question":"短時間、軽作業をしてほしいと思っている方もいらっしゃいますので、短期間雇用を創出する地域システムの構築が必要になってくるかと思います。指導や育成も今後の課題となると思いますけれども、区が現在どのようにお考えかをお知らせくださいとの意見を述べました。","respondent":"松山障害者福祉課長","answer":"区内にあります障害者就労支援センター「げんき品川」ですとか、各特別支援学校、仕組みとしてない状態です。一番必要なのは連携だと考えていますので、関係所管と連携しまして、検討を具体的にしていきたいと考えています。","id":"exchange-067"},{"speaker":"湯澤委員","kind":"質問・要望","question":"専門家の意見や、品川区でも週に２０時間以内の短期間雇用を求める障害者と、品川版の地域システムを構築していただきたいと要望いたします。そこでお尋ねしたいのですけれども、まず、この立正大学との活動に至った経緯はどういったものであったのか。","respondent":"松山障害者福祉課長","answer":"しかも大学生が関わってということで、授業の一環として単位が取れるという形での、３者ウィン・ウィンの関係のものだと認識しております。区といたしましては、こういったような取組を参考にしながら、今後とも連携を強めていきたいと考えております。","id":"exchange-068"},{"speaker":"湯澤委員","kind":"質問・要望","question":"ぜひ連携を取っていただきながら、障害者と健常者が触れ合う機会を今後もたくさんつくっていただくよう要望いたしまして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"西本委員","kind":"質問・要望","question":"親たちは、長期休業のときには、お弁当だけでは足りないし、ということで、おやつが何とかならないか、ということでいろいろと要望がありました。皆さん、おやつを駄目にしたのはどういう議論があったか、しっかり見ておっしゃっていただきたいなというように思っております。","respondent":"初貝保育教育運営担当課長、築山障害者施策推進担当課長、伊東子育て応援課長","answer":"以前から実施をしているところだったのですが、検出がされていないというところで、来年度に関しては休止というような形で予定しております。 こちらは現在２階に設置されております相談支援事業を１階に移しまして、相談しやすい環境づくりをするために実施するものです。… それを基に、今回、臨時給付金を支給したです。クレームというお話でしたけども、やはりなぜ私はもらえないのかというようなクレームはあったところです。","id":"exchange-070"},{"speaker":"西本委員","kind":"質問・要望","question":"「年収で計算するとこんな低いのに、何で私たちはもらえないの、おかしいんじゃないか」という、そういう意見をたくさん伺っております。それから、国なのか、その法整備というのを何か意見として言えるようなそういう仕組みになっていないのかどうか、お聞きしたいと思います。","respondent":"築山障害者施策推進担当課長、伊東子育て応援課長","answer":"障害児者総合支援施設は、地域生活支援拠点として整備した施設ですので、地域で生活できるよう支えていくための施設としていきたいと考えております。 今回、児童手当制度に基づいて実施したというところで、そういうことのご意見があったところではありますけども、区としては、国の制度に従っていったです。","id":"exchange-071"},{"speaker":"西本委員","kind":"質問・要望","question":"ですので、いろいろな要望があったり、生活環境が変わったりといろいろなものが出てくると思います。でも、忘れてはいけないのは、子どもにとっての利益というものをしっかりと考えていただいて、施策を講じてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"田中委員","kind":"確認","question":"この食の安全性を確認するためにも、検査方法を改善し検査を再開すべきと考えますが、見解を伺います。どういったときにもう一度再開ができるのかといったところも、併せて伺います。","respondent":"初貝保育教育運営担当課長","answer":"それはやはり様々な状況があるとは思いますけれども、そういったものを総合的に勘案しまして考えていくというような形になると思います。今どういう形というところは、明確には言えないというところではありますけれども、総合的に考えてというところになると思います。","id":"exchange-073"},{"speaker":"田中委員","kind":"質問","question":"再開などの様々な状況について伺っています。どういった状況になったら再開するのか、明確に、示すよう求めました。","respondent":"初貝保育教育運営担当課長","answer":"それはもう仮の話ということになってまいりますので、その辺りで再度検討して、来年度に関しましては休止をするというようなことで考えております。","id":"exchange-074"},{"speaker":"田中委員","kind":"質問・要望","question":"例えば、来年度、海洋に汚染水を流すといったことも国が示している中で、では国がそれを流した場合には、もう１回検討がされるのか。再開をするための検討がされるのかとか、そういうちょっと具体的にお知らせいただきたいのですけれども、いかがか尋ねました。","respondent":"初貝保育教育運営担当課長","answer":"区といたしましては、ちょっと繰り返しの答弁になってしまいますけれども、やはり状況を総合的に勘案しまして、そういった検討をするかどうかも含めて考えていくというような形になるかと思います。","id":"exchange-075"},{"speaker":"田中委員","kind":"質問・要望","question":"子どもたちの身体への影響というのを第一に考えていただきたくて、それで生活者ネットワークはこれまでずっと求めています。この状況の中でもまた再開については、その都度その都度と言いますが、だから具体的にどういうときに検査を再開するかをお知らせください。","respondent":"初貝保育教育運営担当課長","answer":"検査の再開については、やはり一つの状況を捉えて再開するかどうかということではなくて、やはり様々な状況を総合的に勘案して検討しなければならないというところなので、それはその時点で、区として総合的に考えるということで、検討しています。","id":"exchange-076"},{"speaker":"田中委員","kind":"確認","question":"では、すぐに再開できる体制は常に整っているということで確認できますか。","respondent":"初貝保育教育運営担当課長","answer":"区といたしましては、その状況を鑑みまして、総合的に考えてというようなところで考えておりますので、ちょっと繰り返しの答弁になってしまいますが、そういったところです。","id":"exchange-077"},{"speaker":"田中委員","kind":"質問・要望","question":"すぐに再開できる体制を整えていってほしいと強く要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"},{"speaker":"こんの委員","kind":"質問","question":"なぜ今作成なのか、どういう経緯で作成することになったのか、作成に至った背景も併せてお聞きしたいというふうに思います。いわゆる介護施設の従事者による場合というふうに理解をしておりますが、その理解で正しいかどうか、説明を求めました。","respondent":"宮尾高齢者福祉課長","answer":"基本的には各施設において実施をするものなのですけれども、区のほうで実際にプログラムをつくって、しっかりと虐待の対策を取ってまいりたいです。それから、対象となるところですが、委員のお見込みのとおり、こちらに関しては施設の従事者に対して、研修を行うというものです。","id":"exchange-079"},{"speaker":"こんの委員","kind":"意見","question":"どういう方針でどのようなガイドライン的なものを作成をしていく、そうしたものを作成して各事業所に示していく、どういったものをつくるのか。各事業所で行っていくものなのか、そこら辺、今後の展開についてもお知らせくださいとの意見を述べました。","respondent":"宮尾高齢者福祉課長","answer":"こういったものをプログラム化して、まずは令和４年度については、私どものほうで主催でやらせていただく予定です。研修に関しては、ちょっとコロナの状況もあるのですが、これは感染の状況等も鑑みながら柔軟に対応していければというふうに思っております。","id":"exchange-080"},{"speaker":"こんの委員","kind":"質問","question":"研修をするということは、こうした虐待の認定まではいかない事案に対しても、どのぐらい対応と未然防止になっていくものになるのか。私はこのプログラムがそういったものになっていってほしいという期待もあるわけですけれども、そうした区の対応力と、その辺を説明を求めました。","respondent":"宮尾高齢者福祉課長","answer":"やはりそれだけですと、受講する施設側としては、なかなか気が乗りにくいというようなところも実際にあろうかと思います。もちろん虐待はいけないという趣旨ではあるのですが、それと同時に、ぜひそういうテーマで受講を促していきたいというふうに思っております。","id":"exchange-081"},{"speaker":"こんの委員","kind":"質問・要望","question":"次の質問にまいります。その辺を教えていただきたいのと、それから事業費として３３０万円が計上されておりますが、その内訳などもお知らせください。","respondent":"櫻木生活福祉課長","answer":"特に年代を限定するものではないのですが、就労増廃止ということになりますので、比較的、３０代から５０代の方が想定になるのかなと考えています。内訳としましては委託費という形になっております。","id":"exchange-082"},{"speaker":"こんの委員","kind":"質問・要望","question":"この事業展開前と事業展開後、どれぐらいの、いわゆる再受給防止というか抑制ができるものと見込めるのでしょうか。もう一度お聞きしながら、どういったことで再開しないように抑制ができていくのか、その辺の目標なども教えてほしいと求めました。","respondent":"櫻木生活福祉課長","answer":"は支援体制につきましては、日常の各種手続支援等、なるべく安定した生活が送れるようなことの支援を行っていくことを考えております。基本的にはフォローに入った方々については、そのような状況にならないようにということで考えております。","id":"exchange-083"},{"speaker":"こんの委員","kind":"質問・要望","question":"４０％ぐらいの方が再開をしてしまっている現状を、目標をお聞きしましたが、それはちょっと見通せるようで見通せないのは理解できます。ひとり親支援の一環としての観点から、費用負担軽減のための支援をと考えるところですけれども、区のご見解を説明を求めました。","respondent":"伊東子育て応援課長","answer":"我々のほうのご相談の中では……。","id":"exchange-084"},{"speaker":"のだて委員","kind":"質問","question":"私からは、２４５ページの児童相談所、２４７ページの子ども家庭支援センターに関し、子どもの虐待について伺います。この子どもの虐待について、援助が必要なケースが区内でどれだけあると見込んでいるのか、伺います。","respondent":"山下子ども家庭支援センター長","answer":"令和３年１２月末の段階で、今年度末の段階でも、前年度よりは件数として少し増えてくるのかなというふうに考えているところです。対して支援が必要な児童の数というところで、いろいろな支援策を講じまして、そういったところで対応してまいりたいと考えています。","id":"exchange-085"},{"speaker":"のだて委員","kind":"質問・要望","question":"そんなあるとき親が事故に遭ってしまって、子どもを置いて１０日間入院をしたと。やはりこうした、子どもや親に、また保護者に、子どもの権利条約を周知するということが重要ではないかと思いますが、いかがか尋ねました。","respondent":"山下子ども家庭支援センター長","answer":"委員ご指摘のございました子どもの権利条約につきましては、各学校等でもいろいろ触れる場面があろうかというふうに認識をしています。","id":"exchange-086"},{"speaker":"のだて委員","kind":"質問・要望","question":"この子どもの権利条約を周知していくことが必要だというふうに思うのですけれども、いかがでしょうか。ほかの児童センターですとか、産前・産後の支援など、教育部門などとも連携をして周知をしていただきたいと思うのですが、いかがか尋ねました。","respondent":"山下子ども家庭支援センター長","answer":"母子健康手帳、新たな呼称がまた次年度からできますけれども、そういったところでしっかり周知というのは進んでいるかと考えています。今、委員ご指摘の通りの点がありますので、そういったところの周知啓発というのは取り組んでいく必要があるものと捉えてあります。","id":"exchange-087"},{"speaker":"のだて委員","kind":"質問・要望","question":"この中で、そういった状況に今、あるということで、区はその状況を認識しているかということも含めて原因をどのように考えているか、伺います。区立の児童相談所設置時には、同じ状況にならないようにしてほしいと求めましたが、いかがか尋ねました。","respondent":"山下子ども家庭支援センター長、加島児童相談所移管担当課長","answer":"今、委員よりございました東京都品川児童相談所の対応についてというところにつきましては。品川区子ども家庭支援センターとしましては、要支援児童の対応に当たっておりますので、引き続きそちらに注力してまいりたいと考えています。区立児童相談所が開設いたしました際も、子ども家庭支援センターとの両輪の体制を構築してまいりたいと考えております。","id":"exchange-088"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひそういった形でやっていただきたいというふうに思うのですけれども、援助がなかなかできていない部分があるのかなというふうに思うのです。今度、区立の児童相談所が設置をされた場合、現在の児童福祉司などの体制は、東京都の設置の状況よりも改善をされるかどうか、伺います。","respondent":"加島児童相談所移管担当課長","answer":"区立児童相談所の児童福祉司等の体制につきましては、法令の基準に基づき確保を図ってまいります。","id":"exchange-089"},{"speaker":"鈴木（博）委員","kind":"質問","question":"保育所における感染症対策についてお伺いいたします。２０２２年１月からの第６波流行における区内保育所の職員、園児の養成者数はいかがだったのか尋ねました。","respondent":"初貝保育教育運営担当課長","answer":"ただいまご質問いただきました、区内の保育園における新型コロナウイルスの陽性者数ですが、令和４年１月から３月２日までの数字ですけれども、園児が９１４名、職員が３５７名となっております。","id":"exchange-090"},{"speaker":"鈴木（博）委員","kind":"質問","question":"品川区の保育所における新型コロナウイルス感染予防対策は、状況の変化に応じて何か変わった点はあったのでしょうか。それとも同じ基本的感染対策が継続して行われているのか尋ねました。","respondent":"初貝保育教育運営担当課長","answer":"保育園での新型コロナウイルスに対する対応に関しましては、根本的な部分では対応は変わっておりません。これも以前からの対応になりますけれども、園児を小さなグループに分けて活動を行うなど、工夫を行っております。","id":"exchange-091"},{"speaker":"鈴木（博）委員","kind":"質問","question":"昨年の決算特別委員会でもデルタ株流行下での保育所の感染対策をお伺いしました。現在の保育所の役割と、保育所が直面している問題点などがあれば、併せてご説明をお願いいたします。","respondent":"初貝保育教育運営担当課長","answer":"保育園での濃厚接触者に関して、保育園の影響を最小限に抑えるために保護者へ伝えるなど、保育園でも速やかな対応を行っているようなところです。今後、引き続き保育課や保育支援課、あとは保健所などの関係機関と連携を取りながら対応してまいりたいと考えております。","id":"exchange-092"},{"speaker":"鈴木（博）委員","kind":"質問","question":"療養と登園、職員の労務など、濃厚接触者の特定対応以外にも様々なコロナ対策が現在必要になってきていると思います。保育所が様々な課題を抱えたときに、保育課、保育支援課ではどのようなスキームで支援をなさっているのでしょうか、もう一度お尋ねいたします。","respondent":"初貝保育教育運営担当課長","answer":"保育園での対応に関しても、もちろん案件によって相談内容も様々であります。個別に保育課や保育支援課が保健所と連携をしながら相談をして、そういった対応を現在行っているというような状況です。","id":"exchange-093"},{"speaker":"鈴木（博）委員","kind":"質問","question":"保育現場のための新型コロナウイルス感染症対応ガイドブック第３版によれば、フェイスシールドなどの目の保護具の使用が推奨されております。マスク以外の用具の実際の利用状況や備品の補充などについて、現在どのような状況で行っているのか、ご説明をお願いします。","respondent":"初貝保育教育運営担当課長","answer":"園児にとって触れ合いが大切ということで認識しておりますので、ガウンやエプロンなど、後の消毒を徹底して行っているというようなことです。様々な、必要な用品に関しては、国等の補助もありますので、そちらを活用しながら随時物品の補充というところに努めているところです。","id":"exchange-094"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"これに関連して、全国知事会が２歳以上の園児へのマスク着用を国として進めるように求めた提言が問題となりました。日本小児科学会の提言にもあるように、２歳未満児にはマスクは必要ないし、２歳児でもマスクの着用は慎重な対応を求める意見がほとんどです。","respondent":"初貝保育教育運営担当課長","answer":"今、厚生労働省のほうからも「保育所等における新型コロナウイルスへの対応にかかるＱ＆Ａ」が。今、そのような国の方針の内容も踏まえて、一律にマスクの義務づけを行うというような対応は行っていないというようなところです。","id":"exchange-095"},{"speaker":"鈴木（博）委員","kind":"意見","question":"発症予防効果は再び６０％から７５％まで回復するため、コロナワクチンの３回目の追加接種、ブースターショットが必要なことです。保育所の職員に対するコロナワクチン３回目の接種の進捗状況と、現在問題になっている点があれば、それも併せてご説明をお願いいたしますとの意見を述べました。","respondent":"初貝保育教育運営担当課長","answer":"全体の接種率の進捗に関しては把握しておりませんけれども、各自で優先接種枠に申込み、接種を進めているところと考えております。接種が重ならないような形の工夫をしながら、調整し、ワクチン接種を進めているというようなところです。","id":"exchange-096"},{"speaker":"鈴木（博）委員","kind":"質問","question":"このようなオミクロン株に抵抗力を持つ、人的な資源を何か有効に活用できる施策などはないものでしょうか。保育現場では、経験をどのように今後の保育スタイルと保育所における感染予防に活かしていくおつもりか、最後に質問したいと思います。","respondent":"初貝保育教育運営担当課長","answer":"今、委員のご指摘にございました、既にオミクロン株に感染したことがある方への対応です。保育園では新型コロナウイルスの対応を行う一方で、愛情を持った触れ合いを大切にした保育を行うなど試行錯誤をしながら保育を行っているところです。","id":"exchange-097"},{"speaker":"鈴木（博）委員","kind":"質問","question":"次に、病児保育について、決算特別委員会に引き続いてお伺いしたいと思います。今回はオミクロン株流行下での品川区の病児保育の各施設でのお預かり人数の推移、利用率についてご報告をお願いいたします。","respondent":"初貝保育教育運営担当課長","answer":"令和元年の実績には届かないものの、令和２年度と比較しまして大分多い数字になる見込みです。こころキッズケアでは１２４名で、約９％です。","id":"exchange-098"},{"speaker":"鈴木（博）委員","kind":"意見","question":"しかし、風邪症状を呈する軽症のオミクロン株の患者が利用してくるリスクは大きいと思われます。このリスクに対して各施設はどのような対策がなされていると、区は把握されているのか、ご説明お願いいたしますとの意見を述べました。","respondent":"初貝保育教育運営担当課長","answer":"受入れの際に、最終的にはそれぞれの医院の医師が各自で判断をしていただいて、受入れを実施しているというところで聞いております。その結果として、今、病児保育の中で新型コロナウイルスの感染症が確認できていないというようなところで捉えております。","id":"exchange-099"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今回の新型コロナウイルス感染症流行下において、病児保育は一定の役割を果たしたと、区は総括されているのか尋ねました。","respondent":"初貝保育教育運営担当課長","answer":"このたび、このコロナ禍でも一定数の受入れができたというところで、ニーズの確認、役割が再認識できたと確認しております。今後、新たな感染症が発生した際も、また関係機関と連携を取りながら、引き続き対応していきたいと考えております。","id":"exchange-100"},{"speaker":"鈴木（博）委員","kind":"質問","question":"その中で無認可保育所は今後どうなっていくと、区のほうは、今、お考えなのでしょうか。その展望についてお伺いします。","respondent":"若生保育支援課長","answer":"認証保育所、認可外施設などの施設についても、今後の状況によっては大きな影響を受けるものと捉えてあります。待機児童対策を取ってきた品川区といたしましては、今後も、区立園の在り方も含めて考えてまいりたいと考えています。","id":"exchange-101"},{"speaker":"芹澤委員","kind":"質問","question":"私からは２２３ページ、２３５ページ、時間があれば２５１ページの養育費相談支援事業についてお伺いをいたします。認知症についてお伺いをしたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"やはりそういうところから察すると、少なくともよい方向にはなかなか向かいにくいのかなという現状で受け止めているところです。国が言っている、高齢者の方のおおむね６人に１人というところで、品川区においてもほぼ同様の分布かなというふうに分析をしています。","id":"exchange-102"},{"speaker":"芹澤委員","kind":"質問・要望","question":"どういったやり方で数字を捉えているのかが分かれば、後で教えてください。この認知症検診、年齢を絞って実施をしていくというふうにも伺っていますが、このやり方を教えていただきたいのです。","respondent":"宮尾高齢者福祉課長","answer":"対象となる方には個別に、案内ですとか接種券ですとかそういったものを一式、郵送でご自宅に送らせていただくということを考えているところです。今時点で考えているのは、区内の、その辺はどういう形で対応できるかというのは今後検討してまいりたいというふうに思っております。","id":"exchange-103"},{"speaker":"芹澤委員","kind":"質問・要望","question":"検診を受けた際には、もうそこで認知症かどうかというのが、診断をされるというような感覚でよろしいのかをお聞かせほしいと求めました。これから国単位で認知症のイメージを変えていかないといけないというふうに伺っていますが、区で今考えられている取組があれば説明を求めました。","respondent":"宮尾高齢者福祉課長","answer":"我々は鑑別診断と呼んでおりますが、そちらのほうにおつなぎを、ご案内をしていきたいというふうに思っております。少しでも垣根を低くというところで、物忘れ検診ということで、名称を考えさせていただきたいというふうに思っているところです。","id":"exchange-104"},{"speaker":"芹澤委員","kind":"質問","question":"認知症サポーターについてもお伺いしたいと思います。この商店街は、地域ぐるみのサポーター制度につながるのかなと思うのですが、そこについてご見解を説明を求めました。","respondent":"宮尾高齢者福祉課長","answer":"ただし、一度過去に受けた方に対するアプローチというのですか、そこに関してはちょっと今後の検討課題とさせていただければと思います。","id":"exchange-105"},{"speaker":"芹澤委員","kind":"質問","question":"続いて、認知症カフェについてもお伺いをします。多分医療器具が必要ない検診というふうにも伺っていますので、何かスタイリッシュに認知症検診を受けるというか、ちょっと格好いいような。","respondent":"宮尾高齢者福祉課長","answer":"今、これまでのなじみの度合いですとか、そういったことも考えながら検討していきたいと思います。それから、そこも、やり方も含めてどういった方法が受診率の向上につながっていくかというところはしっかりと考えてまいりたいと思います。","id":"exchange-106"},{"speaker":"芹澤委員","kind":"質問・要望","question":"最後、医療的ケア児についてちょっと駆け足でお伺いをいたします。現状、ほかに候補がどういったものがあるのかをお聞かせほしいと求めました。","respondent":"松山障害者福祉課長","answer":"委員お尋ねの、２か所目の児童発達支援センターの整備検討ですが、今のところ、候補地といたしましては大原児童センターということを考えております。","id":"exchange-107"},{"speaker":"芹澤委員","kind":"意見","question":"大原児童センターが今、１つ挙がっていらっしゃるということで分かりました。この３階建ての１階にインクルーシブひろばベルがあって、この窓口が一つで、ぜひこの大原児童センターで前向きにご検討ほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-108"},{"speaker":"高橋（し）委員","kind":"質問","question":"それで、これまで２３区が一体となって取り組んできた区立児童相談所開設、その一体化を少し乱すというか、そういう状況ではないでしょうか。区長会としても、２３区一体となって進めてきたことに関してどのようなご意見が出たのか尋ねました。","respondent":"加島児童相談所移管担当課長","answer":"児童相談所の管轄区域人口を１所当たり５０万人とするという人口参酌基準を定め、それを踏まえての動きだという説明を受けております。","id":"exchange-109"},{"speaker":"高橋（し）委員","kind":"質問","question":"このままでは一枚岩で進まない可能性があるのではないでしょうか。区立児童相談所という、将来像が非常に見えにくくなってきていますが、その点についてはいかがか尋ねました。","respondent":"加島児童相談所移管担当課長","answer":"ただ、サテライトオフィスの設置を表明いたしました区も、必ずしも児童相談所を設置しないと表明したわけではございません。区部の児童相談体制の在り方を検討すると伝えてきておりますので、特別区における思いというのを伝えてまいりたいというふうに考えております。","id":"exchange-110"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"しかし、情報推進課からパソコンを借りてきて、それで現場の保育園で使うと伺っています。この認識でよろしいか尋ねました。","respondent":"初貝保育教育運営担当課長","answer":"ご指摘のとおりＷｅｂｅｘというところでは、情報システムの部門から借りたパソコンですけども、そちらでしたらホストが可能です。Ｚｏｏｍに関しては、各園のネットワークに接続できるパソコンであれば、ゲストであれば入れるというようなところです。","id":"exchange-111"},{"speaker":"高橋（し）委員","kind":"質問","question":"一方、公立の小中学校にはＺｏｏｍのアカウントが付与されて、それで飛躍的に教育活動の幅が広がっています。保育園・幼稚園では、そういった状況に関して、そういった今のネット環境についてどのようなお考えをお持ちか尋ねました。","respondent":"初貝保育教育運営担当課長","answer":"区立の保育園・幼稚園に関して、やはり今は借りてくればできるけれども、その場ではすぐにはできないという状況なのです。区全体でいうとセキュリティ等々問題もありますので、情報システムの部門と連携を取りながら、今後の方向を検討していきたいと考えております。","id":"exchange-112"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、情報推進課としては、このような、例えば４０園あるわけです。貸出し用のパソコンが９台か１０台しかないという、そういうような状況ですが、公立小中学校のＺｏｏｍみたいな体制は不可能なのか尋ねました。","respondent":"堀越企画部長","answer":"そういう状況を見ながら、便利に使えるように、そういう検討もしていきたいというふうに思っているところです。今は、セキュリティの理由から使えないという状況ですので、技術の状況を見ながら、今後検討していくと、そういう考え方です。","id":"exchange-113"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ぜひ検討して、保育教育活動の幅が広がることを要望いたします。決算特別委員会で要望したように、５歳児の方々に学校心理士が、全て巡回保育が行けるようなことになりました。","respondent":"若生保育支援課長","answer":"今後も就学時につなげる対応を充実してまいりたいと思います。","id":"exchange-114"},{"speaker":"若林委員","kind":"質問","question":"２３５ページの認知症高齢者支援事業に関連しているところをお聞きします。どういう変化を起こそうとしているのか、いろいろな角度があると思いますけれども、まずはそこをお聞きしたいと思います。","respondent":"菅野高齢者地域支援課長","answer":"認知症施策では、共生と予防を両輪として政策を進めることとしておりまして、現在、高齢者地域支援課では介護予防事業を運営しております。","id":"exchange-115"},{"speaker":"若林委員","kind":"質問・要望","question":"いろいろありますけれども、これのネーミングは、今ご答弁いただいた所管のほうで行われるというようなことで確認をしていいのかどうか。この新生寿会、また、きのこエスポアール病院の専門的な認知症ケアのノウハウというものはどういうものなのか、お知らせほしいと求めました。","respondent":"宮尾高齢者福祉課長","answer":"３月いっぱいは私どものほうで所管をさせていただいて、責任を持って４月以降、高齢者地域支援課のほうに引継ぎをする予定です。ミーティングセンター３か所分の開設支援経費を予定しておるのですが、今、調整を行っているです。","id":"exchange-116"},{"speaker":"若林委員","kind":"質問・要望","question":"商店街、ぜひそういったところとの交流とか貢献とかということもぜひ考えていただきたいなという、何かご見解があれば。２点お願いいたします。","respondent":"宮尾高齢者福祉課長","answer":"ややもすると、エリアですとか運営主体によって知識にばらつきというのが生じるというところも、私どもも課題として認識をしております。福祉カレッジ等を活用いたしまして、こちらにつきましてもしっかりと推進をしてまいりたいというふうに考えているところです。","id":"exchange-117"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それから２２９ページの障害児者総合支援施設、それから、２３１ページの入院中の紙おむつ代助成事業について伺いたいと思います。なぜ世帯の収入とするのか、この利用料は選定するべきではないかと思いますが、いかがか尋ねました。","respondent":"松山障害者福祉課長","answer":"新年度の対象に変更があるかということですが、対象者についてもまだ引き続き検討しておりますので、新年度については対象はこのままにしています。利用料金も同様に、現在検討を行っているところです。","id":"exchange-118"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"ずっと検討が続いているのですけども、なぜここまで長引いているのか。これをぜひ対象になるよう拡大してほしいということで、なぜここまで検討が長引いているのか、その点について説明を求めました。","respondent":"松山障害者福祉課長","answer":"突然の疾病リスクが起こりやすく、障害者と高齢者のみの世帯は電話等での通報ができないリスクが高いということが理由です。現在も事業の整理を行っておりますので、まだ引き続き検討はしていくです。","id":"exchange-119"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２０１８年度までに国から設置を求められていたのですけど、品川区は会議が始まったのかどうなのかというのをちょっと伺いたいのです。もう１点、実際に１月から始まったのか、どの施設で始まっているのかを伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"医療的ケア児等支援関係機関連絡会の開催についてですが、２月に実施予定で組んでおりましたけれども、書面開催という形にしています。森山リハビリテーションクリニックで、今年の１月から開始しておりますが、病床が空いたときに、実際にご本人の状態によってお預かりするです。","id":"exchange-120"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１０月には事業者が変わるわけですけれども、品川区の障害者福祉を今後どう展開していくのかという点からも、いかがでしょうか。「私たちのことを私たち抜きに決めないで」と、当事者の視点からも検証してほしいと求めましたけれども、いかがか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"地域生活支援拠点検討会を実施しまして、その中で検討して、必要な機能の充実を図ることを明記しております。障害福祉計画推進の中で、様々な方向性について検討してまいりたいと考えております。","id":"exchange-121"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"事業者が変わるわけですけれども、職員がそのままどれぐらい残るのか、今の事業者から今度新たな事業者に変わるに当たって、今の働いていらっしゃる方が次の事業者のところに移っても職員がそのまま残るという割合がどれくらいあるのかについてもお聞かせほしいと求めました。","respondent":"築山障害者施策推進担当課長","answer":"職員の状況ですが、法人の人事に関することですので、こちらでは回答は差し控えさせていただきたいと思います。","id":"exchange-122"},{"speaker":"西村委員","kind":"質問","question":"運動・体力向上事業より、令和２年度から実施していただいているオリンピック・パラリンピックレガシーの取組について伺ってまいります。スポーツ体験の拡充、ボッチャセットの全園配備が次年度行われますが、実施が区立保育園だけの理由と私立園の検討があるのかどうかお伺いいたします。","respondent":"若生保育支援課長","answer":"東京２０２０大会のレガシーということで、ボッチャセット等の配付という事業に関して、私立保育園でも実施の予定があるのかというご質問です。区立園のように一律に実施するということは難しいところではありますけれども、今後とも区として働きかけてまいりたいと思います。","id":"exchange-123"},{"speaker":"西村委員","kind":"質問","question":"スポーツはホッケー、ボッチャ、ラグビーとありますけれども、これは各保育園が選ぶものだと思います。ホッケー、ボッチャはオリンピック・パラリンピックと区の関わりがありますが、ラグビーが導入された理由を併せて説明を求めました。","respondent":"初貝保育教育運営担当課長","answer":"令和４年度の実施予定としてはホッケーが８園、ボッチャが９園というような、今のところの予定です。やれる競技、やれない競技というところを一定考えた上で、ラグビーというところを選択したというようなところでおります。","id":"exchange-124"},{"speaker":"西村委員","kind":"質問","question":"いろいろなスポーツに触れてほしいと思う一方で、せっかく楽しいと思えたスポーツを私としても長く楽しんでほしいと考えます。日常的に公園でも遊んでおります野球、バスケットボールなどほかの競技でもいいのではないかと考えますが、いかがか尋ねました。","respondent":"初貝保育教育運営担当課長","answer":"競技に関しては今、委員ご指摘のとおり、様々な競技の幅というところが考えられるかもしれません。どういった形だったらやれるのかとか、そういったところを総合的に考えまして、今後の展開を様々検討していきたいと思います。","id":"exchange-125"},{"speaker":"西村委員","kind":"提案","question":"子育て支援事業全般から夢食堂事業という取組をご提案させてほしいと求めました。私がお伺いした店舗はもんじゃ焼き・鉄板焼きのお店でして、子どもたちに焼いてもらい、食事後の配膳は子どもたちが自分で行っておりましたとの意見を述べました。","respondent":"廣田子ども育成課長","answer":"行政ではなかなかできない、地域や個人ならではの柔軟な支援かと思います。行政も入り、地域の方も入って意見交換をしながら、今後の在り方については考えていきたいと考えます。","id":"exchange-126"},{"speaker":"西村委員","kind":"質問","question":"逆に今だからこそ、困っている人に手を差し伸べないと手後れになるかもしれないという思いからだと伺っております。コロナ禍で運営に苦慮されていた点もあると思いますが、昨年度の実績と、この地域子育て支援グループのコロナ禍の現状について伺います。","respondent":"廣田子ども育成課長","answer":"令和３年６月から開始したのですけれども、１月末現在で９団体の申請がありまして、障害や難病などの家族の会など６団体に助成したところです。","id":"exchange-127"},{"speaker":"西村委員","kind":"質問・要望","question":"すみません、私も少し確認をさせてほしいと求めました。少し派生しますが、修学旅行を引き受ける宿とか施設でも、児童のアレルギー対応に大変苦慮をされているということは伺ったことがあります。","respondent":"廣田子ども育成課長","answer":"その当時は１５区ぐらいあったのですけれども、いずれも保護者会・父母会が実施しているというような内容でございました。場所によって、食の支援というとアレルギーもありますので、まずは調査をして分析をしていきたいというところで考えているところです。","id":"exchange-128"},{"speaker":"西村委員","kind":"質問","question":"続きまして、保育園に関して伺ってまいりたいのですが、先ほど募集状況のご報告もありました、保育園の申請に関して伺いたいと思います。品川区が８園全て記載することを必須としていない理由を説明を求めました。","respondent":"立木保育課長","answer":"保育園の入園に関しましては、それぞれご家庭のご事情がある中で、ご希望される園の中で入園が決まっていただければいいという形で、ご利用される方に沿った入園制度を組み立てているです。","id":"exchange-129"},{"speaker":"西村委員","kind":"質問","question":"「どうして」と伺うと、「そこの園しか行きたくなかったから」と、そういったような個々の事情もあると考えています。補正予算の審査でも質問させていただきましたが、一区切りとして捉えてはどうかと考えています。","respondent":"立木保育課長","answer":"数のほう、それからそれに合わせて質の確保、維持・向上というところもやってまいりました。より一層質の向上や多様なニーズへの対応など、ニーズの動向を注視するとともに、今後も区立園のありようも含めて検討をしてまいりたいと思います。","id":"exchange-130"},{"speaker":"西村委員","kind":"質問・要望","question":"一つ要望させていただきたいのですが、児童センターの職員の方々など、何か感謝の気持ちを表すことができないかなというふうに考えております。ちょっと難しい質問かもしれないのですが、何かそのような機会をつくっていただけないかなと思うのですが、ご答弁お願いできますか尋ねました。","respondent":"若生保育支援課長","answer":"昨今、区からの感謝をお届けするという趣旨で、保育従事者の皆様へ感謝のお手紙とともに記念品をお届けする取組も行ってまいりました。区立・私立含めまして、きめ細かく状況を日々聞き取っていく中で、できる対応を行っていきたいと考えています。","id":"exchange-131"},{"speaker":"西村委員","kind":"意見","question":"全ての園を数えると大変な職員の数になると思いますが、ぜひとも皆様にそういった感謝の気持ちを伝えられる機会をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-132"},{"speaker":"藤原委員","kind":"質問・要望","question":"２６９ページ、生活保護費で、これ課長、具体的な例を挙げて伺いますが、今、何十年も会わなかった親戚の方から、その方が亡くなられて遺産が入る。２１５ページの、しあわせ創設プランと金額が同じなのですけれど、これでいいのか尋ねました。","respondent":"櫻木生活福祉課長、寺嶋福祉計画課長、宮尾高齢者福祉課長","answer":"遺産の状況によってはそのまま廃止になるということがあります。その点については、ケースワーカーを通じて… 重層的支援体制整備の検討です。こちら、そこのところで「しあわせ創設プラン（重層的支援体制整備－検討）」というふうに記載をさせていただきました。 来年度の品川介護福祉専門学校の入学予定者数ですが、現時点で１４名というふうに聞いております。","id":"exchange-133"},{"speaker":"藤原委員","kind":"質問・要望","question":"こういうふうに継続をしていただいて、給料面の改善をしていただきたいと私は思うのですが、改めてそこをお伺いします。困難な課題、これは、ここ保健所とか男女共同参画センターでもできないということで、こういう形でしあわせ創設プランをつくったのか尋ねました。","respondent":"宮尾高齢者福祉課長、寺嶋福祉計画課長","answer":"臨時の介護報酬の改定を予定しているというところですので、半年で終わってしまうということではないのかなという捉え方をしております。例えば来年度は、選んでいただける保険者になるかというところで… これが部署が２つ、３つというふうになってきますと、なかなかその連携の取り方が難しくなってくるというところがあります。","id":"exchange-134"},{"speaker":"藤原委員","kind":"質問・要望","question":"そこを変えていっていただきたいという思いで、何回も何回も何回も質問させていただいているので、その辺について改めてお伺いします。期待していますので、その辺も含めて答弁をお願いします。","respondent":"寺嶋福祉計画課長、宮尾高齢者福祉課長","answer":"深掘りされたときに対応ができないということ、今考えている方法としまして、検討しています。 その中で、これはやはり、制度面でも財政面でも非常にクリアすべき課題が多いというふうに認識をしております。９月までの補助金の対応、それから１０月以降の臨時の報酬改定、研究をしていきたいというふうに考えているところです。","id":"exchange-135"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"だからこそ、命と健康を守るという本来の役割を果たすためにあらゆる努力をして軽減に踏み出すべきだということも、繰り返し求めてきました。ですので、区でできることなのになぜやらないのか、伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"７億円、８億円というような形で、投入させていただいているところです。","id":"exchange-136"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それを元に戻すだけでも大きな軽減につながるということで私たちは求めています。この平成２２年、もうとにかく３０億円台を入れてきた、そのときに戻せるべきなのになぜやらないのかというのを聞いているのです。","respondent":"池田国保医療年金課長","answer":"令和２年度、令和３年度と同じように、多くの一般財源を投入させていただいているところです。","id":"exchange-137"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、私たちは、こんなに値上げされては本当にもう負担の限界だということで、さらなる法定外の繰入れをということで求めているのです。それから短期証、資格証、そして差押件数をそれぞれ伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"令和２年度につきましても、実際に令和３年度につきましても、２億円程度の執行停止の額が見込まれているところです。差押についてですけども、令和２年度の差押の数ですが、２０７件という形で差押を実施させていただきました。","id":"exchange-138"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今年度は１.９億円ということで、激変緩和の措置を約束どおり入れるように求めるべきではないでしょうかということをお聞きしたいと思います。年金収入２００万円の方が窓口負担２割になるということ、区はどのように考えているでしょうか、説明を求めました。","respondent":"池田国保医療年金課長","answer":"この３万４,７８１人のうち、２割負担になる方が９,２２０人、１割負担の方が残りの２万５,５６１人というような形になる予定になってあります。国のほうの施策の中で、２割負担というものが今年の１０月から実施されるですので、致し方ないというふうに考えているところです。","id":"exchange-139"},{"speaker":"石田（ち）委員","kind":"質問","question":"２割負担になることで、受診を控えて薬も減らす、こういう人が生まれるのは容易に想像できることではないでしょうか。国も区でも、こういうことにも矛盾していくのではないかと思いますけれども、いかがか尋ねました。","respondent":"池田国保医療年金課長","answer":"初年度に当たり７００円ということでの負担が軽減になりまして、翌年度に８００円という形で、国からの話が出ているかと思います。今回２割負担に始まるということで、６００円ほどの負担が軽減されているということで、ですからこれでいきたいと考えています。","id":"exchange-140"},{"speaker":"大沢委員","kind":"質問","question":"２４７ページ、児童相談所、ヤングケアラー、そして２３０ページ、高齢者福祉費、順不同でお伺いをします。１点だけ、当たり前のようでまだこの委員会では語られていないような気がしますので、改めて現状について伺いたいと考えています。","respondent":"加島児童相談所移管担当課長","answer":"今年度新たに人事部門と協議いたしまして、任期付採用に取り組み、児童相談所業務に係る豊富な知識、経験を持つ職員の確保に取り組んでまいりました。今後も最大限、人材の確保、育成に取り組んでまいります。","id":"exchange-141"},{"speaker":"大沢委員","kind":"質問","question":"以前、人材の確保に困難を要しているということで伺ったことがありますけれども、そこについてどのような工夫をされ、どのような考えの下に、人材の確保の取組をされているのか、説明を求めました。","respondent":"加島児童相談所移管担当課長","answer":"こちらは児童福祉司につきましては、おおむね５年程度の経験、児童心理司に当たってはおおむね１０年と言われているところです。経験を持つ職員、開設準備に当たっては子ども家庭支援センターを中心に専門職の育成を担える、そういった職員の確保に取り組んでいるところです。","id":"exchange-142"},{"speaker":"大沢委員","kind":"質問・要望","question":"いつもの団塊の世代についてを中心に伺いたいと思うのですけれども、起こるだろう問題を予想してどのように備えていくかが必要であると思うのです。どのような問題があってどのようにそれをやっていくか、備えについて、簡単に概要があれば教えてほしいと求めました。","respondent":"宮尾高齢者福祉課長","answer":"介護認定をされる方の年齢はやはり７５歳を境に大きく、皆さん介護保険をお使いになられて、そうすると給付費の上昇が見込まれるです。定着、育成支援、こういったところも今からしっかりと備えておく必要があるというふうに捉えているところです。","id":"exchange-143"},{"speaker":"大沢委員","kind":"意見","question":"まさに団塊の世代、日本の人口のボリュームゾーンでありまして、ここのところの生活と住まいの問題が重要になってくると思います。住まいにおきましては、そこのところはどういうふうに捉えられて、どういうふうにお考えになっていらっしゃいますかとの意見を述べました。","respondent":"宮尾高齢者福祉課長","answer":"自宅での生活を、暮らし続けていることを支援するということを根本の考え方に置いて、介護保険のサービスを展開してきているところです。に様々、こういうことをしっかり捉えて今後も政策を推進してまいりたいというふうに考えております。","id":"exchange-144"},{"speaker":"大沢委員","kind":"意見","question":"ちょっと調べたところによると、東京都で、都市型軽費老人ホーム、これを推奨しているという話を聞きました。本区においては昨年の３月より、当然理由があるのでしょうけれども、それについて説明を求めました。","respondent":"宮尾高齢者福祉課長","answer":"特に、軽費老人ホームにつきましても、例えば区のほうで設置をしないとか、そういうことを決めている考えというところはございません。どういった類型のものが適しているかというところは、これはもうトータルに、総合的に考えていく必要があるというふうに思っております。","id":"exchange-145"},{"speaker":"大沢委員","kind":"質問","question":"取扱いがいろいろと違ってくると思うのですけども、そこのところは、今ご一緒に考えられた答弁ではないですよね。もう１回お願いします。","respondent":"宮尾高齢者福祉課長","answer":"これを選択しないという考え方ではなく、短所があろうかと思いますので、そういったところを総合的に考えて整備等を考えて検討していく必要があるというふうに考えております。","id":"exchange-146"},{"speaker":"大沢委員","kind":"質問","question":"平成２１年に群馬県渋川市で起きた、都市型が都のほうで推奨している、品川区ではやはり政策がいろいろあろうかと思います。そこの政策についての、１年経っていますけれども、政策についての取扱いや俎上に上げてない部分がありましたら、考えがありましたら説明を求めました。","respondent":"宮尾高齢者福祉課長","answer":"様々、類型がある中で、長所、短所をしっかり研究してまいりたいと思います。","id":"exchange-147"},{"speaker":"塚本委員","kind":"質問・要望","question":"今年の１月から、私としても要望をしてまいりましたし、ベッドが空いたときに当事者の病状によって受け入れていくというようなお話でした。予算額としては９２万４,０００円というところで、これは定員みたいなものは設定されているのでしょうかということをまず最初にお伺いします。","respondent":"松山障害者福祉課長","answer":"障害者医療ショートステイ事業の利用定員ですけれども、特に利用定員という考え方ではなく、やはり医療機関の空き病床を利用するため、ご利用につきましては最大７日間と見込んでおりまして、年間８人程度をまずは想定しようです。","id":"exchange-148"},{"speaker":"塚本委員","kind":"質問・要望","question":"致し方ない部分があると思いますが、そのベッドの空きというところでいうと、そのプライオリティみたいなものというのは。プライオリティというか、両方の要望が同じ日にあったときに、その辺をどう調整していくのかみたいな話というのはある程度固まっているのか尋ねました。","respondent":"松山障害者福祉課長","answer":"障害者医療ショートステイ事業のご利用者の調整についてです。リハビリを提供するという形を医療機関が考えておりまして、できるだけこちらのほうを優先していただけるようお願いしているところです。","id":"exchange-149"},{"speaker":"塚本委員","kind":"意見","question":"第６期品川区障害福祉計画、その地域で支えていくために地域生活支援拠点等の整備といったところが、この計画の中に述べられております。現状、区内でこういった強度行動障害をお持ちの方についての受入れ状況というか、受入れの体制というか、そういったところを説明を求めました。","respondent":"松山障害者福祉課長","answer":"強度行動障害がある障害者の方へのショートステイの受入れ体制です。区内につきましては、区立かがやき園、それからかもめ園のショートステイで対応しています。","id":"exchange-150"},{"speaker":"塚本委員","kind":"質問","question":"保護者側の、そういったところでなかなか受入れの調整というところが難しいことがあるのではないかなというふうに、推察をいたします。区としてここら辺の受入れについての様々な調整というか、こういったところについて、どういった認識をお持ちか、お伺いいたします。","respondent":"松山障害者福祉課長","answer":"委員ご指摘のとおり、その方の状態ですとか、あるいは同日、同じくショートステイを利用される方の状況等を考慮して、難しい場合もあります。なかなか区内だけでは難しく、都外だったりする、こちらのほうで探して、何とかショートステイで当該施設が対応する場合もあります。","id":"exchange-151"},{"speaker":"塚本委員","kind":"質問","question":"やはり都外とかにどうしてもなってきてしまうというのが今、実態のようなのです。でき得るものなのかどうかというところでの施設的な整備については、いかがお考えか、お伺いいたします。","respondent":"築山障害者施策推進担当課長","answer":"ハード面では、ぐるっぽのショートステイで、強度行動障害の方も想定した造りとなっておりますので、今後の新たな体制の中で受入れができるよう進めてまいりたいと考えています。","id":"exchange-152"},{"speaker":"塚本委員","kind":"質問・要望","question":"きめ細かく、こういった障害の特性に合わせた施策の展開というのをお願いしたいということで、この質問を終わりにいたします。利用した方々からの、効果というのですか、どの程度この徘回というものに対応がなされるものなのかということで状況を説明を求めました。","respondent":"宮尾高齢者福祉課長","answer":"ご登録をいただいている方が４６５人、同じく１月末現在で、３１人の方にご利用をいただいているところです。あるいはＧＰＳ、やはりご家族の方からは、こういったものがあると安心感が違うねというようなお声を多数いただいているところです。","id":"exchange-153"},{"speaker":"塚本委員","kind":"質問・要望","question":"ＧＰＳのほうが３１人ですか。そういったことにも一つ寄与する部分もあるかなとも思うのですが、どのようなことがなされるべきというふうにお考えか、説明を求めました。","respondent":"宮尾高齢者福祉課長","answer":"それから、そのご家族と地域との関係ですけれども、やはり、そういったご家族の心労に、きちんと私どもは寄り添う必要があると考えています。在宅介護支援センターがあり、そういったいろいろな場で、そういったお声をきちんとお聞きする必要があるというふうに捉えております。","id":"exchange-154"},{"speaker":"塚本委員","kind":"質問・要望","question":"ちょっと時間があまりもうないので要望だけにしておきたいと思いますけれども、この方が今１万８,０００人以上登録されているというところで、ひとつこの活用みたいなこともご検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-155"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私は２２９ページ、障害児者総合支援施設と、２６７ページ、私立幼稚園、時間があれば保育園について伺います。現事業者を３月いっぱいで辞める職員がそれなりにいるというふうに伺いました。","respondent":"築山障害者施策推進担当課長","answer":"生活介護や就労継続支援Ｂ型と、地域活動支援との混合的な事業の実施についてですが、各事業はそれぞれ単独して実施するですので。重度心身障害者の方に対応できるよう、職員の外部研修を予定しておりまして、外部研修を通じて育成のことも図っているところです。","id":"exchange-156"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それから、「待機者が多くて、待機の期間も長くて、どうやって解決してくれるの」ということも伺いました。重度の話がちょっとあったけれども、そこら辺のところをどうしていくのか、お伺いしたい。","respondent":"築山障害者施策推進担当課長","answer":"重度心身障害者等の受入れにつきましては、新たな体制において、医療的ケア、重度心身障害者を対象として受入れを図っていく予定です。子ども発達相談室と障害児相談支援事業の事業連携を強化しまして、相談から支援への流れを見直し、インテーク期間の解消を図っていく考えです。","id":"exchange-157"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"先ほども西本委員への答弁で、１階は人が下りてきて相談とか受付とかそんな感じになると、地下の浴室とかいうのは伺いました。これの考え方をぜひ教えてほしいと求めました。","respondent":"築山障害者施策推進担当課長","answer":"期間につきましては、令和４年度に設計も含めての予定となっておりますので、その中で利用者に配慮した工程を考えたいというふうに考えております。その中で、利用者が事業を実施できるよう、事業および設備の設計に関して、見直していきたいと考えております。","id":"exchange-158"},{"speaker":"石田（秀）委員","kind":"質問","question":"２園の個別事情もありましたが、それを差し引いたとしても、３５０名程度の減となっていたのかなと考えています。この減の要因をどう捉えていらっしゃるのか、まずそれを伺いたいと思います。","respondent":"若生保育支援課長","answer":"区のほうでもなかなか、周知というところで現状足りてない部分はあるのかなというところは認識しています。そういったような対策も必要ではないかと考えているところですので、区としてできることをまた検討していきたいと考えています。","id":"exchange-159"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それは、最後にここだけは思っていただきたいのは、区も幼稚園の団体から要望を毎年伺って支援していただいていると考えています。我々も要望を伺い、区に伝えてきております。","respondent":"若生保育支援課長、渡辺委員長","answer":"現状でも東京都の支援とともに、なかなか十分ではないところについては、今後も検討してまいりたいと考えています。乳幼児教育の重要な部分を担っていただいていると認識していますので… 以上をもちまして、本日予定の審査は全て終了いたしました。","id":"exchange-160"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/201716?Template=document&Id=1150#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":126041,"voices":361}}]);
